/* ÇEVİRİ ru · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ru","olay",{
"KRONOLOJI_COK_ARABISTAN2:1538-01-01:0":{"b": ["Хадрамаут стал османским санджаком — внутреннее управление осталось у вождей Касири", "d80f8d20"], "d": ["Хадрамаут, перешедший под османское управление во время индийского похода Хадыма Сулейман-паши, был организован как санджак в составе Йемена. Однако внутри Хадрамаута управление фактически удерживали вожди племени касири; османская власть ограничивалась побережьем и податной связью.", "93dd8a13"]},
"KRONOLOJI_COK_ARABISTAN2:1659-01-01:0":{"b": ["Зейдитский имам аль-Мутаваккиль Аллах вторгся в Хадрамаут — султанат Касири подчинён имамату Йемена", "21ad9c85"], "d": ["После ухода османов из Йемена в 1635 году зейдитский имамат усилился и при имаме аль-Мутаваккиле Аллахе отправил армию, которая вторглась в Хадрамаут. Так власть Касири во внутреннем Хадрамауте почти полвека оставалась подчинённой йеменскому имамату; когда в первой половине XVIII века влияние имамов и Касири ослабло, управление вновь перешло к местным племенам.", "e5a06ff4"]},
"KRONOLOJI_COK_ARABISTAN2:1835-01-01:0":{"b": ["Абдаллах ибн Рашид отобрал эмират Хаиль у семьи Ибн Али — основан эмират Шаммар (Рашидидов)", "357cc1a0"], "d": ["Абдаллах ибн Рашид из ветви Абде, крупнейшей ветви племени шаммар, в 1835 году выиграл борьбу, начатую им вместе с братом Убейдом против семьи Ибн Али, правившей Хаилем, и захватил эмират. Благодаря положению на торговом и паломническом пути между Месопотамией и Хиджазом Хаиль стал центром власти Рашидидов над Джебель-Шаммаром, продлившейся до 1921 года.", "dc0300b5"]},
"OLAYLAR:1299-01:0":{"b": ["Основание Османского бейлика", "9f0b7c0a"], "d": ["Начало самостоятельных действий Осман-гази из рода кайы в окрестностях Söğüt и Доманича традиционно считается началом основания Османского государства; некоторые историки видят подлинный поворотный пункт в победе 1302 года при Бафее. Благодаря положению на византийском порубежье бейлик быстро набрал силу в набегах гази. В обстановке распада сельджукского наследия Осман-гази собрал вокруг себя ахи, гази и кочевых тюркменов; связь с шейхом Эдебали считается основой духовной легитимности бейлика. В тот же день присоединены также: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Завоевание Бурсы", "98c727fa"], "d": ["Бурса, находившаяся в многолетней блокаде, сдалась Орхан-гази, руководившему заключительным этапом осады; город стал первой большой столицей бейлика. Согласно преданию, весть о завоевании дошла до лежавшего на смертном одре Осман-гази; по его завещанию он был погребён в Бурсе. Город вскоре украсился мечетями, имаретами и медресе и стал образцом раннего османского градостроительства.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Завоевание Изника", "a846a811"], "d": ["Изник (Никея), один из важнейших центров Византии в Анатолии, после победы 1329 года при Пелеканоне потерял надежду на сопротивление и сдался Орхан-гази. Здесь было основано первое османское медресе, а такие учёные, как Давуд-и Кайсери, начали преподавать; город стал научным центром раннего периода. Церковь Айя-София была превращена в мечеть, что явилось ранним примером традиции завоеваний.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Завоевание Измита", "06a35035"], "d": ["С падением Измита (Никомедия) последняя значительная крепость Византии на анатолийском берегу также перешла под османское управление; весь полуостров Коджаэли до самого берега, противоположного Константинополю, стал османской землёй. Таким образом бейлик овладел всем южным и восточным побережьем Мраморного моря и подготовил основу для перехода в Румелию.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Крепость Çimpe — переход в Румелию", "c2f0a07d"], "d": ["Сулейман-паша, сын Орхан-гази, сделал крепость Çimpe, отданную ему во время византийской гражданской войны, своей базой в 1352 году; после сильного землетрясения, разрушившего Галлиполи в марте 1354 года, опустевшие крепости были быстро укреплены, и полуостров превратился в постоянный османский плацдарм. Этот шаг, поддержанный расселением привезённого из Анатолии тюркменского населения, стал началом присутствия османов на европейском континенте, которое продлится более 550 лет.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Завоевание Эдирне", "2f54ebb0"], "d": ["Взятие Эдирне (Адрианополь), ключевого города Фракии, определило главную базу и направление балканских завоеваний; дата завоевания в источниках спорна — между 1361 и 1369 годами. Вскоре город был сделан столицей, что возвестило о смещении центра тяжести государства в Румелию; он оставался столицей около 90 лет, до завоевания Константинополя.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Мурад I взошёл на престол", "f8d48a26"], "d": ["Мурад I (Хюдавендигяр), унаследовавший престол после смерти Орхан-гази, за 27 лет своего правления превратил государство из порубежного бейлика в остов империи. Системой пенчика была заложена основа корпуса янычар, получила распространение тимарная система, учреждено Румелийское бейлербейство и укреплён институт везирата. Балканские завоевания при нём стали систематической государственной политикой.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Первая битва на Косовом поле — мученическая смерть Мурада I", "10b8ddc9"], "d": ["Балканский союз под предводительством князя Лазаря потерпел на Косовом поле решительное поражение; Сербия перешла под верховную власть османов. Мурад I, обходивший поле боя, был заколот кинжалом сербским дворянином Милошем Обиличем и погиб как шехид — это единственный османский падишах, павший на поле боя. На его место в лагере был возведён Йылдырым Баязид; его брат Якуб-челеби был удушен, и это стало одним из известных первых случаев применения братоубийства.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Победа при Никополе", "75716e96"], "d": ["Большое крестоносное войско, собранное по призыву венгерского короля Сигизмунда и включавшее также французско-бургундских рыцарей, было тяжело разгромлено Йылдырым Баязидом под Никополем на берегу Дуная. Победа окончательно закрепила османское господство над Болгарией; в течение целого поколения в Европе не удавалось организовать большой крестовый поход.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Битва при Анкаре — начало Фетрета", "b4a99d96"], "d": ["В тяжёлом поражении от войска Тимура на равнине Чубук Йылдырым Баязид попал в плен и через несколько месяцев умер в неволе. Тимур возродил анатолийские бейлики; османские земли были разделены между сыновьями Баязида и началась борьба за престол, которая продлится 11 лет (период Фетрет). Этот период, самый тяжёлый кризис со времени основания государства, запечатлел в османской памяти важность централизованного устройства. В тот же день утрачены также: Datça, Мармарис, Fethiye (Makri), Söke, Кютахья, Афьон, Испарт, Маниса, Айдын, Денизли, Мугла, Анталья, Конья, Караман, Кайсери, Кастамону, Бартын, Сафранболу, Самсун, Сивас, Малатья, Бейшехир, Sivrihisar, Kırşehir, Çorum, Чанкыры, Yenişehir (Бурса), İnegöl, крепость Aydos, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, остров İmralı, Кандыра, Мудания, Ялова, Karamürsel, Armutlu, Гемлик (Кий), Söğüt, Bilecik, Эскишехир, Бурса, Изник, Измит, Балыкесир, Чанаккале, Бергама, Амасья, Токат, Чорлу, Люлебургаз, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Стара-Загора, Пазарджик, Ихтиман, Кюстендил, Петрич, Неврокоп (Гоце-Делчев), Драма, Галлиполи, Çimpe, Эдирне, Дидимотихон, Кыркларели, Текирдаг, Пловдив, София, Ниш, Видин, Тырново, Варна, Шумен, Силистра, Никополь, Русе, Салоники, Серре, Кавала, Скопье, Битола, Охрид, Лариса, Трикала, Ламия (Ламия), Плевна, Комотини, Бига, Доманич, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Пелеканон (Eskihisar), Gebze, Hereke, Samandır, Kirmasti (М. Кемальпаша), Mihaliç (Karacabey), Констанца, Gölyazı (Аполлония).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Челеби Мехмед восстановил единство", "03413dfd"], "d": ["Победив Мусу-челеби при Чамурлу в последней схватке между братьями, Мехмед I объединил земли страны под единым управлением; поэтому его считают «вторым основателем государства». В его правление был восстановлен обветшавший государственный строй, уравновешены отношения с анатолийскими бейликами, а в Румелии проводилась осторожная мирная политика.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Восстание шейха Бедреддина", "e0a072ca"], "d": ["Религиозно-общественное движение вокруг шейха Бедреддина, крупного факиха и мистика, бывшего в период Фетрета казаскером, вспыхнуло одновременно с восстаниями Бёрклюдже Мустафы в Карабуруне и Торлак Кемаля в Манисе. Восстания были жестоко подавлены; Бедреддин был схвачен в Делиормане и казнён в Серре. Это событие оставило глубокий след в литературе и историографии как самое раннее крупное социально-мессианское восстание в османской истории.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Победа при Варне", "f739eedc"], "d": ["Венгерско-польское крестоносное войско, нарушившее Сегедский договор и двинувшееся на юг, было уничтожено под Варной Мурадом II, вернувшимся во главе армии после отречения от престола; юный король Владислав III погиб на поле боя. Победа устранила последнюю возможность крупного внешнего вмешательства с целью ликвидации османского присутствия на Балканах и обеспечила путь к завоеванию Константинополя.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Вторая битва на Косовом поле", "ebe0b662"], "d": ["Войско Яноша Хуньяди, желавшее отомстить за Варну, было решительно разгромлено Мурадом II в трёхдневном упорном сражении. Это последнее большое полевое сражение, которое крестоносцы дали османам на Балканах; с этой победой османское господство к югу от Дуная утвердилось необратимо.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Завоевание Константинополя", "583d5e3e"], "d": ["После осады, длившейся пятьдесят четыре дня (6 апреля – 29 мая 1453 года), османская армия утром 29 мая перешла через стены и вошла в город; последний император Константин XI погиб в боях, и 1100-летняя история Восточной Римской империи завершилась. Молодой падишах принял титул «Фатих», сделал город столицей и превратил Айя-Софию в мечеть; город вскоре ожил благодаря расселению и благоустройству. Отливка огромных пушек, перетаскивание кораблей по суше и осадный порядок перед стенами считаются вершиной военной инженерии эпохи. В европейской историографии завоевание считается одной из символических дат конца Средневековья.", "3664c5fe"]},
"OLAYLAR:1461-08-15:0":{"b": ["Завоевание Трабзона", "15f52403"], "d": ["По завершении трудного черноморского похода, который Фатих вёл одновременно армией и флотом, сдалась Трабзонская империя; с ликвидацией этого последнего осколка византийского мира в Анатолии всё южное побережье Чёрного моря перешло под османское господство. Прекращение династии Комнинов подкрепило притязание Фатиха на титул «властителя двух морей и двух земель». В тот же день присоединены также: Гиресун, Ризе.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Окончательное завоевание Силифке — слом последнего сопротивления Караманидов", "d988bee4"], "d": ["Крепость Силифке однажды сдалась Гедик Ахмед-паше в 1472 году, но в том же году Караманид Касым-бей с помощью крестоносного флота в Средиземном море отбил крепость. После победы при Отлукбели Фатих поручил своему сыну и Гедик Ахмед-паше окончательно овладеть этим районом; с помощью прежних османских артиллеристов пороховой склад был подожжён и крепость быстро пала. Так было сломлено последнее сопротивление Караманидов в горах Ташели-Ичель; ликвидация бейлика будет завершена в 1474 году.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Битва при Отлукбели", "42c7194e"], "d": ["Правитель Ак-Коюнлу Узун-Хасан, ставший крупной силой на Востоке и заключивший союз с Венецией, потерпел тяжёлое поражение при Отлукбели от армии Фатиха, оснащённой огнестрельным оружием. Победа окончательно утвердила османское превосходство в Анатолии; она стала и ранним свидетельством превосходства центральной армии, использовавшей пушки и ружья, над классическим войском.", "9c59ac50"]},
"OLAYLAR:1475-06-06:0":{"b": ["Переход Крыма под османское покровительство", "44e3f7c8"], "d": ["Флот под командованием Гедик Ахмед-паши завоевал южные прибрежные города Крыма, прежде всего находившуюся в руках генуэзцев Кефе; эти берега были превращены в непосредственный османский санджак. Крымское ханство же при Менгли-Гирее стало привилегированным вассальным государством, признавшим верховную власть османов, и на три века стало краеугольным камнем северной политики; Чёрное море фактически превратилось во внутреннее море османов. В тот же день присоединены также: Бахчисарай, Керчь, Азов.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Смерть Фатиха — дело султана Джема", "190ecf01"], "d": ["После внезапной смерти Фатиха в походе на престол взошёл Баязид II; его брат Джем-султан, претендуя на престол, велел в Бурсе читать хутбу и чеканить монету от своего имени. Потерпев поражение, он укрылся сначала у мамлюков, затем у родосских рыцарей; став в руках рыцарей и папства козырем в торге европейской дипломатии, Джем умер в Неаполе в 1495 году. Это событие в течение пятнадцати лет вынуждало османскую внешнюю политику действовать осторожно.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Победа при Чалдыране", "fea64ebb"], "d": ["Явуз Султан Селим, желавший в корне устранить угрозу, созданную в Анатолии сефевидской пропагандой, нанёс тяжёлое поражение войску шаха Исмаила на Чалдыранской равнине благодаря превосходству в пушках и ружьях. Был занят Тебриз; Восточная и Юго-Восточная Анатолия и линия Мосул–Диярбакыр вошли в состав османских владений. Присоединение курдских беев к османам благодаря усилиям Идриса-и Битлиси заложило основу восточной границы, которая просуществует века.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Победа при Мердж-Дабике", "07d254d3"], "d": ["Мамлюкская армия была разгромлена за несколько часов при Мердж-Дабике к северу от Алеппо; престарелый султан Кансух аль-Гаури умер во время сражения. Благодаря победе, распахнувшей ворота Алеппо и Дамаска, Сирия, Ливан и Палестина перешли под османское управление; открылся путь к походу в Египет, который положит конец Мамлюкскому государству.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ридания — завоевание Египта и халифат", "caf378d6"], "d": ["Быстро пересёкшая Синайскую пустыню османская армия прорвала оборонительную линию Тумана-бея при Ридании и вошла в Каир; продолжавший сопротивление Туман-бей был схвачен и казнён, и Мамлюкское государство перестало существовать. Египет, Хиджаз и священные города перешли под османское управление; аббасидский халиф и священные реликвии были увезены в Стамбул. С переходом халифата к османской династии падишахи приняли на себя притязание на руководство исламским миром; контроль над Пряным путём также принёс империи большие доходы. В тот же день присоединены также: Акка, Маан, Сайда, Керак.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Кануни Султан Сулейман взошёл на престол", "f6512269"], "d": ["46-летнее правление Сулеймана I, унаследовавшего престол после смерти Явуза как единственный сын, считается политической, военной, правовой и культурной вершиной империи. Кануннаме, систематизировавшие обычное право, принесли ему титул «Кануни»; на Западе его называли «Великолепным» (Magnificent). Символами этой эпохи являются творения зодчего Синана, золотой век диванной литературы и господство флота в Средиземноморье.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Завоевание Белграда", "59ef5cec"], "d": ["Белград, который Фатих не сумел взять в 1456 году и который считался «ключом к Центральной Европе», пал во время первого похода Кануни после осады у слияния Дуная и Савы. Южная оборонительная линия Венгрии рухнула; этим завоеванием открылись врата центральноевропейской кампании, протянувшейся пять лет спустя до Мохача и двадцать лет спустя до присоединения Буды.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Завоевание Родоса", "807bbb1e"], "d": ["Родос, база рыцарей-иоаннитов, угрожавших морским путям Восточного Средиземноморья и маршруту паломников, после кровопролитной осады, длившейся месяцами, сдался по договору; рыцарям было разрешено свободно покинуть остров (позднее они обосновались на Мальте). Безопасность анатолийских берегов была обеспечена, и морская линия Стамбул — Египет перешла под непрерывный османский контроль.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Битва при Мохаче", "f3418b0d"], "d": ["Венгерская армия была уничтожена на Мохачском поле примерно за два часа превосходством в артиллерийском огне и манёвре; король Лайош II погиб в болоте при бегстве. Мохач, одно из самых быстро выигранных больших полевых сражений в османской истории, фактически положил конец независимому Венгерскому королевству и открыл эпоху османско-габсбургского соперничества в Центральной Европе.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Первая осада Вены", "dc49ea4f"], "d": ["В походе, предпринятом против притязаний Габсбургов на венгерский престол, османская армия осадила Вену; из-за оставленных в пути тяжёлых орудий, рано наступившей зимы и трудностей с провиантом осада была снята через три недели. Хотя город взят не был, османское влияние над Венгрией сохранилось; подступы к Вене обозначили предел логистической досягаемости империи в Центральной Европе.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Завоевание Багдада — Ирак-ейнский поход", "897092c3"], "d": ["В походе на «два Ирака» (арабский и персидский) сначала был занят Тебриз, затем без боя — Багдад; взятие древней столицы Аббасидов принесло османскому правителю большой авторитет в исламском мире. Была восстановлена гробница Имама-и Азама Абу Ханифы; с присоединением Багдада и Басры османские земли вышли к Персидскому заливу. В тот же день присоединены также: Киркук, Кербела.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Морская победа при Превезе", "30dc0f97"], "d": ["Крестоносный флот, созданный по почину папы, несмотря на численное превосходство был рассеян у Превезы тактикой Барбароссы, мастерски использовавшего ветер и берег; Андреа Дориа покинул поле боя. Победа установила бесспорное османское господство на море в Средиземноморье, которое продлится около 33 лет; это символическая дата, День флота в турецкой морской традиции. В тот же день присоединены также: Аден, Бендеры.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Присоединение Буды — Венгрия как османская провинция", "db53b244"], "d": ["Кануни, выступивший в поход после осады Буды Габсбургами, освободил город, затем взял Центральную Венгрию под непосредственное османское управление и учредил Будинское бейлербейство; Трансильвания была превращена в автономное княжество, зависимое от османов. Этот порядок трёхчастной Венгрии продлился около 150 лет и образовал прочный остов османского управления в Центральной Европе.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Амасийский мир", "a5afe0d1"], "d": ["Это первый официальный мирный договор, положивший конец многолетним османско-сефевидским войнам. Багдад и Ирак остались за османами, граница Восточной Анатолии была впервые взаимно признана; сефевиды обязались прекратить шиитскую пропаганду на османской территории, а османы — обеспечить безопасный проезд иранских паломников. Договор стал первым примером правовой основы отношений между двумя государствами.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Сигетвар — кончина Кануни", "e2917ed2"], "d": ["72-летний Кануни скончался в своём шатре в тринадцатом походе за несколько часов до падения осаждаемой им крепости Сигетвар; Соколлу Мехмед-паша несколько недель скрывал смерть, чтобы армия не разбежалась. Крепость была взята, но государство потеряло своего самого долгоправившего и самого величественного падишаха; на престол взошёл его сын Селим II, и вес великих везирей в управлении государством стал возрастать.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Завоевание Кипра", "e364a2b3"], "d": ["Десант на находившийся под венецианским управлением Кипр был высажен в 1570 году; Никосия быстро пала, Магоса же сдалась лишь в августе 1571 года после одиннадцатимесячной осады. Остров, имевший решающее значение для безопасности торговых и паломнических путей Восточного Средиземноморья, был организован как бейлербейство, и в него было расселено население из Анатолии; завоевание стало и поводом для большого крестоносного союза, приведшего к Лепанто.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Поражение при Лепанто", "6a1d44a9"], "d": ["Объединившийся после завоевания Кипра крестоносный флот настиг османский флот в заливе Лепанто и уничтожил большую его часть; капудан-паша Мюэзцинзаде Али-паша погиб как шехид, спасся лишь флот Улуч Али. После катастрофы великий везирь Соколлу Мехмед-паша назначил Улуч Али-пашу капудан-пашой, поручил ему собрать рассеянный флот и начал строительство нового флота на всех верфях от Стамбула до Аланьи; однако безусловное превосходство в Средиземноморье было психологически подорвано.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Битва при Мезёкерестеше (Хачова)", "da308ec5"], "d": ["В крупнейшем полевом сражении Долгой войны (1593–1606) армия под личным командованием Мехмеда III, дойдя до грани распада, собралась по увещеванию Ходжи Саадеддина-эфенди и обратила габсбургское войско в бегство. Оно считается последним большим классическим полевым сражением, выигранным османами; однако то, что оно не изменило общего хода войны, сочли и признаком износа военной системы.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Ситваторокский мир", "39c01142"], "d": ["По договору, завершившему тринадцатилетнюю изнурительную войну, габсбургский правитель впервые был признан равным падишаху с титулом «римский император», а ежегодная дань была отменена. Потеря территорий была почти ничтожной; но эту перемену дипломатического языка читают как символ конца османского притязания на безусловное превосходство перед Европой.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Зухабский мир", "c1acf3af"], "d": ["Договор, подписанный после возвращения Багдада Мурадом IV (1638), положил конец османско-сефевидским войнам, длившимся более ста лет. Багдад и Ирак окончательно остались за османами, Ереван был оставлен сефевидам; проведённая линия с небольшими изменениями стала основой нынешней границы между Турцией и Ираном и считается одной из самых долговечных границ мира. По договору Bedre, Cessân, Mendelî, Derteng и Derne были оставлены османам; пограничная крепость Zencir должна была быть разрушена, деревни к западу от неё остались османам, а к востоку — Ирану. Окрестности крепости Zalim близ Шахризор и Kızılca Kale остались у османов, Авроман и Mihriban — у Ирана; крепости Котур, Маку и Mağazberd должны были быть разрушены обеими сторонами.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Завершено завоевание Крита", "e0d85604"], "d": ["Осада Кандии — заключительный акт критской войны, начавшейся в 1645 году, — закончилась трёхлетней решительной кампанией Фазыл Ахмед-паши; венецианский командующий Мороцини сдал город по договору. Борьба, продолжавшаяся около четверти века, вошла в историю как самая долгая осада в истории османов; последняя большая латинская крепость Восточного Средиземноморья также перешла под османское управление. Три небольшие скалистые крепости на северном берегу острова — Суда, Спиналонга и Грамвуса — пока оставались у Венеции; поскольку они расположены на отдельных островках, на карте их нельзя показать отдельно от остального Крита.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Бучачский мир — наибольшие границы", "b17b6e5a"], "d": ["По Бучачскому миру, подписанному после завоевания Каменца в польском походе, Подолье было присоединено к османам, а часть Украины взята под покровительство. Так империя достигла наибольших границ в Европе; эта точка считается вершиной эпохи расширения и вместе с тем её последним звеном.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Разгром при второй осаде Вены", "7d889252"], "d": ["Двухмесячная осада Вены Мерзифонлу Кара Мустафа-паши обернулась разгромом после внезапного удара, нанесённого польским королём Яном Собеским с высот Каленберга; армия отступила, бросив обозы, а Мерзифонлу был казнён в Белграде. Война с образованной после победы Священной лигой длилась 16 лет; этот разгром указывают как начальный момент великого упадка в османской истории.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Завоевание крепости Грамвуса — одной из скалистых крепостей Крита, остававшихся у Венеции", "3ddf9eeb"], "d": ["Хотя завоевание Крита с сдачей Кандии в 1669 году считалось в основном завершённым, скалистый остров-крепость Грамвуса на северо-западной оконечности острова ещё двадцать три года оставалась в руках Венеции. С её взятием в 1692 году была ликвидирована одна из трёх венецианских крепостей на Крите; Суда и Спиналонга же должны были дождаться морейского похода 1715 года.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Карловицкий мир — первая крупная потеря территорий", "8f7e2546"], "d": ["По Карловицкому миру, завершившему шестнадцатилетние войны Священной лиги, Венгрия и Трансильвания были оставлены Австрии, Подолье — Польше, Морея и побережье Далмации — Венеции. Впервые в османской истории земли такого масштаба утрачивались за столом переговоров и навсегда; договор считается начальным документом новой эпохи, когда империя перешла к обороне перед Европой, и вместе с тем поворотным пунктом истории османской дипломатии.", "54bb2eee"]},
"OLAYLAR:1711-07-19:0":{"b": ["Победа на Пруте", "2583572f"], "d": ["В войне, вызванной вопросом о шведском короле, искавшем убежища у османов после Полтавского поражения, армия царя Петра I была окружена на берегу Прута и вынуждена сдаться. По заключённому договору Азов был возвращён; то, что армия не была уничтожена, а царь был отпущен, вошло в историю как решение, обсуждаемое с тех пор по сей день.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Завоевание крепостей Суда и Спиналонга — стёрт последний венецианский след на Крите", "7261f7ba"], "d": ["Через двадцать три года после падения Грамвусы в 1692 году, в одной из побочных ветвей морейского похода были завоёваны и крепости Суда и Спиналонга — последние две опоры Венеции на Крите. Так завоевание Крита, начатое в 1645 году, по прошествии сорока шести лет было завершено до последнего вершка острова.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Восстание Патроны Халила", "100941a4"], "d": ["Неудача на иранском фронте, налоги и гнев на роскошь придворного круга переросли в большое восстание под предводительством банщика Патроны Халила. Великий везирь Ибрахим-паша был убит, Ахмед III свергнут, и эпоха тюльпанов закончилась; то, что мятежники месяцами владели городом, ярко показало хрупкость центральной власти.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Белградский мир — возвращение Белграда, Смедерево и северной Сербии", "ba7f8e46"], "d": ["По окончании войны (1736–1739), которую вели на двух фронтах против Австрии и России, Белград и Северная Сербия были возвращены; Россия согласилась разоружить Азов и не держать флот на Чёрном море. Договор, считающийся последним крупным успехом османской дипломатии и армии XVIII века, принёс империи четвертьвековой мирный период.", "5b399dd2"]},
"OLAYLAR:1770-07-06:0":{"b": ["Чесменский разгром", "840b30bd"], "d": ["Русский флот, вышедший в Средиземное море при поддержке англичан, атаковал брандерами османский флот, укрывшийся в гавани Чесме, и почти полностью сжёг его. Россия впервые появилась в Средиземном море как большая морская держава; катастрофа стала одним из ударов, определивших исход войны, приведшей к Кючук-Кайнарджи 1774 года, и обнажила необходимость коренной реформы флота.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Кючук-Кайнарджийский мир", "2776dcdb"], "d": ["По Кючук-Кайнарджи, завершившему войну 1768–1774 годов и считающемуся одним из самых тяжёлых договоров в османской истории, Крымскому ханству была дана «независимость» — фактически была создана сфера русского влияния. Россия закрепилась на побережье Чёрного моря, получила право прохода торговых судов через проливы и постоянное посольство в Стамбуле; расплывчатая оговорка о покровительстве над православными подданными приоткрыла дверь для поводов к вмешательству в следующем столетии. Впервые земля с мусульманским населением выводилась из-под османского господства.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Присоединение Крыма к России", "bdf6faa8"], "d": ["«Независимый» Крым, созданный Кючук-Кайнарджийским миром (Küçük Kaynarca), был присоединён к России манифестом Екатерины II под предлогом смут при последнем хане Шахин-Гирее (Şahin Giray). Трёхвековое османо-крымское партнёрство закончилось; потеря северных степей лишила Стамбул оборонительной глубины и положила начало первой большой волне переселения десятков тысяч крымских татар в османские земли. В этот день Крымский полуостров (Алушта, Кефе/Кафа, Судак, Ялта, Балаклава, Инкерман, Мангуп, Арабат) вошёл в состав России; Тамань и Кубань при том же присоединении тоже перешли к России (TDV Kırım: 8 апреля 1783 г. по юлианскому календарю = 19 апреля по григорианскому).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Селим III и Низам-и Джедид", "d53aec21"], "d": ["Селим III, взошедший на престол в разгар войны, понял, что поражения носят структурный характер, и начал широкую программу реформ под названием «Низам-и Джедид» («Новый порядок»): новая армия, обученная по европейскому образцу, отдельная казна для её финансирования (Ирад-и Джедид), укрепление инженерных училищ и первые постоянные посольства в европейских столицах. Программа считается началом современной турецкой реформаторской традиции; однако из-за сопротивления корпусов и аянов она будет разрушена в 1807 году.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Ликвидация мальтийских рыцарей — остановка французского флота по пути", "d62f901d"], "d": ["Французский флот, шедший в Египет, зашёл на Мальту, лежавшую на его пути; рыцари святого Иоанна (Мальтийские) без особого сопротивления сдали остров. Так закончилось существование последней крепости рыцарского ордена, изгнанного с Родоса в 1522 году и обосновавшегося здесь. Мальта через два года перейдёт в руки Англии, а Наполеон направится с острова прямо в Александрию.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Вторжение Наполеона в Египет", "93fede5f"], "d": ["Армия генерала Бонапарта высадилась в Александрии и заняла Египет; этот поход, нацеленный на путь Англии в Индию, был первым непосредственным нападением европейской державы на центральные земли османов. Нападение Нельсона при Абукире и оборона Акки Джеззар Ахмед-пашой сломили французское продвижение; оккупация закончилась в 1801 году, но в оставленной ею пустоте начались возвышение Кавалалы Мехмеда Али-паши и эпоха «Восточного вопроса».", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Сенед-и Иттифак", "cce49ef5"], "d": ["Документ, подписанный между дворцом и сильными аянскими семействами провинции под руководством русчукского аяна Алемдара Мустафа-паши, возведшего на престол Махмуда II: аяны обязались хранить верность падишаху и поддерживать его войсками, а государство признало их существование и права. Поскольку это первый в османской истории пример ограничения власти падишаха документом, некоторые историки считают его далёким началом конституционной традиции; фактически он утратил силу в течение нескольких месяцев.", "2d97fdfe"]},
"OLAYLAR:1821-03-25:0":{"b": ["Началось греческое восстание", "a7293715"], "d": ["Восстание, подготовленное организацией «Филики Этерия», вспыхнуло сначала в Валахии, затем с основной силой — в Морее; занятое делом Тепеделенли Али-паши государство опоздало с первым вмешательством. Благодаря сильным симпатиям к грекам в европейском общественном мнении (филэллинизм) восстание быстро превратилось в международное дело; так был зажжён фитиль первого успешного движения за независимость на османских землях в эпоху национализма. В тот же день утрачены также: Афины, Патры, Фивы, Ливадия.", "316e2ac7"]},
"OLAYLAR:1826-06-15:0":{"b": ["Вакъа-и Хайрийе — упразднение корпуса янычар", "08c9372a"], "d": ["Янычары, поднявшие бунт против учений нового корпуса эшкинджи, были уничтожены артиллерийским огнём заранее подготовленных Махмудом II верных частей в своих казармах на Этмейданы; корпус был упразднён со всеми его отделениями и связанными с ним бекташскими текке. Эта операция, вошедшая в историю под названием «Благое событие», ликвидировав четырёхвековой институт, расчистила путь армии Асакир-и Мансуре-и Мухаммедийе и всем последующим реформам централизации.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Наваринское сражение", "ee579e7f"], "d": ["Османско-египетский флот, подавлявший греческое восстание, был сожжён в Наварине объединённой английско-французско-русской эскадрой, вошедшей в гавань без объявления войны; было потеряно около шестидесяти кораблей и тысячи моряков. Нападение, которое европейская дипломатия обошла словами «досадный случай», фактически гарантировало независимость Греции и открыло путь к османско-русской войне 1828–1829 годов.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Танзиматский фирман", "5042ce7b"], "d": ["Хатт-и Хумайуном, зачитанным в Гюльхане, безопасность жизни, имущества и чести всех подданных без различия вероисповедания была взята под гарантию государства; были провозглашены принципы справедливости в налогообложении, порядка в военной службе и недопустимости наказания без суда. Фирман, труд Мустафы Решид-паши, считается первым крупным документом османской модернизации конституционного характера, а «эпоха Танзимата» (1839–1876) дала название эпохе реформ; в этих рамках проводилась коренная перестройка управления, права, образования и финансов.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Началась Крымская война", "3b9ca3c8"], "d": ["Кризис, начавшийся с вопроса о святых местах и притязания России на покровительство над православными подданными, перерос в открытый конфликт объявлением войны со стороны османов; после Синопского разгрома Англия и Франция (позднее Пьемонт) вступили в войну на стороне османов. Война была выиграна с высадкой союзных армий в Крыму и взятием Севастополя, завершившись Парижским миром 1856 года; однако первый внешний заём (1854), взятый в годы войны, ввергнул империю в круговорот финансовой зависимости, который продлится полвека.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Ислахатский фирман", "78ff234d"], "d": ["Фирман, провозглашённый накануне Парижских мирных переговоров, расширил принципы Танзимата и предоставил немусульманским подданным широкие права на равенство, включая государственную службу, военную службу и открытие школ; организация общин была упорядочена заново. Затем по подписанному Парижскому миру Османское государство было официально принято в семью европейского международного права, а его территориальная целостность взята под общую гарантию великих держав — эта гарантия на практике станет новой дверью для вмешательства.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Кануни Эсаси — Первая конституционная эпоха", "0fe052c1"], "d": ["В день открытия международной конференции, собравшейся в Стамбуле для обсуждения балканского кризиса, залпами орудий была провозглашена первая османская конституция; Кануни Эсаси, детище движения «Новых османов» под предводительством Мидхат-паши, создал двухпалатный парламент. Палата депутатов открылась в марте 1877 года; однако Абдулхамид II под предлогом «Войны 93-го года» в феврале 1878 года бессрочно распустил палату, и конституция была приостановлена на тридцать лет.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["«Война 93-го года» (русско-турецкая война 1877–1878)", "5bd96af7"], "d": ["В войне, названной «Войной 93-го года», потому что она пришлась на 1293 год по румийскому календарю, русские армии наступали с двух фронтов; хотя оборона Плевны Гази Осман-паши и кавказские сражения Ахмед Мухтар-паши стали легендой, фронт рухнул, и русские дошли до Сан-Стефано (Айастефанос) близ Ешилькёя. Война положила начало большим волнам мусульманской эмиграции с Балкан и Кавказа к Стамбулу, последствия которых тянутся до сегодняшнего дня; демографическая и финансовая структура империи уже не смогла вернуться к прежнему состоянию.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Берлинский договор", "47f76a49"], "d": ["Берлинский конгресс, пересмотревший «Великую Болгарию», созданную Сан-Стефано, во имя баланса великих держав, всё же оставил тяжёлую картину: Сербия, Черногория и Румыния стали независимыми; было создано автономное Болгарское княжество; Босния и Герцеговина были оставлены австрийской оккупации, Кипр — английскому управлению, Карс–Ардахан–Батум — России. Пятисотлетний османский порядок в Румелии в значительной мере распался; «восточный вопрос» стал постоянной повесткой европейской дипломатии. В тот же день утрачены также: Пловдив, Видин, Тырново, Варна, Шумен, Силистра, Русе, Бухарест, Яссы, Констанца.", "076697b6"]},
"OLAYLAR:1881-05-12:0":{"b": ["Оккупация Туниса и Администрация общественного долга", "c7e25598"], "d": ["Франция под предлогом инцидентов на алжирской границе оккупировала Тунис и взяла его под своё покровительство по Бардоскому договору; османское присутствие в Северной Африке сузилось до Триполитании. Декретом Мухаррема, изданным в том же году, было учреждено Управление общественного долга, в котором были представлены кредиторы для управления обанкротившимися внешними долгами: основные доходы, такие как соль, табак, шёлк, были непосредственно переданы этому иностранному управлению, и финансовый суверенитет оказался тяжело ограничен. В тот же день утрачены также: Кайруан, Габес, Сфакс, Джерба (Djerba).", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Английская оккупация Египта", "f1269768"], "d": ["Движение Ураби-паши, поднявшееся против финансового банкротства и иностранного контроля в Египте, было разгромлено победой английской армии при Тель-эль-Кебире после бомбардировки Александрии, и Каир был оккупирован. Хотя Египет юридически оставался зависимым от османов, фактически он перешёл под английское управление; контроль над Суэцким каналом занял центральное место в имперской стратегии Британии.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Провозглашение Второй конституционной эпохи", "95ee2fd2"], "d": ["Перед лицом движения, выросшего после ухода офицеров, связанных с Обществом «Единение и прогресс», в горы Македонии, Абдулхамид II вновь ввёл в силу Кануни Эсаси; «провозглашение свободы» было встречено с восторгом, и состоялись выборы. Однако стабильность не наступила: после подавления «Инцидента 31 марта» (апрель 1909) Абдулхамид был свергнут; независимость Болгарии, аннексия Боснии и стремление Крита к Греции также произошли в эти бурные месяцы.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Триполитанская война", "ed441994"], "d": ["Италия, искавшая колонии, объявила войну Триполитании — последней османской земле в Северной Африке — и оккупировала побережье; когда лишённое флота государство не смогло послать регулярную армию, молодые офицеры, такие как Мустафа Кемаль и Энвер-бей, тайно проникли в этот район и организовали действенное сопротивление вместе с сенуситскими племенами. По Ушийскому миру (18 октября 1912 года), подписанному в связи с началом Балканской войны, Ливия была оставлена Италии; Италия также оккупировала Родос и Додеканес.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Лондонский мир — потеря Румелии", "f3f976df"], "d": ["По Лондонскому миру, завершившему Первую Балканскую войну, были потеряны все земли к западу от линии Мидье–Энез и острова Эгейского моря; Албания стала независимой. От Румелии, на протяжении более пятисот лет бывшей демографическим, экономическим и культурным центром тяжести империи, осталась лишь Восточная Фракия (Эдирне был возвращён во Второй Балканской войне); потеря коренным образом ожесточила военную и переселенческую политику унионистского руководства.", "077da59d"]},
"OLAYLAR:1914-11-01:0":{"b": ["Вступление в Первую мировую войну", "05a0252e"], "d": ["Пропуск в Босфор бежавших от Англии броненосцев «Гёбен» и «Бреслау», выданных за купленные, шаг за шагом втянул государство на сторону Германии; с бомбардировкой русских портов флотом под командованием адмирала Сушона (29 октября) война фактически началась, а взаимные объявления войны последовали в начале ноября. Несмотря на провозглашение Великого джихада, ожидаемого эффекта не последовало; империя вступила на четыре года в борьбу за существование на пяти фронтах — от Кавказа до Палестины.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Победа при Чанаккале", "95d888e8"], "d": ["Армада союзников, нацеленная на захват Стамбула и выход к России, 18 марта была отброшена из Босфора огнём минных полей и батарей; линия, поставленная минным заградителем «Нусрет», определила судьбу сражения. Начавшаяся в апреле сухопутная операция в Галлиполи также была остановлена у Анафарталара и Конкбайыры; союзники полностью эвакуировали полуостров в январе 1916 года. На этом фронте стало известно имя подполковника Мустафы Кемаля; победа, доставшаяся ценой около четверти миллиона павших и пропавших без вести, считается местом, где родились кадры и дух Национальной борьбы.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Восстание шерифа Хусейна", "75f7c58c"], "d": ["Мекканский эмир шериф Хусейн после тайной переписки с англичанами восстал, получив обещание независимого арабского королевства; Хиджазская железная дорога стала целью набегов. Хотя легендарная оборона Медины Фахреддин-пашой, продолжавшаяся до времени после перемирия, осталась символом сопротивления, восстание, соединившись с английским продвижением на палестинском фронте, ускорило распад османского господства в арабских вилайетах. В тот же день утрачены также: Таиф.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Мудросское перемирие", "9e87c767"], "d": ["Османское государство, фронты которого оказались разобщены вследствие краха Болгарии, вышло из войны по перемирию, подписанному на броненосце «Агамемнон». Статья 7, позволявшая открыть проливы и оккупировать особенно места, безопасность которых оказалась под угрозой, вскоре стала юридическим прикрытием фактического раздела: были оккупированы Мосул, Искендерун, затем Измир и Стамбул. Перемирие считается документом фактического конца империи. В тот же день утрачены также: Хама, Дамаск, Хомс.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Мустафа Кемаль в Самсуне — Национальная борьба", "09a8f784"], "d": ["Мустафа Кемаль-паша, в обстановке возмущения, вызванного оккупацией Измира, прибывший в Самсун в качестве инспектора 9-й армии, обратил свою официальную должность на организацию сопротивления в Анатолии. Амасийский циркуляр и конгрессы в Эрзуруме и Сивасе — продолжение этого шага; принцип «независимость народа спасёт воля и решимость самого народа» стал ядром политической программы Национальной борьбы.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Открытие ВНСТ и Севр", "2008feec"], "d": ["После официальной оккупации Стамбула и роспуска Палаты депутатов 23 апреля 1920 года в Анкаре открылось Великое национальное собрание; собрав в себе чрезвычайные полномочия, собрание стало ядром нового государства, основанного на национальной воле. Севрский договор, подписанный стамбульским правительством в августе, делил Анатолию; ВНСТ объявило подписавших договор изменниками родины, и Севр так и не был приведён в исполнение.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Битва на реке Сакарья", "f2f970a6"], "d": ["Греческое наступление, приблизившееся к Анкаре на 50 километров, было сломлено в 22-дневном и 22-ночном сражении, которое велось по приказу Мустафы Кемаль-паши, принявшего полномочия главнокомандующего: «Нет линии обороны, есть поверхность обороны». Греческая армия впервые перешла к стратегической обороне; победа принесла Мустафе Кемалю звание гази и маршала (мушира), открыла путь Анкарскому соглашению с Францией и международному признанию.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Великое наступление и освобождение Измира", "172a50c4"], "d": ["Наступление, начатое утром 26 августа с Коджатепе, 30 августа достигло уничтожения главных греческих сил в Битве Главнокомандующего при Думлупынаре; в преследовании по приказу «Армии, ваша первая цель — Средиземное море, вперёд!» 9 сентября был освобождён Измир. По Муданийскому перемирию (11 октября) Восточная Фракия была возвращена без боя; военная победа определила силу нового государства за столом переговоров в Лозанне.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Упразднение султаната", "9f36a9f6"], "d": ["После приглашения стамбульского правительства на лозаннские переговоры ВНСТ 1 ноября 1922 года отделило султанат от халифата и упразднило султанат; 623-летнее правление османской династии юридически закончилось. Мехмед VI Вахдеддин 17 ноября покинул страну на английском броненосце; на пост халифа по решению ВНСТ был возведён Абдулмеджид-эфенди, и этот пост также будет упразднён 3 марта 1924 года.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Лозаннский мир", "38c27f7d"], "d": ["По Лозаннскому мирному договору, подписанному по окончании восьми месяцев трудных переговоров, границы нового турецкого государства, его полная независимость и суверенитет были признаны на международной арене; капитуляции были отменены, Управление общественного долга поставлено на путь ликвидации, обмен населением урегулирован. Лозанна, фактически сделавшая Севр недействительным, считается дипломатической победой Национальной борьбы и основополагающим внешним документом Республики.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Провозглашение Республики", "d5bfcdfb"], "d": ["Республика была провозглашена принятием ВНСТ изменением конституции положения «Форма правления Турецкого государства — республика»; Мустафа Кемаль-паша был избран первым президентом. Так закрылась 624-летняя османская повесть, начавшаяся в 1299 году как порубежный бейлик; новое государство, в котором суверенитет безусловно принадлежит нации, было построено на наследии империи.", "f5cabb8c"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["Включение пустынного центра Сенусийя — Cağbûb — в османский порядок: фирман Абдулмеджида об освобождении", "039fce6d"], "d": ["Мухаммад ибн Али ас-Сенуси, много лет проживший в Мекке, после возвращения в Триполитанию поселился в оазисе Cağbûb на египетской границе и построил на господствующей скале большую завию; место, состоявшее из нескольких бараков, вскоре превратилось в город. В 1856 году фирманом султана Абдулмеджида имущество членов ордена было освобождено от налога, а мюридам было дано право собирать закят. Этот фирман сделал оазис на караванном пути, соединявшем Западную Африку и Судан с Каиром, частью османского финансового и административного порядка и укрепил Cağbûb как торговый центр. Верность населения региона халифу подтверждается и путевыми записками полковника (миралая) Садика аль-Муайяда, посетившего эти места в 1884 и 1893 годах.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["Начало рытья Суэцкого канала и основание Порт-Саида", "cef0be8d"], "d": ["Земляные работы по проекту Лессепса, одобренному Высокой Портой 5 января 1856 года, начались 25 апреля 1859 года; канал будет завершён десять лет спустя, 16 ноября 1869 года. На средиземноморском конце раскопок, на береговом валу между озером Мензале и морем, барачный посёлок из пяти домов, устроенный для рабочих, стал ядром Порт-Саида. Город получил это имя, означающее «порт Саида», в 1860 году от должностных лиц канальной компании в честь тогдашнего правителя Египта Саид-паши. Так на османской карте на береговой полосе, где ранее не было никакого поселения, возник новый порт.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["Визит султана Абдулазиза в Египет и основание Исмаилии на Суэцком перешейке", "bcfacf38"], "d": ["Султан Абдулазиз по настоянию великого визиря Юсуф Камиль-паши отправился 3 апреля 1863 года в Египет и был встречен большими торжествами; целью было укрепить верность центру вилайета, фактически начавшего превращаться в отдельное государство со времён восстания Мухаммеда Али. В том же году на перешейке, на холмах Tilâlülcisr на берегу озера Тимсах, был основан административный центр канальной компании: сначала для инженеров был поставлен посёлок Karyetüttimsah, затем для рабочих — посёлок Karyetülarab. Когда хедив Исмаил-паша, близко интересовавшийся пресноводным каналом, построил себе на этом холме кёшк, поселение стало называться Исмаилия по его имени. Основание города датируется 1863 годом; точный день неизвестен.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Управление Мидхат-паши Багдадом и расселение племён — основание Рамади и Насирии", "0fa98f06"], "d": ["Мидхат-паша, снятый с поста председателя Şûrâ-yı Devlet и удалённый из Стамбула, управлял в 1869–1872 годах Багдадским вилайетом, включавшим также Мосул и Басру, с широкими полномочиями и с должностью командующего Шестой армией. Применяя здесь Arazi Kanunnâmesi (Закон о землях) и новый закон о вилайетах, он раздавал земли по тапу, привязывал кочевые племена к оседлому порядку и государственной власти. Как итог этой политики расселения в 1869 году на берегу Евфрата для племени дулайм был основан Рамади, а на юге руками мутасарыфа Мунтафика Насыр-паши ас-Садуна — Насирия; оба возникли в местах, где до того времени не было поселений, и впервые попали на карту в эту дату.", "7babb36f"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["После разгрома при Анкаре воевода Валахии Мирча вновь взял Добруджу — Силистра, Констанца, Бабадаг, Исакча", "5eaefc68"], "d": ["Поражение Баязида Молниеносного от Тимура при Анкаре потрясло османское господство вдоль Дуная. Воевода Валахии Мирча, воспользовавшись этим вакуумом, вновь вошёл в Добруджу; Силистра, Констанца, окрестности Бабадага и Исакча на берегу Дуная оставались в его руках в годы Междуцарствия. Мирча поддерживал Мусу Челеби против Челеби Мехмеда. Силистру он удерживал до смерти в 1418 году.", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["Переход Бабадага и окрестностей к османам — Мирча и его сын Михаил разбиты", "bfda2c60"], "d": ["Челеби Мехмед, разбив воеводу Валахии Мирчу и его сына Михаила, взял под османское господство Бабадаг и окрестности в Северной Добрудже. Бабадаг был городом, носившим имя Салтук-бабы и основанным туркменским поселением XIII века. Окрестные Силистра, Констанца и остальные добруджские крепости же оставались в Валахии до 1419 года; то есть Бабадаг три года выглядит оторванным от османской земли островом (эксклавом).", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["Возвращение Силистры и Добруджи — после смерти Мирчи", "73eb6ae9"], "d": ["Смута, возникшая в Валахии после смерти воеводы Валахии Мирчи в 1418 году, дала Челеби султану Мехмеду возможность вернуть Силистру и Добруджу. Весной 1419 года Силистра, Констанца и большая часть Добруджи вновь перешли под османское управление; крепости Энисала (Yenisale) и Исакча были отремонтированы и превращены в пограничные крепости (серхат); Добруджа затем оставалась у османов до 1878 года.", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["Закрытие Нижнего Дуная — присоединение Джурджу, Turnu и Оршовы", "331a0b68"], "d": ["После окончания эпохи Междуцарствия попытка Челеби Мехмеда упорядочить дунайскую линию принесла плоды в 1420 году. Крепость Джурджу, построенная воеводой Валахии Коджа Мирчей на его собственной земле, с покрытием расходов продажей соли, в этом году перешла в османские руки (Добруджа была возвращена годом ранее, весной 1419 года — TDV silistre), и были присоединены Turnu (Kule/Holovnik) на правом берегу Дуная и Оршова — позднее Fethülislâm. Так оба берега реки сразу оказались под контролем. Значение Джурджу определяется его географией: это османская крепость, построенная на левом, то есть валашском берегу Дуная, и вместе с Русе на противоположном берегу держит оба конца одной переправы. Османские документы прямо пишут эту двойственность — для Русе говорится «Джурджу этого берега», для Giurgiu — «Джурджу того берега». Крепость будет возвращена валахами в 1427 году, в 1449 году вновь перейдёт под османский контроль, и кааза Джурджу, подчинённый санджаку Никополь, станет островом, управляемым непосредственно внутри воеводства. Ответ на вопрос, почему на карте дунайская полоса Валахии тёмного цвета, начинается здесь.", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["Область Топлица (Куршумлия, Прокупле) перешла под османское господство", "e22e690d"], "d": ["Вероятно, во время помолвки Мурада II с Марой Бранкович область Дубочица и Топлица (окрестности Лесковаца, Куршумлии и Прокупле) перешла под османское господство; кадастровая перепись (тахрир) 1445–1447 годов показывает, что область была роздана османским сипахи в качестве тимаров. На карте Куршумлия и Прокупле с этого года находятся под османским управлением.", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["Присоединение Сараевского поля — создание османского выступа в Боснии", "be5c0f00"], "d": ["После того как боснийские короли в 1428–1429 годах были обложены данью, османы начали прочно обосновываться вглубь королевства. В 1428–1435 годах был взят городок Ходидед; в 852 (1448) году вилайет Ходидед вместе с Сараевским полем полностью перешёл под османское управление. Это — пограничная область, созданная в центре королевства за пятнадцать лет до завоевания Боснии и управлявшаяся скопским беем Иса-беем, носившим титул воеводы; поскольку вокруг по-прежнему находились боснийские беи, подчинённые османам, область находилась под двусторонним контролем. Сам город также возник в этот период: до 1462 года Исхак-бей или его сын Иса-бей основал первый мусульманский квартал, в 862 (1458) году от имени Завоевателя была построена мечеть Hünkâr Camii, а, когда были обустроены посевы села Brodec, возник городок Saray. Завоевание 1463 года уничтожило Боснийское королевство; Сараевское поле же к тому времени уже пятнадцать лет было османской землёй.", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["Присоединение Подгорицы к османским землям — взятие под контроль Зетской равнины", "46e401c5"], "d": ["Городок, расположенный в равнине на слиянии вод Моравы и Рибницы в двадцати километрах к северу от Шкодерского озера, в источниках впервые упоминается в 1216 году как Рибница, в 1326 году — как Подгорица. В 1457 году он был присоединён к османским землям, и контроль над Зетской равниной тем самым вышел из рук династий Балшичей и Черноевичей. Мехмед II Завоеватель в 1474–1478 годах велел построить на обрывистых скалах на стыке двух рек крепость и мечеть; в 1479 году после завоевания Шкодера область была подчинена вновь созданному санджаку Шкодер. Подгорица, по переписи 1485 года — христианский городок на сорок домов, в 1529–30 годах достигла 800 человек и гарнизона из тридцати двух человек под началом коменданта (dizdar) внутри крепости, а в 1582 году — 322 домов. Эвлия Челеби в 1662 году насчитал в крепости Фатих триста домов, склады, арсеналы и семьсот стражников. Эти записи показывают и разницу между равниной и горами Зеты: равнина — подсчитанный, облагаемый налогом и имеющий гарнизоны османский кааза, тогда как в XVIII веке город вынужден будет укрепляться шестью бастионами и стенами с тремя воротами, чтобы предотвращать набеги племён в горах Черногории. Подгорица в конце войны 1876–1878 годов перешла в руки Черногории и по Берлинскому договору осталась за ней.", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["Взятие Фочи — открытие первого входа в Герцеговину", "f098a9e6"], "d": ["После упразднения Боснийского королевства в 1463 году настала очередь земель Стефана Вукчича-Косачи, отделившегося от королевства и создавшего собственное герцогство. Фоча, расположенная в долине Дрины, на перекрёстке торгового пути, связывавшего Стамбул с Дубровником, в 1465 году перешла под османское управление. Значение города было понято сразу: в 1470 году он был сделан центром нового санджака Герцеговина — то есть административное ядро Герцеговины было создано в Фоче ещё до падения самого герцогства. Присоединение герцогства целиком продлится до 1483 года. Фоча после этого развивалась как торговый и административный центр благодаря благоприятному климату и положению на перекрёстке дорог. На карте эта дата — день, когда после завоевания Боснии началась вторая волна на юг.", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["Окончательная аннексия Ливно и западной Боснии — установление венецианской границы", "c14d4283"], "d": ["Крепость на плато, господствующем над Ливненской равниной, в 1448–1454 годах находилась в руках Стефана Вукчича-Косачи, основателя герцогства Герцеговина. В боснийском походе 1463 года она на короткое время была занята османскими силами, но в том же году возвращена; в 1466 году хозяин города — Иваниш Влатькович. По выражению TDV, окончательное османское господство, по всей вероятности, установилось в 1468–1469 годах, и перепись 1485 года уже записывает Ливно как османскую землю. Это закрытие западного края боснийского завоевания: Ливно стало опасным пограничным городком, соседним с венецианскими землями, находившимися всего в тридцати шести километрах по ровной равнине, и сохраняло это положение до взятия боснийским правителем Гази Хюсрев-беем венецианских крепостей в 1521–1522 годах.", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["Потеря Böğürdelen в пользу венгров — первая брешь на линии Савы", "129fe8f2"], "d": ["В местности, перешедшей в османские руки при Мехмеде II Завоевателе и прежде называвшейся Zaslon, в 1471 году была построена деревоземляная крепость. Поскольку она находилась в пункте, угрожавшем Белграду, и отсюда можно было легко совершать набеги на южные области Венгрии и Австрии, крепость и получила своё имя от этой функции — Böğürdelen означает «бастион, бьющий сбоку». Венгерский король Матьяш Корвин осадил крепость к концу 1475 года и взял её в феврале 1476 года. Венгерская эпическая поэма Szabács viadala, рассказывающая об осаде, — один из самых длинных дошедших до нас текстов венгерских исторических поэм XV века. Венгры создали в области банат и, заново укрепив крепость камнем, сделали её звеном цепи пограничных крепостей. Османы в 1492 году пытались вернуть её и не смогли; крепость сорок пять лет оставалась в руках венгров.", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["Завоевание Ионических островов — конец герцогства Токко: Санта-Маура, Кефалиния, Закинф, Итака", "07b27251"], "d": ["Подписанный в январе того же года с Венецией Константинопольский мир оставил османам Шкодер и албанское побережье; Ионические острова же находились не в управлении Венеции, а семьи Токко, державшей графство Кефалиния-Закинф, и были взяты отдельной операцией. По статье «Ayamavra» в TDV, последний герцог Леонардо Токко сначала сохранял верность, женившись на родственнице Мехмеда II Завоевателя Милице Бранкович, а когда в 1464 году жена умерла, в 1477 году женился на Франческе Марцано из неаполитанской династии и тем рассердил падишаха. Через два года флот под командованием владетеля Влёры Гедик Ахмед-паши взял Санта-Мауру вместе с Кефалинией на юге; Леонардо и Франческа бежали в Италию. Статья «Гедик Ахмед-паша» отмечает, что в той же операции был взят и Закинф (Zanta); подчинённая графству Кефалиния Итака также в это время перешла под османское управление. Так морской путь от входа в Адриатику до Мореи оказался полностью под контролем. Из островов Закинф через три года будет оставлен Венеции, Кефалиния и Итака будут потеряны в 1500 году, и лишь Санта-Маура двести лет останется у османов.", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["Подданство Зеты Черноевичей и превращение Цетине в центр", "59d20267"], "d": ["С тем, что Шкодер остался в 1479 году у османов, оказалась в границах империи и находившаяся в его тылу горная область Зета. Семья Черноевичей, державшая область, признала власть Баязида II, взошедшего на престол после смерти Мехмеда II, обложилась харадж и осталась свободной во внутренних делах; Иван Черноевич перенёс центр с равнины в Цетине у подножия горы Ловчен и основал город. Монастырь, построенный им здесь через два года, стал религиозным центром региона. Так Черногория появляется на карте не как непосредственно османская земля, а как подчинённая область светлого тона. Статья «Черногория» в TDV упоминает династию и Цетинскую епископию и пишет, что в 1514 году господство руками Скендер-бея (из рода Черноевичей, воспитанного при османском дворе) было превращено в отдельный санджак; сам же 1482 год в TDV не встречается, это дата, даваемая черногорской историографией. Из-за суровости рельефа управление здесь никогда не действовало так строго, как на равнинах.", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["Завоевание крепости Килия — замок устья Дуная", "ef4eca73"], "d": ["Молдавия с сентября 1455 года была зависимым воеводством, платившим две тысячи золотых в год, но два порта, выходящих к Чёрному морю, всё ещё находились в руках воеводы, и дунайская торговля шла через них. Баязид II совершил первый большой поход своего правления именно на эти два порта. Комендант крепости Килия, обстреливавшейся десять дней днём и ночью, был вынужден сдаться. Крепость была взята под прямое османское управление и превращена в санджакбейство; во второй половине XVI века из-за казачьей угрозы она была преобразована в кааза и присоединена к санджаку Аккерман, подчинённому бейлербейству Румелии. Отсюда Молдавия на карте выглядит двухуровневой: внутри воеводство остаётся светлым тоном как зависимая земля, а два порта на побережье — тёмным тоном как непосредственно османские санджаки. Статья «Молдавия» в TDV называет эти два порта «ключами и воротами Молдавии» и пишет, что область окончательно была присоединена к османам при Баязиде II.", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["Завоевание Аккермана — закрытие устья Днестра и чёрноморских ворот Молдавии", "7cb20feb"], "d": ["Через двадцать дней после сдачи Килии армия подошла к Аккерману в устье Днестра, и крепость была взята 4 августа. Город был самым оживлённым портом Молдавии; при Мехмеде II, когда воевода Петру III в 1455 году признал османское господство, купцам Аккермана было дано разрешение на торговлю, теперь же порт стал непосредственно государственным. Аккерман, после завоевания превращённый в санджак, подчинённый бейлербейству Румелии, в 1593 году был присоединён к вновь созданному эялету Очаков. Так внешняя оболочка Молдавии, окружённая с севера Хотином, с юга — Килией и Аккерманом, начала переходить под непосредственный османский контроль; воеводство осталось свободным во внутренних делах, но выхода к морю лишилось. На карте нет промежуточной пустой области — портовые санджаки тёмного тона и земля воеводства светлого тона соприкасаются; степь Буджак между ними до 1538 года всё ещё является частью воеводства.", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["Сдача Лепанто — вход в Коринфский залив отнят у Венеции", "2cfe0777"], "d": ["Лепанто с 1407 года находилось в руках Венеции и держало вход в Коринфский залив; вся береговая линия внутри залива была подчинена досягаемости этой крепости. В походе 1499 года крепость была осаждена с суши, а османский флот, сражавшийся у Лепанто с венецианским флотом, помогал силам осады с моря. Венецианцы в крепости 26 августа сдали город османам. После этого город оставался у османов сто восемьдесят восемь лет, в 1687 году с потерей Мореи вновь перешёл к Венеции, в 1715 году был возвращён. Морское сражение того же лета и эта сдача — два разных события: флотское сражение происходило на западной оконечности Мореи, в водах Сапиенца — Зонкьо; Лепанто же пало в результате сухопутной осады у входа в Коринфский залив.", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["Присоединение баната Сребреник — первый разлом венгерской линии в северной Боснии", "6d98c725"], "d": ["После падения Боснийского королевства в 1463 году Матьяш Корвин перешёл в контрнаступление и создал на севере королевства два баната, остановивших османское продвижение: на западе — Яйце, на северо-востоке — Сребреник. Они были передовой оборонительной линией Венгрии в Боснии и закрывали коридор между Савой и Боснией. Банат Сребреник был взят в 1512 году; так рухнул восточный фланг линии, и санджак Зворник смог расшириться к северу. Яйце на западном фланге продержится ещё шестнадцать лет и будет взят лишь после Мохача, в 1528 году.", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["Завоевание Böğürdelen — первая крепость, взятая Кануни, и место, где было принято решение о Белграде", "85177a90"], "d": ["Силы бейлербея Румелии Ахмед-паши, посланного в область в первом венгерском походе Кануни Сулеймана, после ожесточённой осады взяли крепость 7 июля 1521 года. Böğürdelen — первая крепость, завоёванная в правление Кануни. Падишах после завоевания лично вошёл в крепость и приказал благоустроить город; решения о завоевании Белграда также были приняты здесь — то есть план Белграда, который падёт 29 августа 1521 года, был составлен в Böğürdelen. После этого крепость почти двести лет оставалась у османов; сначала была подчинена Румелии, с 1580 года — эялету Босния, затем ненадолго Смедерево и, наконец, санджаку Зворник. На карте эта дата — день, когда линия Савы закрылась в пользу османов.", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["Начало восстания трёх воеводств — Трансильвания перешла к Священной лиге, османофильские бояре арестованы", "68a33800"], "d": ["На втором году Долгой войны вассальный пояс османов в Центральной Европе вдруг рухнул. К Священной лиге, созданной под покровительством папы Климента VIII, в конце лета присоединились Молдавия и Трансильвания: воевода Молдавии Арон Водэ 16 августа 1594 года оформил своё присоединение к христианской стороне документом, а князь Трансильвании Жигмонд Батори 28 августа 1594 года, расправившись с османофильскими боярами, выступавшими против войны, сломил внутреннюю оппозицию. Воевода Валахии Михай Храбрый присоединился к союзу осенью того же года. Так три зависимых княжества османов к северу от Дуная — три воеводства, сто пятьдесят лет платившие харадж, воеводы которых утверждались Стамбулом, — осенью разом перешли на другую сторону. Решение было оформлено договором, подписанным в Праге 28 января 1595 года. Это было самое тяжёлое потрясение, которому подверглась система косвенного управления османов на севере Балкан; восстание будет подавлено, но верность трёх княжеств уже не будет такой прочной, как в 1526–1593 годах.", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["Бухарестское восстание и нападение на дунайские крепости", "18971100"], "d": ["Решение Священной лиги было осуществлено через месяц кровью: Михай Храбрый в Бухаресте перебил османский охранный отряд и левантийских кредиторов, находившихся в городе. Восстание в ту же зиму распространилось на линию Дуная; валашские силы напали на Джурджу, Брэилу, Хыршову и Силистру, а на молдавской стороне Арон Водэ совершил такое же нападение на османскую охрану в Бендерах. Выбор поражённых мест не случаен: все они были не землёй воеводства, а крепостями и кааза вдоль Дуная, подчинёнными непосредственно османскому управлению — кааза Джурджу относился к санджакбейству Никополь, Брэила с 1538 года — непосредственно к государству, Бендеры также с 1538 года — к санджаку Буджак. То есть восстание ударило не по вассальной внутренней области, а по непосредственной османской оболочке, окружавшей эту область. Без пробития этой оболочки треугольник Трансильвания — Валахия — Молдавия нельзя было присоединить к габсбургскому фронту.", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["Сражение при Калугэрени — валашский поход Коджа Синан-паши", "201210a1"], "d": ["После того как три воеводства разом были потеряны, великий визирь Коджа Синан-паша с большой армией перешёл Дунай и двинулся, чтобы вновь привести Валахию к повиновению. Михай Храбрый, зная, что не сможет противостоять в открытом бою, ждал армию в Калугэрени, на болотистом броде Нягова, и внезапно напал на силы, зажатые на узкой местности. После нападения, не сумев устоять против численно превосходящей османской армии, он отступил на север, в горы; Синан-паша занял Бухарест и Тырговиште и попытался подчинить Валахию прямому управлению. Поэтому Калугэрени было для османов не поражением, а нападением, задержавшим завершение похода; но то, что Михай смог сохранить свою армию, сделало возможным его переход в контрнаступление через несколько недель с помощью, пришедшей из Трансильвании.", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["Отступление из Валахии и нападение у Джурджу — безрезультатность карательного похода", "118806e1"], "d": ["После контрнаступления Михая Храброго, объединившегося с силами князя Трансильвании, Синан-паша оставил Тырговиште и Бухарест и отошёл к Дунаю. Самый дорогой момент отступления пришёлся на переправу: в октябре 1595 года акынджи, преследовавшие возвращавшуюся из Валахии армию, подверглись у Джурджу нападению Михая. Поход таким образом закончился, не достигнув цели подчинения Валахии прямому управлению, и воеводство фактически осталось потерянным. Османская власть в этом треугольнике могла быть восстановлена лишь за годы и по частям; возвращение Трансильвании к повиновению будет ждать восстания Бочкаи в 1604 году, а полное закрытие фронта — Житваторокского мира 1606 года.", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["Отторжение Хотина от Молдавии — прямой османский санджак посреди воеводства", "947517cb"], "d": ["Переход молдавского воеводы Дмитрия Кантемира на сторону России в Прутском походе показал, что северную границу воеводства больше нельзя оставлять воеводе. Поэтому Хотин после 1711 года был отнят у Молдавии и введён в прямое османское управление; ему был дан сначала статус нахийе, затем санджака. После временной русской оккупации 1713 года крепость была вновь отремонтирована и расширена под надзором османской и французской технических комиссий, присланных из Стамбула, и стала сильнейшим османским укреплением к северу от Дуная. Что на карте после этой даты Хотин выходит из тона зависимого воеводства и возвращается к цвету непосредственно османскому и стоит посреди зависимой Молдавии как отдельный остров — это и есть отражение этого административного разделения; это не ошибка рисунка. Такая же структура уже существовала в Буджаке с 1538 года, в Килии и Аккермане — с 1484 года: воеводство свободно во внутренних делах, пограничные крепости принадлежат государству.", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["Вторая австрийская оккупация Böğürdelen — открытие фронта на Саве", "063b3ad0"], "d": ["После вступления Австрии в войну на стороне России 9 февраля 1788 года линия Савы вновь стала фронтом, и Böğürdelen 24 апреля 1788 года перешёл под австрийское господство. Крепость ранее, 17 августа 1717 года, была без боя уступлена Австрии и удерживалась ею до Белградского мира (1739); в то время население настолько сократилось, что в городе осталось тридцать четыре христианских дома и ни одного мусульманина. В османскую эпоху 1739–1788 годов население вновь выросло до 1500–2000 человек. Вторая оккупация закончится Систовским миром (4 августа 1791), и крепость будет возвращена османам.", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["Сдача Böğürdelen Карагеоргию — первая крепость в Первом сербском восстании", "5c913eb4"], "d": ["Во время первой сербской революции, начавшейся в 1804 году как реакция на давление дахий и ямаков в Белграде и затем приобретшей националистический характер, крепость Böğürdelen была сдана Карагеоргию 26 января 1806 года. Эта крепость на Саве — первая крупная османская крепость, захваченная повстанцами, и она предвещает падение Белграда. Когда восстание было подавлено в 1813 году и Белград возвращён, крепость также вернулась под османское управление; однако по условию о гарнизонах фирмана 1830 года Böğürdelen вместе с Белградом, Смедерево и Fethülislâm была определена как одна из четырёх крепостей внутри автономной Сербии, где оставались османские войска, и сохраняла этот статус до вывода гарнизона в 1867 году.", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["Ламия осталась в границах Греции — линия Арта — Волос", "930f63b8"], "d": ["Северная граница независимого греческого государства в 1832 году была проведена по линии от Амбракийского залива до Воломского залива. Ламия, в османский период (1424–1832) бывшая центром кааза в составе санджака Негропонт, осталась к югу от этой линии и поэтому перешла к Греции; остальная Фессалия (Лариса, Трикала) оставалась у османов до 1881 года.", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["Объявление войны Россией — начало Русско-турецкой войны 1877–1878 гг.", "ac548ab8"], "d": ["Подавление Болгарского восстания 1876 года вызвало большое возмущение в европейском общественном мнении, и Россия использовала это до конца, чтобы изолировать Высокую Порту. После того как предложение Константинопольской (Тершанейской) конференции разделить Болгарию на две автономные провинции, а затем Лондонский протокол от 31 марта 1877 года были отвергнуты Османским государством, Россия 24 апреля 1877 года объявила войну, и её армия вошла на территорию Румынского княжества, перетянутого на её сторону (карта показывает Валахию и Молдавию с этого момента до Адрианопольского перемирия штриховым покрытием русского продвижения). Так как война пришлась на 1293 год по календарю рûmî, она известна как Doksanüç Harbi (Война 93-го года). Операции велись на двух фронтах — на Дунае и в Восточной Анатолии: на Дунае 180-тысячная османская армия считала левый берег реки первой, а Балканские горы — второй оборонительной линией; на востоке 55 000 солдат Ахмед Мухтар-паши были расположены между Ардаганом и Баязетом. Эта война на карте — событие, начавшее крушение османской Румелии: нынешние границы Болгарии, Сербии, Черногории и Румынии — все продукт этих пятнадцати месяцев.", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["Провозглашение независимости Румынии — конец зависимости Валахии и Молдавии", "bdd164b3"], "d": ["Через две недели после объявления Русско-турецкой войны 1877–1878 гг. Румынское княжество провозгласило независимость и вступило в войну на стороне России; его роль в осаде Плевны стала решающей для османского поражения. Зависимость Валахии и Молдавии, длившаяся более четырёхсот лет, тем самым фактически закончилась; независимость получила международное признание на Берлинском конгрессе (1878). Карта с этой даты показывает Румынию не как зависимую, а как независимое государство собственного цвета.", "02d51dee"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["Переход русскими Дуная — падение Систова и Тырново", "811367b1"], "d": ["Русские, вошедшие с началом войны на румынские земли и привлёкшие это княжество на свою сторону, продвигались двумя колоннами — одна в направлении Добруджи, другая — Бухареста. Дунай был форсирован между Русе и Никополем, и 27 июня был взят Систов, а 1 июля — Тырново, старая болгарская столица. Поскольку, несмотря на приказ об эвакуации, этому не было уделено внимания, Никополь, ещё некоторое время сопротивляясь, также сдался. Прорыв первой оборонительной линии за неделю вызвал в Стамбуле большую панику; распространились даже слухи о том, что центр султаната будет перенесён в Бурсу, и руководство войной было передано военному совету, созданному в столице.", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["Эвакуация Шипкинского перевала — прорыв Балканской линии", "1f45e50a"], "d": ["Османские силы на Шипке, самом стратегическом из перевалов через Балканские горы, упорно сопротивлялись русским атакам; но, убедившись, что будут разбиты, 19 июля тайно эвакуировали перевал. Так была открыта и вторая оборонительная линия, и генерал Гурко 22 июля взял Стару-Загору. Хотя Сулейман-паша, подошедший со стороны Черногории, разбил Гурко и вернул оккупированные места к югу от Балкан, ему не удалось вернуть Шипку, несмотря на длившиеся месяцами с 21 августа атаки. На карте это означает, что целостность обороны между севером и югом Балканского хребта уже не была восстановлена: борьба на дунайском фронте отныне свяжется узлом у Плевны.", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["Ловеч занят русской армией", "70e54611"], "d": ["В Русско-турецкой войне 1877–1878 гг. Ловеч был занят русскими 5 июня 1877 года, османские силы под командованием Рифат-паши 15 июня отбросили русских; 23 августа город был оставлен османами и вновь перешёл под русскую оккупацию. Карта показывает Ловеч с этого дня до Берлинского договора под русской оккупацией (штриховка); юридически он продолжает оставаться османской территорией.", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["Падение Карса — развал восточного фронта и форты Азизие", "53fc3bf5"], "d": ["Русские, наступавшие в Восточной Анатолии тремя колоннами в направлении Карса, Баязета и Ардагана, 30 апреля взяли Баязет, вошли в Ардаган, но при движении на Эрзурум 15 июля были разбиты и выброшены за границу. Этот успех, принёсший Ахмед Мухтар-паше титул «Гази», в августе обернулся обратным, когда генерал Лазарев вновь перешёл в наступление, и 18 ноября Карс пал. Османские силы, отошедшие к Эрзуруму для более удобной обороны, оказали большое сопротивление на фортах Азизие, где население воодушевляла Нене Хатун. Карс, Ардаган и Батум через восемь месяцев будут уступлены в Берлине России в счёт части военной контрибуции.", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["Начало Первой Балканской войны — объявление войны Черногорией", "c0c2697e"], "d": ["Балканские государства, после того как «Единение и прогресс» законом от 3 июля 1911 года решило вопрос о церквях, устранили между собой самое большое препятствие и в течение 1912 года по подстрекательству России подписали между собой союзные договоры (13 марта — Болгария и Греция, в августе — Черногория и Болгария, 6 октября — Черногория и Сербия). Высокая Порта этого не заметила; более того, полагаясь на гарантии России, она распустила 120 обученных батальонов в Румелии. Четыре государства 3 октября вручили совместную ноту с требованием автономии для Македонии, Албании и Крита; не получив ответа, они начали операции 8 октября 1912 года с объявления войны Черногорией. 13 октября послам Сербии и Болгарии были вручены паспорта, на следующий день эти два государства, а затем Греция объявили войну. Политические разногласия внутри армии во время войны сыграли большую роль в поражении.", "f008aef9"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["Разгром Кырджалийского отряда в Родопах, падение Кырджали", "8cf59b7f"], "d": ["После объявления Болгарией войны болгарские силы, спустившиеся с Родоп, разбили Кырджалийский отряд Мехмеда Явер-паши и вошли в Кырджали. Разбитый отряд отошёл в направлении Комотини; восточная часть Родоп была потеряна в первую же неделю войны.", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["Разгром Восточной армии и отход на линию Чаталджи — потеря Куманова и Салоник", "cf95591a"], "d": ["Османская Восточная армия 23 октября 1912 года была разбита болгарской армией, втрое превосходившей её по численности, и отступила до линии Чаталджи в тридцати километрах к западу от Стамбула; столица в первый же месяц войны оказалась под прямой угрозой. В те же дни Западная армия 23–24 октября была разбита сербами при Куманове, а Тахсин-паша с армией в 35.000 человек сдался грекам в Салониках. В связи с этими разгромами 29 октября подал в отставку кабинет Гази Ахмед Мухтар-паши; Абдулхамид II, проводивший жизнь в ссылке в Салониках, 1 ноября был перевезён в Стамбул. Линия Чаталджи удерживалась до конца войны — пятисотлетняя османская география Румелии за несколько недель сузилась до этой узкой полосы.", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["В центр Новопазарского санджака вошёл князь Александр", "326d0616"], "d": ["Сербские силы в первую неделю войны взяли Новый Пазар и соединились с черногорскими силами, подошедшими с запада. Новопазарский санджак, сто лет разделявший Сербию и Черногорию, превратился в мост между двумя союзниками.", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["После сражения при Кирк-Килисе потерян Кыркларели", "eda4c759"], "d": ["После поражения Восточной армии в сражении при Кирк-Килисе в Восточной Фракии город, оборонявшийся Колемен Абдулла-пашой, был оставлен болгарским силам. Город был освобождён от оккупации, длившейся девять месяцев, лишь во Второй Балканской войне, 21 июля 1913 года.", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["Центр Косовского вилайета Скопье оставлен без сопротивления", "455d9b71"], "d": ["После разгрома при Куманове (23–24 октября) центр Косовского вилайета Скопье остался беззащитным. Поскольку население не желало боёв вокруг города, сербские силы под командованием князя Александра, приглашённые через консулов, вечером 26 октября вошли в город без сопротивления.", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["Потерян Велес на Вардаре", "73d20b7d"], "d": ["Через два дня после падения Скопье сербская армия, спускавшаяся на юг вдоль Вардара, взяла Велес. Ворота долины Вардара к Салоникам тем самым перешли в руки сербов.", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["Бассейн Брегальницы: генерал Стефанович вошёл в Штип", "70a84256"], "d": ["Сербские части под командованием генерала Стефановича взяли Штип, не встретив сопротивления; в город сначала вошли нерегулярные отряды. После Куманова бассейн Брегальницы в восточной Македонии перешёл под сербский контроль.", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["После перевала Сарантапоро Верия перешла под греческое господство", "02a68e02"], "d": ["Греческая армия, наступавшая с севера Фессалии, после преодоления перевала Сарантапоро (Kırkgeçit) овладела Верией. Часть мусульманского населения города в это время покинула область.", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["Потеряна Эдесса на железной дороге Салоники — Монастир", "fc15b917"], "d": ["Эдесса на железной дороге Салоники — Монастир перешла в руки греческой армии. С вынужденным выселением славянского и турецкого населения население города вскоре серьёзно сократилось.", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["Сражение при Яннице — переход Яницы на Вардаре к грекам", "8f6cb76e"], "d": ["8-й сводный корпус Хасана Тахсин-паши был разбит греческой армией при Яннице к западу от Салоник и отошёл в район Салоник. Во время сражения сгорела большая часть городка; путь на Салоники для греческой армии был открыт.", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["Призрен на юго-западе Косова сдался", "bae6b1b9"], "d": ["Призрен на юго-западе Косова сдался сербским силам. Отношение вошедших в город частей к мусульманскому населению было зафиксировано как одна из самых тяжёлых страниц войны в Косове.", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["Полковник Митов объявил в Струмице военное положение", "bcad75cc"], "d": ["Болгарский полковник Митов вошёл в Струмицу и объявил военное положение; на следующий день, уходя, он оставил городок болгарскому каймакаму и сербскому командиру. Струмица в ходе войны переходила из рук в руки между союзниками и в 1913 году была присоединена к Болгарии.", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["Хасан Тахсин-паша оставил Салоники грекам", "1738933c"], "d": ["Хасан Тахсин-паша, отошедший к Салоникам после поражения при Яннице, оставил город грекам, когда болгарская армия приближалась с севера; греческая армия вошла в город около полудня 8 ноября. Так были потеряны Салоники, крупнейший портовый город османской Румелии и родина «Единения и прогресса».", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["Центр Западной Фракии Комотини открыт болгарам", "96eec25f"], "d": ["После отхода отряда Явер-паши, отступавшего из Кырджали, в направлении Фере Комотини сдался болгарским силам. Центр Западной Фракии был в числе первых земель, которые по окончании войны будут оставлены Болгарии.", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["Сербы, дошедшие до Эльбасана, в тот же день вошли в Дебар", "16720246"], "d": ["Сербские силы, продвигавшиеся на запад от Монастира, в день прибытия в Эльбасан вошли и в Дебар и спустились к Адриатике. В тот же день во Влёре провозглашалась независимость Албании.", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["Тимур вторично занял Багдад — разрушены аббасидские кварталы города", "04b68a24"], "d": ["Тимур брал Багдад дважды с промежутком в восемь лет. При первой оккупации 1393 года город сильно не пострадал; вторая же в 1401 году считается вторым тяжёлым ударом по культурной жизни Багдада — население было перебито, большая часть кварталов и зданий аббасидской эпохи разрушена. Хотя джалаирид Ахмед в 1405 году вернулся в город и пытался восстановить разрушенные стены и рынки, времени у него не хватило; Багдад в 1410 году перешёл в руки туркмен Кара-Коюнлу. Эти две оккупации — один из самых конкретных шагов, показывающих, насколько близко Тимур подошёл на пути к битве при Анкаре к османским и мамлюкским границам.", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["Джунайд-бей вернулся во главе Aydın-ili — Айдыниды вновь самостоятельны", "63281658"], "d": ["Челеби Мехмед в 1414–15 годах взял Измир и, отправив Джунайд-бея санджакбеем в Никополь, подчинил Aydın-ili османскому управлению. Джунайд после смерти Челеби Мехмеда вновь появился на сцене рядом с Мустафой Челеби, выдвинутым византийцами как претендент на престол, и даже был его визирем. Мурад II отдалил его от этого союза обещанием вернуть прежний бейлик; Джунайд вернулся в Измир, овладел Ayasuluk и, убив Айдыногуллары Мустафа-бея, встал во главе бейлика. Так Aydın-ili родился из кризиса «Самозванца Мустафы» вышедшим из-под османского управления.", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["Казнь Джунайд-бея и его семьи — конец бейлика Айдынидов", "efa684ba"], "d": ["Когда Джунайд-бей, вновь овладевший Aydın-ili, стал подстрекать анатолийских беев и искать связей с Венецией, Мурад II послал против него бейлербея Анатолии Хамза-бея. Когда его сын Курд Хасан был разбит близ Акхисара и взят в плен, Джунайд, отошедший к İpsili напротив острова Самос, был вынужден сдаться, потому что ожидаемая от Караманидов помощь не пришла, а генуэзцы, действовавшие заодно с османами, блокировали его с моря; он был уничтожен вместе со всем своим родом. Земли Айдынидов тем самым полностью перешли под османское управление.", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["Эрзурум и бассейн Вана перешли к Сефевидам — рухнул северный фланг Ак-Коюнлу", "b418875f"], "d": ["Разбив Альванд-бея при Шарюре и войдя в Тебриз летом 1501 г., шах Исмаил на следующий год двинулся на северо-запад и подчинил себе линию от Эрзурума до бассейна озера Ван. Государство Ак-Коюнлу после смерти Узун-Хасана уже было расколото борьбой за трон на две части: Альванд-бей владел Азербайджаном и Диярбакиром, а его двоюродный брат Мурад - Персидским Ираком и Фарсом. Этот раскол облегчил продвижение Сефевидов; область за год сменила владельца в десяти записях. Эрзурум оставался в руках Сефевидов шестнадцать лет и перешёл под власть Османов лишь после Чалдырана, в 1518-19 гг. В этом году (1502) Ашкале и Пасинлер (Хасанкале) вместе с областью Эрзурума перешли от Ак-Коюнлу к Сефевидам (день не подтверждён).", "2f80b39d"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["Поражение Мурад-бея под Хамаданом: Ирак-и Аджами и Фарс перешли к Сефевидам", "8de07a31"], "d": ["Второй претендент на трон Ак-Коюнлу султан Мурад потерпел тяжёлое поражение в сражении против шаха Исмаила близ Хамадана и бежал в Багдад. Этим единственным сражением области Ирак-и Аджами, Фарс и Керман перешли под сефевидское управление; на карте эти области меняют владельца одновременно. Это самый крупный отдельный шаг распада государства Ак-Коюнлу — потеря Тебриза оставила династию без столицы, поражение под Хамаданом оставило её без земель.", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["Шах Исмаил вошёл в Йезд: пал последний оплот остатков Ак-Коюнлу в центральном Иране", "6f9835df"], "d": ["Хотя после поражения под Хамаданом в 1503 году Ирак-и Аджами и Фарс перешли к Сефевидам, Йезд оставался обособленным в руках Bayındırlı Мурад-бея из династии Ак-Коюнлу. Город пал после месячной осады, и последний остров Ак-Коюнлу в центральном Иране закрылся. Запись TDV: «Шах Исмаил вошёл в город 28 джумада ас-сани 910 года (6 декабря 1504) после месячной осады.»", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["Диярбекирский поход шаха Исмаила: пали последние центры Ак-Коюнлу", "b6d8504e"], "d": ["Шах Исмаил, овладевший Азербайджаном и Иранским нагорьем, в 1507 году обратился на запад, в область Диярбекир, где родилась династия Ак-Коюнлу. Линия от Амида до Мардина, от Урфы до Харпута двумя рывками перешла под сефевидское управление, и Ак-Коюнлу фактически исчезли. Этот поход впервые подвёл сефевидскую границу вплотную к османским и мамлюкским границам; так была создана географическая почва напряжения, ведшего к Чалдыранской битве.", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["Переход Багдада к Сефевидам — Ирак-и Араби сменил владельца", "39730186"], "d": ["Вслед за султаном Ак-Коюнлу Мурадом, укрывшимся в Багдаде после поражения под Хамаданом, шах Исмаил в 1508 году вошёл в Ирак-и Араби и взял Багдад. Переход гробниц в Кербеле и Неджефе под сефевидское управление был так же важен с точки зрения конфессиональных притязаний движения, как и взятие Тебриза. На карте Ирак-и Араби меняет владельца в тот же день; это последний и самый широкий географический шаг распада. Багдад оставался у Сефевидов до похода Кануни на оба Ирака (Irakeyn Seferi) 1534 года.", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["Сражение при Мерве: узбеки тяжело разбиты, Мерв и Герат взяты", "f8e45aaf"], "d": ["Шах Исмаил, завершивший на западе наследство Ак-Коюнлу, двинулся на восток, в Хорасан, и нанёс перед Мервом тяжёлое поражение узбекам; Шейбани-хан погиб на поле боя. Мерв и Герат перешли под сефевидское господство, и государство Сефевидов обрело границы, протянувшиеся от Евфрата до Амударьи. Так процесс, начавшийся летом 1501 года вступлением в Тебриз, был завершён за девять лет: наследство Ак-Коюнлу целиком перешло под сефевидское управление, и Османское государство получило на востоке соседом второе государство своей величины.", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["Окончательный переход Забида под османское господство", "ddd971c7"], "d": ["Флот, снявший осаду Диу 5 ноября 1538 года, на обратном пути зашёл к берегу Йемена, и Забид окончательно был подчинён османскому управлению; Хадым Сулейман-паша покинул город 10 марта 1539 года и 1 апреля прибыл в Джидду. Город с 1517 года управлялся от имени османов прежними мамлюкскими беями; с этой датой он перешёл на прямое управление.", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["Иберийская уния: португальская корона перешла королю Испании", "1cc6dfdc"], "d": ["Борьба за наследство, открывшаяся со смертью бездетного короля-кардинала Энрике, закончилась в пользу Испании в сражении при Алкантаре (25 августа 1580), и собравшиеся в Томаре португальские кортесы 16 апреля 1581 года признали Филиппа II королём Португалии. По условиям Томара Португалия сохраняла свои учреждения, деньги и язык, на управление назначались только португальцы, в Мадриде должен был находиться отдельный португальский совет — то есть объединение было личной унией, а не аннексией.", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["Restauração: Португалия вернула независимость", "64ec0738"], "d": ["В дни, когда каталонское восстание занимало Испанию, в Лиссабоне группа знатных людей совершила налёт на дворец и свергла испанское управление, провозгласив герцога Браганса королём под именем Жуана IV. Шестидесятилетняя Иберийская уния тем самым закончилась; однако Сеута предпочла остаться в Испании, и это было признано Лиссабонским договором 1668 года. Это окно, в котором Португалия была втянута в габсбургские войны, составляет также рамки её потерь в Азии: Ормуз был потерян в 1622 году, Малакка — в 1641 году, Коломбо — в 1656 году; Танжер и Бомбей же были отданы Англии как цена независимости. Источник: Britannica, History of Portugal — Restoration.", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["Танжер передан Англии", "1f7cad6d"], "d": ["Вторая статья брачного договора (23 июня 1661), заключённого для получения английской поддержки в войне Португалии за независимость, отдавала Танжер Англии как приданое Екатерины Браганской. Флот графа Сандвича бросил якорь 29 января 1662 года, и на следующий день церемонией графа Питерборо была проведена официальная передача. Англичане оставят город в 1684 году.", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["Убийство Надир-шаха — распад афшаридского господства", "19c218c0"], "d": ["Надир-шах, положивший конец сефевидскому трону и провозгласивший в 1736 г. собственный султанат, дошедший в индийском походе до Дели и трижды воевавший с Османами, прежде чем заключить мир Кердэнским договором 1746 г., был убит в своём шатре собственными телохранителями. После этого Ираном невозможно было править из одних рук: сорок девять лет страну делили афшарский остаток в Хорасане, Зенды на юге и возвышавшиеся Каджары на севере. Благодаря этой раздробленности османская восточная граница надолго оставалась спокойной. Надир-шах был убит 20 июня 1747 г.; по TDV, Эриванское ханство было основано в том же году (1747), день не подтверждён.", "75fd6ab9"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["Господство династии Каджаров в Иране", "744b48c5"], "d": ["Ага Мухаммед-хан, предводитель племени каджаров, свергнув власть Зендов и сломив последнее сопротивление Афшаридов в Хорасане, вновь объединил Иран в одних руках и сделал столицей Тегеран. Так завершился сорокадевятилетний период раздробленности; отныне до 1923 года восточным соседом Османской империи был каджарский Иран. По данным TDV İslâm Ansiklopedisi, Мешхед в 1796 году был встречен перед Ага Мухаммед-шахом афшаридским правителем Шахрухом и перешёл под власть каджаров (день в источнике не указан).", "755b544a"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["Фердинанд овладел Будой — Запольяи изгнан из столицы", "99f77c29"], "d": ["После Мохача на венгерском троне оказались два короля: часть знати избрала Яноша Запольяи, другая часть — Габсбурга Фердинанда. Фердинанд в 1527 году овладел Будой и изгнал Запольяи из столицы; Запольяи просил помощи у султана Сулеймана. Вот почему первой целью Венского похода 1529 года стала Буда.", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["Поход Барбароссы на Эгейские острова — Герцогство Наксос перешло под османский контроль", "722b2fea"], "d": ["Герцогство Наксос, с 1207 года управлявшееся под венецианским покровительством латинскими герцогами, перешло под османский контроль в результате островного похода Барбароссы Хайреддин-паши. Статус острова не был затронут; герцогство продолжило существование как подчинённое османам, и по османско-венецианскому договору 1540 года право господства было официально передано османам.", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["Крестоносный флот занял Джербу — потеряна база Тургут-паши", "f41b3f2a"], "d": ["Крестоносный флот, составленный из кораблей Испании, Папства, Мальты, Генуи и Флоренции, нацелился на Джербу, использовавшуюся Тургут-рейсом с 1551 года как база набегов. Из-за бурь и эпидемии он смог дойти до острова лишь в начале 1560 года; 12 марта 1560 года занял остров и построил крепость. Узнав об этом, Пиале-паша 28 марта вышел из Стамбула с флотом из 120 галер. Оккупация длилась недолго: османский флот в мае победил союзников у Джербы, а крепость была возвращена в конце июля. Этот поход — начало второй большой морской операции, укрепившей после Превезы османское господство в Средиземном море.", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["Падение крепости Джерба — переход острова под османское управление", "f1efc0df"], "d": ["После морской победы Пиале-паши 14 мая 1560 года крестоносные силы заперлись в построенной ими на острове крепости; силы бейлербея Триполи Тургут-паши осадили её с суши. Двухмесячная осада закончилась падением крепости 30 июля 1560 года, и остров был подчинён бейлербейству Триполи. Между морской победой и завоеванием крепости семьдесят семь дней; остров фактически сменил владельца не 14 мая, а 30 июля.", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["Закончилось русско-прусское двоевластие в Данциге — вольный город Наполеона вернулся к Пруссии", "1ccda4d2"], "d": ["Силы Наполеона покинули Данциг, отделённый от Пруссии Тильзитским миром (9 июля 1807) и превращённый в вольный город под французским покровительством, после осады 1813 года. Между 2 января и 4 февраля 1814 года в городе продолжалось русско-прусское двоевластие; когда царь Александр отказался от плана взять Данциг и устье Вислы, город перешёл под прусское управление.", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["Краков объявлен на Венском конгрессе вольным, независимым и нейтральным городом", "19eea839"], "d": ["На Венском конгрессе Россия, Австрия и Пруссия сделали город Краков с округой вольным государством под покровительством трёх держав; Заключительный акт Венского конгресса закрепил этот порядок.", "21a6fe2b"]},
"OLAYLAR_EK12:1846-11-11:0":{"b": ["Вольный город Краков упразднён и присоединён к Австрии", "15548a14"], "d": ["Воспользовавшись как предлогом Краковским восстанием февраля 1846 г., Россия, Австрия и Пруссия на конференции в Вене постановили упразднить вольный город и присоединить его к землям Австрии; возражения Англии и Франции остались безрезультатными.", "bf12c063"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["Борну переходит под власть Рабиха ибн аз-Зубайра", "8be4ca96"], "d": ["Суданский военачальник Рабих ибн аз-Зубайр, потрясший Багирми и Вадаи, захватил Борну; к 1896 г. он овладел всей страной и сделал своей столицей Dikeo.", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["Рабих ибн аз-Зубайр разбит французами и убит — его власть в Борну распалась", "fb5a3ace"], "d": ["Рабих, потерпевший поражение от французской колониальной армии, был убит; его сын хотел удержать власть, но не смог, и в 1902 г. Борну было поделено между Францией, Англией и Германией.", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["Провозглашено Временное правительство Западной Фракии (Garbî Trakya Hükûmet-i Muvakkatesi) с центром в Комотини", "974b2e28"], "d": ["Когда Бухарестский мир (10 августа 1913) отдал Западную Фракию Болгарии, турецкое население области провозгласило временное правительство с центром в Комотини; после взятия Дедеагача правительство объявило о своей независимости под названием «Garbî Trakya Hükûmet-i Müstakillesi». Из-за вмешательства великих держав османское правительство его не поддержало; Константинопольский договор от 29 сентября 1913 года оставил Западную Фракию болгарам, и правительство просуществовало лишь пятьдесят семь дней, до 25 октября 1913 года.", "86d3bfee"]},
"OLAYLAR_EK12:1920-11-15:0":{"b": ["Вольный город Данциг основан под защитой Лиги Наций", "bd148fe8"], "d": ["Данциг, отделённый от Германии Версальским договором, с 10 января 1920 года находился в переходном управлении союзных великих держав; 15 ноября 1920 года он был основан как вольный город под защитой Лиги Наций, находящийся в таможенном союзе с Польшей.", "c74affc1"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["Кончина Орхан-гази — конец сорока лет, превративших бейлик в государство", "62c59cfd"], "d": ["Орхан-гази, возглавивший бейлик после смерти Осман-гази в 1324 г., за тридцать восемь лет своего правления превратил Османов из пограничного бейлика в государство, утвердившееся по обе стороны Мраморного моря: были взяты Бурса (1326), Изник (1331) и Измит (1337), присоединён бейлик Каресиды, отчеканена первая акче (1327), основано первое медресе в Изнике (1331), а переход в Румелию стал прочным через Цимпе (1352) и Галлиполи (1354). Старшего сына Сулейман-пашу, руководившего завоеванием Румелии, он потерял в 1357 г. из-за несчастного случая на охоте; сам он скончался в Бурсе в марте 1362 г., и ему наследовал сын Мурад I.", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["Переход островов Бахрейна к Джабридам", "6a242b16"], "d": ["Статья TDV о Бахрейне отмечает, что остров «последовательно находился под властью Уйунидов, Салгуридов, Tabî, Джабридов, и при Джабридах большинство перешло от шиизма к суннизму», не давая ни одной даты. В общей литературе династия Джабридов возникла в начале XV в., свергнув последнего правителя Cervânî в Катифе, и в пору наивысшего расцвета (Аджвад ибн Замиль, ум. 1496) контролировала весь арабский берег Персидского залива, Хасу, Катиф и острова Бахрейна. После Аджвада острова Аваль перешли к Мукрину ибн Замилю — это правитель, которому предстояло потерпеть поражение от португальцев в 1521 г.", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["Взятие Асилы португальцами — второй плацдарм на берегу Марокко", "83444a11"], "d": ["Афонсу V высадился на марокканском берегу лично с войском в 30.000 человек и флотом в 400 судов и 24 августа 1471 г. взял Асилу, находившуюся под властью Ваттасидов. Падение города сломило сопротивление Танжера; Танжер сдался без боя четыре дня спустя, 28 августа. Так Португалия после Сеуты (1415) и Ксар-эс-Сегира (1458) создала на атлантическом побережье Марокко третий и четвёртый опорные пункты; после этого похода король велел добавить к своему титулу слова «владыка Африки».", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["Переход Сафи под португальское влияние", "765e703e"], "d": ["Сафи, самый оживлённый порт зерна и рыболовства на Атлантическом побережье, в 1488 г. перешёл под португальское влияние; некоторое время город управлялся местными правителями под португальским покровительством, а в 1508 г. был занят непосредственно. Поскольку источники по-разному расставляют акценты в этих двух стадиях, дата начала колеблется между 1488 и 1508 гг.; обе — крайние точки одного процесса. Сафи оставался в руках Португалии пятьдесят три года и был оставлен в 1541 г. после падения Агадира.", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["Основание Santa Cruz do Cabo de Gué — португальской крепости в Агадире", "cc22c433"], "d": ["Крепость Santa Cruz do Cabo de Gué, построенная частной инициативой на побережье Суса, в пункте, до которого Португалия прежде не доходила, была возведена в 1505 г. и в 1513 г. передана португальской короне. Контролируя торговлю сахаром и золотом долины Суса, крепость закрывала юго-западный выход из Марракеша, и поэтому стала первой крупной целью движения Саадидов. Осада 1533 г. была отбита, осада 1541 г. завершилась успехом и положила начало крушению Португалии в Марокко.", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["Взятие Азаммура — контроль над устьем Умм-эр-Рбии", "232acd4b"], "d": ["Португальское войско под командованием герцога Брагансского Жайме 3 сентября 1513 г. вошло без сопротивления в Азаммур в устье реки Умм-эр-Рбия. Взятие города дало контроль и над устьем реки, и над зерновым путём во внутренние области, а на следующий год открыло путь к основанию крепости Мазаган в 12 км к юго-западу. Азаммур оставался в руках Португалии двадцать восемь лет.", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["Основание крепости Мазаган — самого долговечного португальского пункта в Марокко", "786cdb40"], "d": ["Через год после взятия Азаммура, летом 1514 г., на побережье была построена крепость Мазаган. После общего краха 1541 г., когда Португалия оставила все свои пункты в Марокко, Мазаган она не оставила; напротив, крепость была перестроена заново с бастионами в итальянском стиле и удерживалась двести пятьдесят пять лет. Большая осада 1562 г. также была отбита. Мазаган как последний португальский пункт в Марокко предстояло оставить в 1769 г.", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["Сдача крепости Мардин — конец сефевидского сопротивления к югу от Диярбакыра", "e6226de5"], "d": ["Когда Бийыклы Мехмед-паша, двигавшийся после Чалдырана к области Диярбакыра, осадил Мардин, сефевидские войска в октябре 1515 г. отошли в крепость; хотя город перешёл в руки османов, крепость сопротивлялась. Контрнаступление сефевидского наместника Кара-хана с подкреплением завершилось в мае 1516 г. битвой при Koçhisar (Kızıltepe): в сражении, шедшем весь день в степи Dede Garkın, Кара-хану отрубили голову, а его войско было рассеяно. Крепость же, по выражению TDV, сдалась «лишь девять месяцев спустя».", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["Взятие Бахрейна Португалией — конец власти Джабридов", "315a435a"], "d": ["После того как джабридский правитель Мукрин ибн Замиль отказался платить дань Ормузу, на остров высадились португальский флот и войска вассального Португалии Ормузского царства; Мукрин был разбит в сражении, и Бахрейн в 1521 г. перешёл под португальское управление. Затем в течение восьмидесяти лет остров управлялся через Ормуз, преимущественно суннитскими иранскими наместниками. Жемчужины Бахрейна и его стратегическое положение сделали остров прямой целью османско-португальского соперничества в заливе.", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["Падение Агадира — Саадиды начинают вытеснять Португалию из Марокко", "bb1568f6"], "d": ["Саадидский султан Мухаммад аш-Шейх осадил крепость Санта-Круш 16 февраля 1541 г. и взял её 12 марта; около шестисот португальцев, включая наместника Гутерре де Монроя, попали в плен.", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["Оставление Сафи и Азаммура — Португалия уходит с Атлантического побережья", "4cb6099a"], "d": ["После падения Агадира 12 марта 1541 г. и неудачи в заключении ожидавшегося союза с марокканским султаном Жуан III приказал оставить два крупных пункта на Атлантическом побережье; эвакуация Сафи и Азаммура была завершена осенью 1541 г., в сентябре — октябре. Так за один год были потеряны три пункта, и полувековое расширение Португалии на марокканском берегу обратилось вспять; остались Сеута, Танжер, Асила, Ксар-эс-Сегир и заново укреплённый Мазаган.", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["Оставление Асилы — Португалия сжимает северное побережье", "b5d18373"], "d": ["Из-за сочетания финансового кризиса и давления Саадидов Жуан III оставил Асилу, удерживавшуюся с 1471 г. Присутствие Португалии в Марокко таким образом сократилось до Сеуты, Танжера и Мазагана. Асилу предстояло ненадолго вновь занять в 1577 г., а окончательно оставить в 1589 г.", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["Османский поход на Бахрейн — последний крупный шаг против Португалии в заливе", "14501df3"], "d": ["Османское государство, утвердившееся на арабском берегу залива после присоединения Басры в 1546 г. и образования эйялета Хаса, нацелилось на жемчужную торговлю острова и ормузскую линию Португалии и выступило на Бахрейн под командованием бейлербея Хасы Мустафа-паши. Итог похода в источниках расходится: TDV İslâm Ansiklopedisi пишет, что османы «в 1559 г. овладели Бахрейном и основали там базу», а острова «позднее вновь перешли под управление португальцев»; западная же литература сообщает, что осада провалилась, что подкрепление португальцев, пришедшее морем из Ормуза, отбросило османские силы и что после эпидемии чумы, сломившей обе стороны, османы запросили условий капитуляции. Два рассказа расходятся в самом исходе; общее у них то, что Бахрейн не остался за османами надолго.", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["Взятие Туниса Улудж Али-пашой — конец хафсидско-испанского порядка", "d4498698"], "d": ["Когда Карл V в 1535 г. взял Тунис, он не стал управлять городом сам, а вернул на престол хафсидского султана Мулая Хасана; по выражению TDV, город Тунис оставался «под покровительством испанцев и под управлением Мулая Ахмада III вплоть до второго вмешательства османов в 1569 г.». Улудж Али, назначенный 27 июня 1568 г. бейлербеем Алжира, двинулся на Тунис по суше, разбил хафсидского султана у Беджи и вошёл в город; Мулай Ахмад укрылся в испанском пресидио Голетта. Так залив оказался поделён надвое — город стал османским, портовая крепость осталась испанской, — и это разделение продлилось четыре года.", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["Возвращение Туниса доном Хуаном Австрийским — единственный сухопутный отклик Лепанто", "a6f044ee"], "d": ["Хотя после Лепанто (1571) Священная лига распалась, Испания одна взяла на себя бремя действий в Северной Африке: по словам TDV, «10 октября 1573 г. испанцы предприняли новый поход, чтобы установить контроль над Тунисом. Взяв Тунис, они оставили там 8000 солдат». Этот поход под командованием дона Хуана Австрийского — единственное место, где победа при Лепанто нашла отклик на суше; однако он не стал прочным, и город был возвращён через одиннадцать месяцев. Вторжение разрушило уже сложившееся османское управление: 2 зу-ль-хиджа 980 г. х. (5 апреля 1573 г.) командующим в Тунисе был Кылыч Али-паша, каймакамом — Рамазан-паша, бейлербеем — Хайдар-паша.", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["Взятие Бахрейна у Португалии Сефевидами", "c37d982c"], "d": ["Войска, посланные шахом Аббасом I, соединились с мятежниками на острове и вывели португальский гарнизон из крепости; по выражению TDV, острова были отняты у португальцев «в 1602 г. силами, подчинёнными Ирану». Бахрейн, таким образом, вышел из-под португальского управления, длившегося восемьдесят один год, перешёл под власть Сефевидов и сто пятнадцать лет оставался зависимым от Ирана. Это первое звено в распаде португальского присутствия в заливе; двадцать лет спустя сам Ормуз должен был пасть в результате совместной англо-иранской операции.", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["Вторжение оманцев на Бахрейн — конец сефевидской власти", "c9be5820"], "d": ["В пору распада Сефевидского государства в его последние годы оманский флот под управлением династии Ярубидов вторгся на остров, и власть Сефевидов закончилась. Последовавшие тридцать пять лет — самый запутанный период в истории залива: остров несколько раз переходил из рук в руки между Оманом, Ираном и местными арабскими силами.", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["Переход Бахрейна под управление Аль Мазкур в Бушире", "610e2f9d"], "d": ["Семья Âl-i Mezkûr, происходившая из Омана, поселившаяся в Бушире и считавшаяся Huvele, в 1753 г., действуя из своих баз в Бушире, взяла Бахрейн под своё управление. Семья возглавляла арабские общины на заливном берегу Ирана и управляла островом от имени Ирана; её последний представитель Наср Âl-i Mezkûr был назначен на должность наместника Бахрейна зендским правлением. Это последнее управление островом перед Аль Халифа.", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["Оставление Мазагана — последний португальский пункт в Марокко пал", "f9e9749d"], "d": ["Гарнизон в 592 человека не смог устоять перед осадой, начатой алауитским султаном Мухаммадом III ибн Абдаллахом в начале 1769 г.; эвакуационный флот, вышедший из Лиссабона 1 февраля, 11 марта 1769 г. принял на борт последних солдат, а город последним покинул наместник Диниш Грегориу. Так присутствие Португалии в Марокко, начавшееся в 1415 г. взятием Сеуты, закончилось через три с половиной века. Мазаган был единственным пунктом на Атлантическом побережье, удерживавшимся после общего краха 1541 г., и с двумястами пятьюдесятью пятью годами стал местом, дольше всего остававшимся в руках Португалии в Марокко.", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["Завоевание Бахрейна Аль Халифа — основание правящей по сей день династии", "8773b011"], "d": ["Наср Âl-i Mezkûr, бахрейнский наместник зендского правления, осадил Зубару на полуострове Катар; силы утуб под командованием Ахмада ибн Мухаммада ибн Халифы разорвали осаду, перешли в контрнаступление и в том же году взяли Бахрейн. Запись TDV коротка: «Бахрейн в 1783 г. перешёл под власть Аль Халифа из племени утуб». Ахмад ибн Мухаммад после этой победы стал называться «аль-Фатих», и основанная им династия правит островом по сей день.", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["Договор Бахрейна с Англией — вступление в систему протектората в заливе", "576796b2"], "d": ["По записи TDV, «21 мая 1861 г. Англия и Али, брат шейха Мухаммада, представлявший Бахрейн, подписали соглашение, запрещавшее в регионе работорговлю и пиратство»; в английских документах тот же договор (Perpetual Truce of Friendship and Peace) датирован 31 мая 1861 г. Договор — первое звено системы протектората, связавшей внешние отношения Бахрейна с Англией, и остров остался вне этой системы и после того, как османы в 1871 г. вновь утвердились в Хасе и Катифе.", "ab2ad5ff"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["Ахи Эвран — покровитель-основатель организации ахи", "3392e100"], "d": ["Ахи Эвран считается одним из основателей организации ахи в Анатолии и покровителем кожевников (debbağ). Его завийе в Кыршехире сохранялось в османский период как духовный центр ремесленной организации (эснаф/цех) вплоть до начала XX в.; государство официально подтверждало это положение в 1780, 1782, 1822–23 и 1842 гг.", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["Шейх Эдебали — основополагающая связь между организацией ахи и османской династией", "c1186059"], "d": ["Эдебали, основавший завийе в Биледжике и бывший также одним из шейхов организации ахи, по преданию истолковал знаменитый сон Осман-гази; затем Осман-гази женился на дочери Эдебали Мальхун-хатун. Эдебали считается также первым османским кадием и муфтием.", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["Орхан-гази выделяет после завоевания Бурсы площадку для игр cirit", "da1becbd"], "d": ["По статье TDV о cirit, Орхан-гази после завоевания Бурсы выделил как вакф участок в её окрестностях для скачек и игр cirit — это один из первых зафиксированных в записях примеров институционализации игры cirit у османов.", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["Предание о начале борцовских состязаний Kırkpınar", "2d93fa65"], "d": ["По преданию, традиция борьбы Kırkpınar началась с борцовских состязаний среди сорока гази, перешедших в Румелию вместе с завоевателем Румелии Сулейман-пашой. Статьи TDV о борьбе и о Kırkpınar приводят это предание, но точной даты основания не дают.", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["Основание корпуса янычар", "f4206dce"], "d": ["Система, начавшаяся по указанию Чандарлы Кара Халиля и Молла Рустема с обучения молодых немусульман, взятых из военнопленных в соответствии с законом pencik, получила институциональный облик через Acemi Ocağı (корпус новобранцев), основанный в Галлиполи, при Мураде I.", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["Начало строительства Старой мечети в Эдирне (Улу-джами)", "da7a22ac"], "d": ["Строительство Эскиджами, известной в народе также как Улуджами (Джами-и Атик), было начато Эмиром Сулейманом Челеби в 1402–1403 гг.", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["Начало строительства комплекса Зелёной мечети в Бурсе", "280b8a21"], "d": ["Мехмед I, вновь объединивший престол после эпохи Междуцарствия, начал строительство комплекса в 1414 г. и поместил его в центральной точке Бурсы так, чтобы отличать от комплексов деда и отца. Главный зодчий — Хаджи Иваз-паша.", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["Завершение комплекса Зелёной мечети в Бурсе", "bc82821f"], "d": ["Комплекс Зелёной мечети, известный изразцовой и декоративной программой, в которой участвовали и тебризские мастера, был завершён в декабре 1419 г. Комплекс состоит из мечети, тюрбе (Зелёное тюрбе), медресе, имарета и хамама; это один из богатейших образцов ранней османской архитектуры.", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["Фактическое начало применения системы девширме", "fa835172"], "d": ["Порядок девширме, не встречавшийся в прежних исламских государствах, начался прежде всего как использование юношей-немусульман из военнопленных в соответствии с законом pencik. По TDV, «понятно, что он применялся при Челеби Мехмеде, но получил законодательное оформление при его сыне Мураде II».", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["Учреждение должности шейх-уль-ислама — назначение Молла Фенари бурсским муфтием", "2a8ee2b9"], "d": ["Назначение учёного Молла Фенари, многие годы бывшего кадием Бурсы, в 1425 г. бурсским муфтием считается, по выражению TDV, «началом муфтийства и шейх-уль-исламства у османов». Однако TDV отмечает, что оно не тождественно полностью институционализированной должности шейх-уль-ислама, представлявшей в XVI в. всю организацию ильмийе.", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["Институционализация системы тимаров", "dc267780"], "d": ["Документально подтверждённые первые упоминания тимара восходят ко времени Орхан-бея; систематическая кодификация же произошла при Мураде II. Составленные в это время сводные тимарные книги (icmal defterleri) показывают, что все основные принципы системы сложились; документы, относящиеся примерно к 1432 г., доказывают, что законы были полностью в силе.", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["Завершение мечети Üç Şerefeli и её комплекса", "cde6993e"], "d": ["Мечеть Üç Şerefeli, построенная по приказу Мурада II мастерами Муслихуддином и Шехабеддином за десять лет (1437–1447), считается первым примером центрально-купольных мечетей в османской архитектуре и одной из переломных вех переходной архитектуры, предшествовавшей классическому периоду.", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["Институционализация Императорского дивана законом Завоевателя", "e8443e77"], "d": ["Диван при Мураде II в Эдирне был подчинён регулярным правилам и начал приобретать облик «Dîvân-ı Hümâyun» (Императорский диван). Главное преобразование принёс закон Мехмеда Завоевателя: крупнейшим новшеством было полное упразднение председательства падишаха в диване и передача его великому визирю.", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["Передача Мехмедом Завоевателем Okmeydanı лучникам", "342a9fd5"], "d": ["Мехмед Завоеватель, расположивший во время завоевания Стамбула свой стан на склонах Касымпаши, использовал это место также как учебное поле для лучников; взяв город, он закрепил эту территорию за лучниками навсегда. Это закрепление — начало превращения Okmeydanı в центр османской традиции стрельбы из лука, которой предстояло просуществовать столетия.", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["Бурса достигает вершины в торговле иранским шёлком", "f1324cdf"], "d": ["Караваны из Тебриза доставляли в Бурсу шёлк Гиляна, Астрабада и Сари, и здесь генуэзские, венецианские, флорентийские и еврейские купцы наперебой его покупали. В 1479 г. стоимость шёлка, ввезённого из Ирана, достигла 150.000 венецианских золотых; в 1502 г. в городе работало более 1000 ткацких станков.", "0f47c417"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["Баязид II назначает большие награды борцам Kırkpınar", "d745b882"], "d": ["По статье TDV о борьбе, Баязид II в 1504 г. назначил борцам награды в 3.000 и 1.500 курушей; это один из ранних зафиксированных в записях примеров покровительства османского двора борьбе как виду спорта.", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["Завершение мечети Баязида и её комплекса", "eb9ab65b"], "d": ["Строительство мечети Баязида и её комплекса, возводимых для Баязида II, согласно архивному документу началось в 906 г. х. (1500 г.) и было завершено 14 джумада аль-уля 911 г. х. (13 октября 1505 г.). Имя зодчего спорно: опираясь на запись Айвансарайи, мечеть долгое время считали творением Мимара Хайреддина, затем её приписали Мимару Кемаледдину, а по мнению некоторых, они работали вместе; тот же документ показывает, что мастером был Якуб-шах ибн Султан-шах. Мечеть считается одним из важных памятников перехода от доклассической османской архитектуры к классической эпохе.", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["Перенос Tersâne-i Âmire в Стамбул (Касымпаша/Золотой Рог)", "f36e3675"], "d": ["При Селиме I Грозном новая верфь, строительство которой началось в бухте к западу от стен Галаты, была в 1515 г. завершена со 160 доками; так деятельность верфей с центром в Галлиполи была перенесена в Стамбул. Позднее, при Барбаросе Хайреддин-паше, учреждение официально получило название «Tersâne-i Âmire» (Императорская верфь).", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["Кончина шейха Хамдуллаха и наследие школы каллиграфии", "f5ed4d09"], "d": ["Шейх Хамдуллах из Амасьи, наставник Баязида II по каллиграфии, довёл до зрелости школу aklâm-ı sitte (шесть видов письма) и стал основателем османского каллиграфического стиля, которому предстояло занять господствующее положение во всём исламском мире. Когда он скончался в 1520 г., он оставил после себя широкий круг учеников.", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["Завершение Пири-реисом первой редакции Kitâb-ı Bahriye", "fd6cc1ff"], "d": ["Первую (прозаическую) редакцию Kitâb-ı Bahriye, в которой собраны сведения о берегах Средиземного моря, портах и мореплавании, Пири-реис завершил в 1521 г. Эта первая редакция ещё не была представлена падишаху и представляла собой черновик, который предстояло расширить в последующие годы.", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["Расширение Пири-реисом Kitâb-ı Bahriye и его подношение султану Сулейману Кануни", "d4abf0b7"], "d": ["Пири-реис, расширив Kitâb-ı Bahriye частично в стихотворной форме, в 1526 г. поднёс её султану Сулейману Кануни. В таком виде сочинение получило широкое распространение как самое полное навигационное руководство османского мореплавания.", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["Изображение Матракчи Насухом маршрута похода Irakeyn в Beyân-ı Menâzil", "aa012278"], "d": ["Матракчи Насух, участвовавший в первом иранском походе (Irakeyn) Сулеймана Кануни в 1534 г., изобразил в технике миниатюры-карты каждую стоянку на маршруте армии из Стамбула в Тебриз и оттуда в Багдад. Эта работа вошла в сочинение Beyân-ı Menâzil-i Sefer-i Irâkeyn и является самым самобытным образцом жанра menzilname у османов.", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["Физули подносит Кануни касыду после завоевания Багдада", "1ef0653f"], "d": ["После завоевания Багдада Сулейманом Кануни в 1534 г. Физули поднёс османскому султану пять касыд, включая знаменитую касыду, начинающуюся строкой «Geldi burc-ı evliyâya pâdişâh-ı nâmdâr»; так он вышел из-под сефевидского покровительства и стал искать покровительства османских государственных деятелей.", "b8e9e300"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["Завершение Физули поэмы-месневи Лейли и Меджнун", "e3ef4085"], "d": ["Лейли и Меджнун, считающаяся одной из прекраснейших месневи классической турецкой литературы, была написана и завершена Физули в 1535 г. по просьбе стамбульских поэтов, принимавших участие в багдадском походе Кануни.", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["Назначение Мимара Синана главным придворным архитектором", "7a753f0e"], "d": ["По статье TDV İslâm Ansiklopedisi о Синане, после смерти в 1537 г. главного придворного архитектора Аджеми Али, Синан, обративший на себя внимание мостом, построенным через реку Прут во время похода в Молдавию, по представлению великого визиря Лютфи-паши был назначен на эту должность. Так началась эпоха Синана на посту главного архитектора, которой предстояло продлиться более пятидесяти лет.", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["Начало строительства комплекса мечети Шехзаде", "1a70ddfd"], "d": ["Султан Сулейман Кануни в 1543 г. приказал построить комплекс в память сына, шехзаде Мехмеда, умершего во время эпидемии чумы; строительство началось в июне 1543 г., сначала был завершён тюрбе, затем перешли к строительству мечети. Это здание — по собственному выражению Мимара Синана, «творение моего ученичества».", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["Завершение комплекса Михримах-султан у пристани Ускюдара", "3769007f"], "d": ["Строительство комплекса на площади у пристани Ускюдара началось в первые годы 1540-х гг. и было завершено в 1547 г. По хронологии это первая из двух больших мечетей, построенных Михримах-султан у Мимара Синана; вторая (Эдирнекапы) будет завершена примерно двадцатью годами позже.", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["Открытие Венецией консульства в Алеппо", "3aad8b9e"], "d": ["В XVI в. центр европейской торговли переместился из Дамаска в Алеппо. Конкретным показателем этого сдвига стало открытие Венецией в 1548 г. консульства в Алеппо; за ней последовали Франция в 1557 г. и Англия в 1586 г. Город стал главным рынком, где обменивались европейские шерстяные ткани и серебро на индийские пряности, а к концу века — и на иранский шёлк.", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["Открытие мечети Шехзаде для богослужения", "2bb3f4b2"], "d": ["После строительства, продлившегося около пяти лет, мечеть Шехзаде была открыта для богослужения в августе 1548 г. Благодаря плану с двумя минаретами и центральным куполом она считается предвестником последующих великих творений Мимара Синана; комплекс состоит из мечети, тюрбе, медресе, имарета, табхане и караван-сарая.", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["Начало строительства водопровода Кыркчешме", "14124b59"], "d": ["Мимар Синан, по приказу Кануни изучив возможность подвода воды в Стамбул из Белградского леса, сообщил, что это осуществимо; строительство большого водного сооружения началось в 1554 г. и было завершено до 1563 г. TDV описывает это сооружение как «наиболее важное с инженерной точки зрения и наибольшее по объёму творение» Синана.", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["Открытие первых кофеен в Стамбуле", "85c12f9f"], "d": ["Появление кофе в османской городской жизни началось с кофеен, открытых в Tahtakale алеппским купцом Хакемом и неким дамаскином по имени Шемс. Вскоре возникло новое общественное пространство, где собирались люди из всех слоёв общества; в последние годы Кануни в Стамбуле было пятьдесят кофеен.", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["Правовое рассмотрение Эбусууд-эфенди вопроса о гедике (праве ремесленной монополии)", "5d4e2930"], "d": ["Вопрос о «гедике» — праве монополии и привилегии, предоставляемом определённому числу лиц в ремесле, — вновь встал на повестку при Кануни; шейх-уль-ислам Эбусууд-эфенди в 1555–56 гг. глубоко изучил вопрос и представил падишаху довод о законности этой практики.", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["Завершение Сейди Али-реисом сочинения Mir'âtü'l-Memâlik в Стамбуле", "ee8640e1"], "d": ["Сочинение о путешествии Mir'âtü'l-Memâlik, которое Сейди Али-реис писал, начав с Багдада, на протяжении всего обратного пути, он завершил в Стамбуле в январе 1557 г. Это первоисточник, рассказывающий о возвращении османского мореплавателя на родину по суше через Среднюю Азию из Индийского океана.", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["Сооружение комплекса (мечети) Рустем-паши", "02e30725"], "d": ["Комплекс, построенный у Мимара Синана зятем и великим визирем Кануни Рустем-пашой, возводился в 1555–1561 гг. Здание известно самобытной архитектурой на приподнятой платформе с арочными лавками внизу и богатыми изникскими изразцами.", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["Завершение Мостарского моста", "e7f434af"], "d": ["Знаменитый Мостарский мост через реку Неретву был построен около 1566–67 гг. Мимаром Хайреддином; упоминание моста в официальном документе 1568 г. подтверждает, что он был завершён. Сооружение — один из самых известных образцов классической османской мостовой архитектуры с одним пролётом стрельчатой арки.", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["Завершение мечети Эдирнекапы (Михримах-султан)", "f2d21a82"], "d": ["Строительство мечети, начатое после подтверждения в 1563 г. разрешения на сооружение для дочери Кануни Михримах-султан, было завершено в 1566 г.; вакфная грамота комплекса составлена в 1570–71 гг. Это здание — одно из крупных творений Мимара Синана, ближайших к стенам Стамбула.", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["Баки пишет элегию на смерть Сулеймана Кануни", "7aa6665f"], "d": ["Когда из Сигетвара пришла весть о смерти султана Сулеймана Кануни, Баки, тогдашний «султан поэтов», написал одну из самых знаменитых элегий османской литературы.", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["Баки подносит Селиму II джулусийе", "6027f034"], "d": ["Сразу после восшествия Селима II на престол Баки поднёс новому падишаху «джулусийе» (стихотворение о восшествии на престол) — по TDV, сразу вслед за элегией, написанной на смерть Кануни.", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["Завершение моста в Бююкчекмедже", "5f49b3c5"], "d": ["Мост, начатый по приказу султана Сулеймана Кануни, был в 1567–68 гг. достроен по распоряжению его сына Селима II в связи со смертью падишаха во время похода на Сигетвар. Мимар Синан сам отремонтировал и те участки моста, построенного в месте впадения озера Бююкчекмедже в море, которые пострадали от наводнения.", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["Начало строительства мечети Селимие (Эдирне)", "07e18c9e"], "d": ["Строительство Селимие, которую Мимар Синан называл «творением мастерства», началось от имени Селима II в 1568 г. и, продлившись шесть лет, было завершено в 1574 г. (завершение уже записано в хронологии). Западные лавки арасты и начальная школа были достроены Давуд-агой при Мураде III, после смерти Селима II.", "a3d4551b"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["Кончина Кыналызаде Али Челеби — автора Ahlâk-ı Alâî, классического текста османской философии нравственности", "dd921873"], "d": ["Кыналызаде Али Челеби, автор Ahlâk-ı Alâî — самого известного классического текста османской философии нравственности, скончался 22 января 1572 г., будучи казаскером Анатолии. В стамбульских библиотеках имеется более семидесяти списков его сочинения.", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["Сооружение комплекса Пияле-паши", "75411278"], "d": ["Каптан-и дерья Пияле-паша, зять Селима II, купил участок под комплекс в 1573 г. и построил его у Мимара Синана. Комплекс был задуман как обширное сооружение, состоящее из мечети, медресе, текке, тюрбе, кладбища, начальной школы, фонтана, рынка и хамама.", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["Завершение моста Дрина (Мехмед-паши Соколлу)", "1d668c73"], "d": ["Мост, построенный Мимаром Синаном под покровительством великого визиря Соколлу Мехмед-паши, согласно дате на надписи был завершён в 1577–78 гг.; некоторые исследователи утверждают, что строительство началось в 1571–72 гг. Мост — символ привязанности Соколлу к Вышеграду, где он родился.", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["Сооружение мечети Азапкапы (Соколлу Мехмед-паши)", "f7b57feb"], "d": ["Мечеть, расположенная у опоры моста Unkapanı со стороны Şişhane, была построена великим визирем Соколлу Мехмед-пашой у Мимара Синана. Здание — одна из двух мечетей Синана, возведённых на имя Соколлу (другая — мечеть в Kadırga).", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["Приказ Мурада III о составлении Hünernâme", "b125710d"], "d": ["Указом от 2 января 1578 г. Мурад III приказал Сейиду Локману написать Hünernâme, посвящённую жизни падишахов от Осман-гази до его собственной эпохи; миниатюры к сочинению были выполнены Наккашем Османом и его командой.", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["Завершение мечети Зал Махмуд-паши", "732f75bc"], "d": ["В строительстве комплекса, начатом после брака Зал Махмуд-паши с Шах-султан в 1574 г., сооружение мечети было завершено в 1580 г.; медресе строились до 1582 г., а фонтан — до 1590 г. Комплекс выделяется самобытным планом с двумя симметричными минаретами на склонах Эюпа.", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["Завершение второго тома Hünernâme", "70a1e741"], "d": ["Второй том Hünernâme был завершён в январе 1588 г.; с 65 миниатюрами он стал одним из самых ценных в документальном отношении сочинений османской историографии. Оба тома иллюстрированы в мастерской Наккаша Османа.", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["Давуд-ага становится главным придворным архитектором", "8cdc7f53"], "d": ["После краткого перерыва после смерти Мимара Синана в 1588 г., начиная с 1592 г. Давуд-ага стал упоминаться в официальных документах как главный придворный архитектор. Давуд-ага, взявший на себя некоторые дополнительные элементы комплекса Селимие и первое строительство Новой мечети, — один из важнейших зодчих своего времени.", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["Закладка фундамента Новой мечети (Эминёню)", "d3cddc01"], "d": ["Фундамент мечети под покровительством Сафие-султан, матери Мехмеда III, был заложен: грунт укрепили сваями, и фундамент положили из каменных блоков. Две разные статьи TDV дают для этого события разные даты (статья о комплексе Йени-джами — 9 апреля 1598 г., статья о Давуд-аге — 23 августа 1597 г.); здесь за основу принята дата из особой статьи о самом здании.", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["Смерть Давуд-аги от чумы и остановка строительства Новой мечети", "81f2cd04"], "d": ["Давуд-ага, умерший в сентябре 1598 г. во время эпидемии чумы, когда Новая мечеть была поднята над землёй лишь на один зира, был заменён на посту главного архитектора Далгыч Ахмед-чаушем. TDV отмечает, что в альтернативном предании, основанном на хронограмме, дата смерти указывается также как 1599–1600 гг. и что точная дата не установлена.", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["Интенсивный вывоз анкарского софа в Европу", "3f37018d"], "d": ["Соф и шали, ткавшиеся в Анкаре, вывозились не только на внутренние рынки — Стамбул, Бурсу, Дамаск, Алеппо, — но и в Венецию, Польшу, Англию и Францию. В приведённом TDV примере в 1599 г. восемнадцать купцов купили 162 тюка софа на сумму 5.700.000 акче и отправили их в Алеппо и Венецию.", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["Остановка строительства Новой мечети в связи со смертью Мехмеда III", "5acef053"], "d": ["После смерти Мехмеда III, сына основательницы Сафие-султан, в 1603 г. Сафие-султан была отправлена в Старый дворец, и строительство Новой мечети осталось незавершённым; здание в таком виде ждало завершения около шестидесяти лет.", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["Катиб Челеби начинает в Алеппо исследования для Keşfü'z-Zünûn", "094e6870"], "d": ["Катиб Челеби в 1633 г. в Алеппо начал собирать материал для Keşfü'z-Zünûn, которой предстояло стать его библиографическим шедевром. На протяжении этой работы, которая продлится двадцать лет, он по одному обследовал библиотеки и книжные лавки городов, в которых бывал.", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["Казнь Нефи за его сатиры", "5e459c60"], "d": ["Диванный поэт Нефи, известный своими сатирами, в 1635 г. по приказу Мурада IV был казнён из-за сборника сатир Sihâm-ı Kazâ. Великий визирь Байрам-паша выдал его; Нефи был задушен в дровяном сарае дворца, а тело брошено в море.", "e3b52153"]},
"OLAYLAR_EK14:1640-01-01:0":{"b": ["Первое путешествие Эвлии Челеби — начало Seyahatnâme", "ca3ce3f9"], "d": ["Эвлия Челеби в 1640 г. совершил первое путешествие за пределы Стамбула — в Бурсу — и положил начало сорокалетней жизни в странствиях, ставшей основой его десятитомной Seyahatnâme. Сочинение, не завершённое из-за смерти автора около 1684 г., внезапно обрывается в десятом томе.", "1db7969c"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["Составление обширной книги нарха", "6c1e231b"], "d": ["Хотя практика нарха (предельных цен) у османов очень древняя, самая обширная из дошедших до нас книг нарха датирована 1640 г.; эта книга, охватывающая продовольствие, одежду, услуги, стандарты и гигиенические условия, по выражению TDV, «функционировала как полноценный кодекс регулирования рынка».", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["Катиб Челеби впервые приступает к сочинению Cihannümâ", "554c6734"], "d": ["Катиб Челеби, стремясь восполнить пробел в османских географических знаниях перед лицом географических открытий Запада, в 1648 г. приступил к первой редакции Cihannümâ. Эта первая версия осталась незавершённой, потому что о некоторых европейских странах не нашлось достаточных источников.", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["Созревание системы ильтизам, оказавшейся в монополии военного сословия", "2c587934"], "d": ["Порядок ильтизам (отдача сбора налогов частным лицам за плату) применялся со второй половины XV в., но с начала XVI в. быстро распространялся. По TDV, процесс полного перехода этого сектора в монополию представителей военного сословия завершился в 1650 г.; ильтизам тем самым стал основным финансовым методом, сменившим систему тимаров.", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["Катиб Челеби заново приступает к сочинению Cihannümâ", "e9c68110"], "d": ["Оставив первую редакцию незавершённой, Катиб Челеби в конце 1654 г. вновь приступил к сочинению Cihannümâ с самого начала. Эта вторая версия также осталась незавершённой; сочинение дошло до Вана, когда смерть автора в 1657 г. оборвала его, и оно было напечатано в таком виде лишь в 1732 г. Ибрагимом Мютеферрикой.", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["Завершение Новой мечети и открытие её для богослужения", "d6d86c82"], "d": ["Строительство Новой мечети, остававшееся незавершённым более шестидесяти лет, было завершено под руководством главного архитектора Мереметчи Мустафа-аги, назначенного в 1661 г. Хатидже Турхан-султан (валиде), и она была открыта для богослужения 30 октября 1665 г. пятничной молитвой.", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["Мехмед IV устраивает многодневные игры cirit на свадьбе обрезания в Эдирне", "3638a5b6"], "d": ["Мехмед IV на празднествах по случаю обрезания шехзаде, устроенных им в Эдирне в 1675 г., организовал многодневные состязания cirit; в статье TDV о cirit это особо упоминается как один из самых пышных примеров поддержки, оказанной османским двором спорту cirit.", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["Хафиз Осман вырабатывает самобытный каллиграфический стиль", "93081cb3"], "d": ["Хафиз Осман, продолжатель линии шейха Хамдуллаха, в 1679 г. выработал в aklâm-ı sitte новый самобытный стиль, который позднее стал называться «школой Хафиза Османа». Этот стиль дошёл до наших дней в двух отдельных ветвях.", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["Назначение Хафиза Османа наставником Мустафы II по каллиграфии", "d976cda4"], "d": ["Хафиз Осман, считавшийся самым искусным каллиграфом своего времени, в 1695 г. был назначен наставником по каллиграфии только что взошедшего на престол Мустафы II. За свою жизнь он воспитал около пятидесяти каллиграфов и переписал 25 экземпляров Корана.", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["Кончина Итри", "62750526"], "d": ["Бухуризаде Мустафа Итри-эфенди, один из величайших композиторов турецкой музыки, согласно близким к эпохе источникам скончался в 1711 г. Своими произведениями, такими как Segâh tekbiri и rast na'tı, он оставил шедевры мечетной и тарикатской музыки.", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["Выдвижение Недима как предтечи поэзии эпохи тюльпанов", "d3c40dbb"], "d": ["На протяжении эпохи тюльпанов 1718–1730 гг. Недим выработал новый поэтический стиль, выделявшийся совершенством выражения, стремлением к простоте и остроумной манерой. Этот стиль, развивавшийся в окружении Невшехирли Дамада Ибрагим-паши, считается крупнейшим представителем течения опоры на местное в диванной поэзии.", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["Левни иллюстрирует Surnâme-i Vehbî", "8c127866"], "d": ["Придворный художник Левни проиллюстрировал 137 миниатюрами Surnâme-i Vehbî, рассказывающую о празднествах по случаю обрезания шехзаде Ахмеда III в 1720 г. В отличие от прежних образцов он не ограничил торжества одним Atmeydanı, а изобразил их в разных уголках города, положив тем самым начало новому пониманию в османском искусстве миниатюры.", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["Официальное закрепление системы гедик как цехового порядка, основанного на монополии", "cd0f79a7"], "d": ["По TDV, систематическое преобразование, в ходе которого право гедик приобрело значение «монополии, привилегии и своего рода патента», прослеживается с 1727 г.; этот порядок, дающий право на работу определённому числу лиц в ремесле, закрепился главным образом в лавках вакфного имущества под названием «право гедик».", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["Разрушение Садабада во время восстания Патроны Халила", "8a30f9a0"], "d": ["Во время восстания Патроны Халила, вспыхнувшего 25 сентября 1730 г., были разрушены сотни павильонов и построек в Садабаде; этот комплекс, символ эпохи тюльпанов, больше не обрёл прежнего великолепия.", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["Смерть Недима во время восстания Патроны Халила", "06bf909e"], "d": ["Недим, бывший мударрисом в медресе Секбан Али-паши, когда вспыхнуло восстание Патроны Халила, умер в последующие за восстанием дни. День смерти неизвестен; но поскольку kassam hüccet о его наследстве составлен 15 рабиуль-ахира 1143 г. х. (28 октября 1730 г.), он умер раньше этой даты. О причине смерти существуют различные предания: часть источников пишет, что он умер от «болезни страха» (illet-i vehîme) или от дрожательной болезни, вызванной вином и опиумом, а Мюстакимзаде — что во время мятежа он от страха взобрался на крышу своего дома и, упав с неё, погиб. С его смертью фактически закончился и культурный блеск эпохи тюльпанов.", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["Кончина Левни", "dd48b56e"], "d": ["Левни, считающийся последним великим представителем османского искусства миниатюры, скончался в 1732 г. Большая часть его работ находится ныне в музее дворца Топкапы.", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["Закладка фундамента мечети и комплекса Nuruosmaniye", "397ec798"], "d": ["Фундамент комплекса Nuruosmaniye был заложен Махмудом I 19 января 1749 г. Это здание считается первым крупным применением европейского барочного стиля в османской архитектуре и заметно отходит от классической схемы комплекса.", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["Открытие мечети и комплекса Nuruosmaniye", "15d83731"], "d": ["Открытие комплекса, начатого Махмудом I, но не дожившего до его завершения, состоялось 5 декабря 1755 г. при его брате Османе III. Мечеть получила своё название — «Свет Османа» — в честь Османа III, осуществившего открытие.", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["Открытие Mühendishâne-i Bahrî-i Hümâyun", "a2fab1cd"], "d": ["Mühendishâne-i Bahrî-i Hümâyun (Императорская военно-морская инженерная школа), первая современная морская инженерная школа Османской империи, согласно французским архивным документам была открыта 29 апреля 1775 г. при Абдулхамиде I, в бытность великим визирем Дервиш Мехмед-паши.", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["Введение системы эсхам", "eabd8ece"], "d": ["В 1775 г. в условиях бремени контрибуции в 7,5 млн курушей, наложенной Кючук-Кайнарджийским миром, была введена система эсхам. В этом методе, задуманном как способ выйти за пределы маликяне, доход от мукатаа делился на доли, и в отличие от маликяне пайщиками могли становиться также женщины, немусульмане и простой народ.", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["Рождение Хаммамизаде Исмаила Деде-эфенди", "c033f039"], "d": ["Хаммамизаде Исмаил Деде-эфенди, один из самых плодовитых композиторов турецкой музыки, родился 9 января 1778 г. в стамбульском квартале Шехзадебаши. За свою жизнь он сочинил более 500 произведений; около 294 из них дошли до наших дней.", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["Начало строительства Mühendishâne-i Berrî-i Hümâyun", "4f5d521a"], "d": ["Строительство Mühendishâne-i Berrî-i Hümâyun (Императорская сухопутная инженерная школа), одного из важнейших учреждений реформ Nizâm-ı Cedîd («Нового порядка») Селима III, началось 14 июля 1793 г. Здание было завершено в сентябре 1795 г. и открыто для обучения; учреждение было второй военно-инженерной школой Османской империи, образцом для которой служили военные академии Европы.", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["Начало отмены Селимом III монополии некоторых ремесленных цехов", "008f4a7d"], "d": ["По статье TDV об эснафе, в османской цеховой системе, с момента возникновения переплетённой с организацией ахи, должностные лица вроде «ахи-бабы» и «шейха» руководили цехами до начала XIX в.; когда в XVIII в. монополия цехов подняла цены выше нарха и создала экономическое давление, Селим III с 1794 г. начал отменять монополию цехов, торгующих основными продуктами питания.", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["Принятие Деде-эфенди ко двору в качестве musâhib-i şehriyârî", "0cb99ac3"], "d": ["Деде-эфенди, обративший на себя внимание падишаха при Селиме III сочинением в макаме bûselik, в 1812 г. был Махмудом II включён в число «musâhib-i şehriyârî» (ближайших собеседников падишаха), а вскоре возвысился до должности старшего муэдзина.", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["Первая регулярная перепись населения в Османской империи", "4f004c6c"], "d": ["Махмуд II с целью определить население, подлежащее призыву, впервые провёл регулярную перепись в конце 1830 г.; были записаны только мужчины, и в Анатолии и Румелии было зарегистрировано около 7,5 млн человек. В некоторых областях, например в Эрзуруме и Ване, перепись удалось завершить лишь в 1836 г.", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["Основание Feshâne-i Âmire", "971ab85a"], "d": ["Для удовлетворения потребности в фесках войска Asâkir-i Mansûre-i Muhammediyye (Победоносное войско Мухаммеда), созданного после упразднения корпуса янычар в 1826 г., в 1833 г. на Cündî Meydanı в Kadırga с капиталом в 1,5 млн курушей началось производство фесок. В 1839 г. предприятие было перенесено во дворец Хатидже-султан в Эюпе; Feshâne заложила основу османской текстильной промышленности.", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["Медицинская школа получает название Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne", "187d60f3"], "d": ["Медицинская школа, переведённая в здание Enderun Ağaları Mektebi в Галатасарае, 14 мая 1839 г. после посещения Махмуда II получила название «Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne» (Императорская медицинская школа); тем самым учреждение было официально закреплено как военно-административная школа.", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["Кончина Деде-эфенди в Мине во время хаджа", "c3e613a2"], "d": ["Хаммамизаде Исмаил Деде-эфенди, заболевший холерой в Мине, куда он отправился исполнить обязанность хаджа, скончался 29 ноября 1846 г. Со смертью художника, сочинившего в 1824–1839 гг. семь отдельных мевлевийских аинов, закончилась эпоха классической османской музыки.", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["Принятие Торгового кодекса 1850 г. (Ticaret Kanunnâmesi)", "8ac085fd"], "d": ["В рамках правовых реформ эпохи Танзимата новые законы заимствовались у западных государств путём перевода и адаптации: уголовный кодекс вступил в силу в 1840 г., торговый кодекс — в 1850 г., земельный кодекс — в 1857 г. Ticaret Kanunnâmesi был первой современной кодификацией османского торгового права.", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["Начало большой волны переселения крымских татар и кавказских народов в османские земли", "8832c06d"], "d": ["После того как шейх Шамиль в 1859 г. попал в плен к русским, вместе с крымскими татарами с Кавказа в османские земли начали переселяться многочисленные черкесские и ногайские мухаджиры. Эта волна переселения с разной интенсивностью продолжалась вплоть до Русско-турецкой войны 1877–1878 гг.", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["Учреждение Комиссии по делам мухаджиров", "9717e77e"], "d": ["Для управления нарастающей волной переселенцев с Кавказа османское правительство 16 января 1860 г. учредило Комиссию по делам мухаджиров (Muhâcirîn Komisyonu). Комиссия координировала работу по расселению в Анатолии, на Балканах и в Сирии и действовала до 1875 г.", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["Реорганизация Bank-ı Osmanî в Bank-ı Osmanî-i Şâhâne (Османский банк)", "c3530456"], "d": ["В 1856 г., после Крымской войны, для управления выплатами по внешнему долгу был основан Bank-ı Osmanî с центром в Лондоне и английским капиталом. В 1863 г. франко-английской группе было дано разрешение на создание нового банка под названием Bank-ı Osmanî-i Şâhâne (Османский банк); позднее учреждение получило и право выпуска банкнот.", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["Основание Cem'iyyet-i Tedrîsiyye-i İslâmiyye", "77ad553a"], "d": ["30 марта 1864 г. было основано Cem'iyyet-i Tedrîsiyye-i İslâmiyye (Общество мусульманского образования) с целью обучения бедных мусульманских подмастерьев; эта инициатива гражданского общества — пионерский пример превращения традиции благотворительных учреждений в проект современной школы. Через девять лет общество откроет Darüşşafaka.", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["Упорядочение системы мухтаров и советов старейшин Положением о вилайетах 1864 г.", "1a2e8cf2"], "d": ["Положением о вилайетах 1864 г. (Vilâyet Nizamnâmesi) было вновь упорядочено сельское управление; в деревнях, где совместно жили мусульмане и немусульмане, было признано, что каждая община избирает своего мухтара и свой совет старейшин. Совет старейшин тем самым впервые обрёл официальное место в управлении деревней и кварталом.", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["Кульминация Великого черкесского изгнания", "b2ab1874"], "d": ["В результате занятия Россией Кавказа в 1858–1878 гг., наиболее интенсивного в 1861–1864 гг., от 1,2 до 1,5 млн черкесов были принудительно переселены в османские земли. По TDV, многие исследователи характеризуют это событие как «первую акцию этнической чистки в новейшей истории».", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["Издание Положения о всеобщем образовании 1869 г. (Maârif-i Umûmiyye Nizamnâmesi)", "787f6022"], "d": ["Maârif-i Umûmiyye Nizamnâmesi, изданное 1 сентября 1869 г., стало первым всеобъемлющим текстом, регулирующим всеобщее образование в провинции и в центре. Этим положением был учреждён Meclis-i Kebîr-i Maârif; тем самым началась перестройка начальных школ (сыбьян) так, чтобы они перестали быть лишь этапом религиозного обучения и были направлены на обучение чтению и письму.", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["Начало обучения в школе Darüşşafaka", "525c457c"], "d": ["Darüşşafaka, основанная Cem'iyyet-i Tedrîsiyye-i İslâmiyye, 28 июня 1873 г. фактически начала обучение с целью бесплатного обучения сирот и бедных мусульманских детей с проживанием; предельный возраст приёма был установлен в десять лет.", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["Стамбульское землетрясение 1894 г.", "7ae7f648"], "d": ["Землетрясение, произошедшее 10 июля 1894 г. в море близ Измитского залива, тяжело ударило по Стамбулу; многие мечети и исторические здания, включая стамбульские стены, получили повреждения. Статья TDV о землетрясении относит это землетрясение вместе с землетрясениями 1509, 1719 и 1766 гг. к тем, что привели в районе Мраморного моря к большим людским и материальным потерям.", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["Открытие Dârülaceze", "a30baf31"], "d": ["Dârülaceze, подготовленный по приказам Абдулхамида II начиная с 1890 г., был открыт 2 февраля 1896 г. великим визирем Халиль Рифат-пашой. Учреждение, приютившее беспризорных детей, стариков и нуждающихся, было крупнейшим комплексом социальной помощи своего времени — с больницей на 200 коек, мастерскими и отдельными молельнями: мечетью, церковью и синагогой.", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["Окончательное учреждение Dârülfünûn-ı Şâhâne как постоянного заведения", "7d6d8fc4"], "d": ["После двух неудачных попыток (1863 и 1870 гг.) Darülfünun был вновь основан 31 августа 1900 г. как постоянное заведение под названием Dârülfünûn-ı Şâhâne (Императорский университет); TDV характеризует эту дату как непосредственную основу современной турецкой университетской системы.", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["Сарбадары взяли Сабзевар — первое послеильханское государство в Хорасане", "af997fec"], "d": ["Когда с кончиной Абу Саида (30 ноября 1335 г.) рухнула центральная власть Ильханов, накопившееся в Хорасане недовольство сборщиками налогов взорвалось в Баштине: Абд ар-Раззак поднял восстание 13 марта 1337 г. и 9 сентября 1337 г. (12 сафара 738 г. х.) овладел Сабзеваром. Название «Сарбадар» — «голова на виселице» — слова самих сарбадаров, означающие, что в случае поражения они готовы были быть повешенными.", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["Мараши-сейиды взяли Амоль — власть сейидов в Мазендеране", "c0e03266"], "d": ["Сейид Кавам ад-Дин Мараши, пойдя путём, проложенным сарбадарами в Хорасане, в 760 г. х. (1359 г.) овладел Амолем и создал сейидское государство на южном берегу Каспия. Династия распространилась на Сари, Барфуруш и их окрестности; она была потрясена походами Тимура и распущена при сефевидском Шахе Аббасе I.", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["Основание династии Каркия в Гиляне — последние независимые правители каспийского берега", "6e5f9db7"], "d": ["Али Кия вернулся в Гилян вместе со своей семьёй и в 773 г. х. (1371–72 гг.) основал власть Каркия с центром в Лахиджане; династия более двухсот лет удерживала юго-западный берег Каспия и просуществовала до присоединения области сефевидским Шахом Аббасом I в 1592 г.", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["Переход власти даджу в Дарфуре к тунджурам", "6eb22a2a"], "d": ["Согласно статье TDV İslâm Ansiklopedisi о Дарфуре, первыми поселились в этом районе и создали первое государство даджу; господствовавшие здесь на протяжении XIII и XIV вв. даджу уступили торговое господство тунджурам, а в XV в. положение, особенно в центральной области, полностью изменилось в пользу тунджуров.", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["Возвращение Испанией скалы Бадис (Пеньон-де-Велес)", "0dc52728"], "d": ["Статья TDV о Саадидах отмечает, что захват испанцами Бадиса стал тяжёлым ударом для мореплавания Магриба (1564). Этот скальный пункт на северном берегу Марокко служил опорой для пиратства в западной части Средиземного моря и османско-испанского соперничества.", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["Уступка Лараша Испании", "7b8f6e27"], "d": ["В годы гражданской войны, в ходе которой распалась династия Саадидов, атлантический порт Лараш был передан Испании. Статья TDV о Саадидах отмечает, что в это время страна была разделена на эмираты Марракеш (южный) и Фес (северный), а стороны в борьбе за престол искали помощь извне. Порт простоял в испанских руках почти восемьдесят лет, и Мулай Исмаил отвоюет его в 1689 г.", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["Переход Мамуры (Мехдии) в руки испанцев", "c8fd494e"], "d": ["Порт Мамура (Мамура / Мехдия) в устье реки Себу был взят испанцами в 1614 г. и укреплён под названием San Miguel de Ultramar. Статья TDV о Мулае Исмаиле отмечает, что порт был отвоёван у испанцев внезапным нападением в 1092 г. х. (1681 г.), то есть испанское господство продлилось шестьдесят семь лет.", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["Конец династии Саадидов — начало алауитской (филалийской) эпохи в Марокко", "b1afa579"], "d": ["TDV İslâm Ansiklopedisi определяет Саадидов как «исламскую династию, правившую в Марокко (1511–1659)». Династия, в 1549 г. положившая конец власти Ваттасидов и объединившая всё Марокко, в 1578 г. уничтожившая у Вади-ас-Сейль португальское войско и ни в один период не подчинявшаяся османам, после долгих распрей за престол прекратилась в 1659 г. Её место заняли алауитские (филалийские) шерифы из Тафилальта; Мулай Рашид в 1666 г. вошёл в город Фес и упрочил новую династию, а его брат Мулай Исмаил очистил европейские пункты на атлантическом побережье.", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["Занятие Испанией островов Альусемас", "954ca998"], "d": ["Острова Альусемас (аль-Хусайма) на средиземноморском берегу были заняты испанским флотом в 1673 г. Вместе с Бадисом и Сеутой это один из пунктов, которые Испания удерживала на северном берегу Марокко и которые остались в её руках по сей день. В том же году Мулай Рашид, старший брат Мулая Исмаила, вошёл в Марракеш и принял присягу населения, и власть Филали укрепилась на юге; эта потеря на побережье показывает, что внутреннее объединение ещё не имело соответствия на внешнем фронте.", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["Отвоевание Мулаем Исмаилом Лараша у испанцев", "a54bc6ee"], "d": ["Статья TDV о Мулае Исмаиле ясна: «В 1100 г. х. (1689 г.) они отвоевали Лараш у испанцев, захватив 200 орудий, а два года спустя вернули и Асилу». Это одно из звеньев цепи очищения побережья султаном из Филали: Танжер был отвоёван у англичан в 1678 г., Мамура — в 1681 г., Лараш — в 1689 г., Асила — в 1691 г. Порт, оставленный восемьдесят лет назад в саадидской гражданской войне, таким образом вернулся в Марокко.", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["Основание Дарфурского султаната — династия Кейра и Сулейман Солонг", "0fc1c112"], "d": ["По TDV, основание Дарфурского султаната приходится на время после смуты, последовавшей за вторжением Бому эль-Касира в конце XVII в. Фуры под руководством династии Кира (Кейра) во главе с Сулейманом Солонгом отняли власть у даджу и тунджуров и установили прочное управление. Сулейман Солонг правил в 1695–1715 гг. Дарфурские султаны в последующие века вели переписку с Высокой Портой; Абдулмеджид и Абдулазиз утверждали их правление.", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["Провозглашение Первой республики во Франции — конец королевства", "d53d49b0"], "d": ["На первом заседании Национального конвента королевство было упразднено, а на следующий день провозглашена Первая республика; от этого дня был начат отсчёт первого года нового календаря. Для Османской империи собеседник не изменился, но изменился род собеседника: в годы Nizâm-ı Cedîd Селима III Франция была уже не династией, а режимом, и именно армия этого режима высадится в Египте в 1798 г.", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["Падение Великой Кабилии — пленение Лаллы Фатмы Н'Сумер", "0f61ff08"], "d": ["Статья TDV об Алжире отмечает, что с занятием горной Кабилии (Билад аль-кабаиль) по итогам походов 1853, 1854 и 1857 гг. завоевание Алжира Францией в основном завершилось. Поход 1857 г. сломил линию Тизи-Узу и Акбу; символ сопротивления Лалла Фатма Н'Сумер попала в плен. Так угас последний крупный очаг сопротивления, уцелевший после капитуляции эмира Абд аль-Кадира в 1847 г.", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["Занятие французами Ин-Салаха (Тидикельт)", "1e28d1d0"], "d": ["Ин-Салах, центр группы оазисов Тидикельт посреди Сахары, был взят французскими силами 29 декабря 1899 г. Это первый крупный шаг французской экспансии, спускавшейся на юг от алжирского побережья, на территорию пустыни; в течение двух лет Туат и Гурара пойдут по тому же пути.", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["Присоединение оазисов Туат, Гурара и Тидикельт к Франции", "d412838b"], "d": ["Пояс оазисов Туат, Гурара и Тидикельт на юго-западе Алжира был 21 февраля 1901 г. официально присоединён к Франции. Этот узел караванных путей, на который номинально претендовал марокканский султан, — включая Адрар, Тиммимун, Реггане и Бени-Аббес — таким образом вошёл в состав Алжира; отсюда начинается пограничный спор между Марокко и французским Алжиром.", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["Основание французского поста в Бешаре (Коломб-Бешар)", "4d44d252"], "d": ["Оазис Бешар на границе с Марокко был занят французскими силами 11 ноября 1903 г. и превращён в передовой пост под названием Colomb-Béchar. Этот шаг, последовавший через два года после присоединения пояса Туата, — одно из заключительных звеньев продвижения Франции из Алжира в сторону Марокко; он открывает путь к установлению протектората над Марокко в 1912 г.", "bd1a7ae2"]},
"OLAYLAR_EK16:1283-01-01:0":{"b": ["Основание Московского княжества — Даниил I", "49549309"], "d": ["Даниил, младший сын Александра Невского, стал править Москвой как самостоятельным княжеством. В то время Москва была небольшим и малозначительным центром Владимиро-Суздальской земли; русская историография считает эту дату отправной точкой последующего возвышения.", "10cf92d1"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["Основание бейликов Каресидов и Хамидидов", "3905da93"], "d": ["Согласно статье TDV о Каресидах, Караси-бей, объявив независимость в распадавшейся после смерти отца Калем-бея сельджукской пограничной организации, с 696 г. х. (1296–97 гг.) сделал своим центром Балыкесир и вскоре отнял у Византии всю Мисию, включая Эрдек, Бигу, Эдремит и Бергаму. В тот же год (1297) Хамид-бей, сделав Улуборлу центром правления, основал бейлик Хамидидов; Испарта, Бурдур, Эгирдир и Ялвач из распавшейся сельджукской пограничной области вошли в первые границы бейлика. Оба бейлика — порождение одного и того же краха в Западной Анатолии — распада сельджукской центральной власти.", "7d297343"]},
"OLAYLAR_EK16:1301-01-01:0":{"b": ["Московский князь Даниил присоединил Коломну и Серпухов к Москве", "6d82dccd"], "d": ["Даниил отнял у Рязанского княжества Коломну (пленённый рязанский князь передал крепость ради освобождения) и Серпухов; Москва вышла к реке Оке, и это было первое территориальное расширение Московского княжества.", "f6b7a96c"]},
"OLAYLAR_EK16:1304-01-01:0":{"b": ["Можайск отнят у Смоленского княжества и присоединён к Москве", "462055a0"], "d": ["Московское княжество, отняв у Смоленска Можайск в верхнем бассейне Москвы-реки, приблизило свою западную границу к Литве.", "3002aa5d"]},
"OLAYLAR_EK16:1307-01-01:0":{"b": ["Полоцкое княжество перешло к Великому княжеству Литовскому", "04a26a6f"], "d": ["Полоцк, Витебск и их окрестности до 1307 г. оставались в составе русской княжеской династии; расширение Литвы на восток до Гедимина обозначилось этим переходом (дата справки о государстве в атласе — 1307 г.; фактический переход Витебска ≈1320 г. спорен).", "52bf8042"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["Основание бейлика Айдыниды — взятие Измира, Аясулука и Тире", "69a021ae"], "d": ["Согласно статье TDV об Айдынидах, Мубаризеддин Гази Мехмед-бей, отняв эту область у Гермиянидов — пограничного бея Сасы-бея, в 1308 г. утвердился в Айдын-или; он завоевал мусульманскую часть Измира вместе с Аясулуком (Сельчук), Тире и Бодемией. Он сделал Аясулук военно-морской базой и разделил завоёванные земли между пятью сыновьями — в последующие десятилетия бейлик, особенно при его сыне Умур-бее, станет решающей силой в мореплавании на Эгейском море.", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["Фактический конец Анатолийского Сельджукского государства — прямое управление Ильханов", "00f85ecb"], "d": ["По статье TDV о Мас'уде II, Гийас ад-Дин Мас'уд II, скончавшийся после долгой болезни в 708 г. х. (1308 г.) в Кайсери, по общепринятому мнению — последний правитель Анатолийского Сельджукского государства: кандидаты, возведённые на престол после его смерти, не получили признания ни внутренних властей, ни Ильханов. Область и без того на протяжении всего правления Мас'уда фактически управлялась ильханскими чиновниками; с его смертью это прямое управление лишилось и формального прикрытия в таких центрах, как Конья, Нигде и Аксарай.", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["Распространение бейлика Джандаридов на Кастамону, Чанкыры, Бартын и Сафранболу", "64e39ad0"], "d": ["Согласно статье TDV о Джандаридах, бейлик был основан в начале XIV в. в окрестностях Кастамону и Синопа Шемседдином Яман Джандаром, которому ильханский правитель Гейхату пожаловал в икта Эфлани и его окрестности; из-за скудости источников точная дата основания неизвестна. Преемник Джандара Сулейман-бей упоминается как правитель, занявший место бейлика Чобанидов, — то есть окрестности Кастамону и Чанкыры перешли к Джандаридам от Чобанидов, а линия Бартын — Сафранболу — Эфлани — от прямого ильханского управления.", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["Завоевание Родоса и Додеканеса рыцарями Св. Иоанна (госпитальерами)", "67885b4b"], "d": ["Статья TDV о Родосе отмечает, что остров перешёл в руки рыцарей Св. Иоанна (госпитальеров, İsbitâriyye) в 1309 г.; стандартная история госпитальеров (см. J. Riley-Smith, The Knights Hospitaller) уточняет, что осада началась летом 1306 г., а город Родос, долго сопротивлявшийся с византийскими подкреплениями, пал лишь 15 августа 1310 г. от сил великого магистра Фулька де Виллара. Остров с этой даты вплоть до османского завоевания 1522 г. станет центром рыцарей, а окружающий его Додеканес в том же процессе перешёл от Византии к власти госпитальеров.", "c1422e2c"]},
"OLAYLAR_EK16:1313-01-01:0":{"b": ["Ливонские рыцари вернули у Литвы крепость Динабург", "92119516"], "d": ["Литовцы около 1281 г. взяли Ерсику и обменяли её на крепость Ордена Динабург. Крепость в 1313 г. вновь перешла в руки ливонских рыцарей и оставалась центром комтурства Ордена.", "0cdd86e0"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["Взятие Коса рыцарями Сен-Жан", "445666f7"], "d": ["Согласно статье TDV об Истанкёе, рыцари Сен-Жан, обосновавшись на Родосе, взяли и Кос (1315) и построили новые крепости. Остров таким образом перешёл под власть рыцарей, продлившуюся до 1523 г.; под чьим управлением находился Кос после падения города Родос в 1310 г., в TDV не уточняется.", "145d1bad"]},
"OLAYLAR_EK16:1325-01-01:0":{"b": ["Митрополичья кафедра перенесена в Москву", "d20099f8"], "d": ["Митрополит Пётр, глава Русской православной церкви, перенёс свой религиозный центр в Москву. Это было началом возвышения Москвы не только как политического, но и как религиозного центра и укрепило легитимность княжества.", "4e31c42f"]},
"OLAYLAR_EK16:1330-01-01:0":{"b": ["Ливонский орден стал сюзереном города Риги", "21453047"], "d": ["Рижское архиепископство и город, воевавшие против Ордена при поддержке литовских великих князей Витеня и Гедимина, потерпели поражение в 1330 г.; Ливонский орден стал сюзереном города. По Саласпилсскому договору 1452 г. Рига перешла под совместный сюзеренитет Ордена и архиепископа.", "28788282"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["Основание бейлика Эретна — центральная Анатолия после Ильханов", "a67bacd9"], "d": ["Согласно статье TDV об Эретнидах, Алаэддин Эретна, ильханский чиновник уйгурского происхождения, после смерти ильханского правителя Абу Саида Бахадур-хана в 1335 г. превратил ильханское наместничество в Анатолии в фактически независимое правление; сначала он выступал в качестве наиба мамлюкского султана, в 1340 г. убрал из хутбы имя мамлюка и около 1341 г. объявил полную независимость. Бейлик с центром сначала в Сивасе, затем в Кайсери вплоть до его смерти (1352 г.) создал обширную власть над центральной Анатолией, охватывавшую Амасью, Токат, Чорум, Нигде, Аксарай и Эрзинджан, и в 1381 г. был уничтожен кади Бурханеддином.", "04978a80"]},
"OLAYLAR_EK16:1335-05-01:0":{"b": ["Захват Габсбургами Крайны и Каринтии (Любляна)", "039918d3"], "d": ["После того как 2 апреля 1335 г. в замке Тироль без наследника умер герцог Каринтии и граф Тироля Генрих VI, братья Габсбурги Альбрехт II и Отто IV в соответствии с тайным соглашением, заключённым 23 ноября 1330 г. с Людвигом Баварским, получили императорской грамотой герцогство Каринтию и подчинённую ему Крайну (область, в которой находится нынешняя Любляна); Тироль же через дочь Генриха остался отдельно. Это был один из первых крупных шагов расширения Габсбургов в Альпийском регионе, и Крайна (с перерывами) оставалась в руках Габсбургов/Австрии до 1918 г.", "4dbed85a"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["Основание государства Джалаиридов — Азербайджан после Ильханов", "a13ada90"], "d": ["Согласно статье TDV о Джалаиридах, Хасан Бузург, внук ильханского эмира Нойана, воспользовавшись борьбой за престол, разразившейся со смертью ильханского правителя Абу Саида Бахадур-хана, в 1340 г. основал независимое государство с центром в Тебризе. Джалаириды таким образом стали первой крупной династией, заполнившей вакуум после Ильханов в Азербайджане и его окрестностях; при его преемнике Увайсе (1356–1374) их земли расширятся до Мосула и Диярбакыра.", "224cbb81"]},
"OLAYLAR_EK16:1341-01-01:0":{"b": ["Основано Суздальско-Нижегородское великое княжество — хан даровал ярлык Константину Васильевичу", "c69f5198"], "d": ["Хан Золотой Орды Узбек (в справке о государстве — Узбек/Джанибек) передал суздальскому князю Константину Васильевичу Нижегородско-Городецкое княжество; княжество стало соперником Москвы и в 1392 г. было присоединено к Москве Василием I.", "4b281b04"]},
"OLAYLAR_EK16:1346-01-01:0":{"b": ["Дания продала Северную Эстонию (Ревель и Нарву) Ливонскому ордену", "6861ba55"], "d": ["Датское королевство продало Ливонскому ордену свои земли в Северной Эстонии вместе с Ревелем и Нарвой. Область оставалась в руках Ордена вплоть до Ливонской войны.", "0723514c"]},
"OLAYLAR_EK16:1348-01-01:0":{"b": ["Болотовский договор — Новгород признал независимость Пскова", "08eca44d"], "d": ["Новгород признал Псков «младшим братом»; Псков жил как независимая городская республика со своим вече и посадником, пока в 1510 г. не был присоединён к Москве.", "12f9ce2f"]},
"OLAYLAR_EK16:1392-01-01:0":{"b": ["Василий I присоединил Суздальско-Нижегородское княжество к Москве", "5ecf441b"], "d": ["По ярлыку, полученному от хана Тохтамыша, Василий I подчинил Москве Нижний Новгород, Городец и Суздаль; началось продвижение Москвы к бассейну Волги и Оки.", "ac83ac55"]},
"OLAYLAR_EK16:1404-01-01:0":{"b": ["Витовт взял Смоленск — Смоленское княжество присоединено к Литве", "1a68300c"], "d": ["Витовт овладел Смоленском; город оставался в Великом княжестве Литовском, пока в 1514 г. не перешёл к Москве.", "3ed5ce14"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["Переход Багдада к Кара-Коюнлу — поражение джалаиридского султана Ахмада", "a42ebe92"], "d": ["Согласно статье TDV о Кара-Коюнлу, Кара Юсуф 28 раби аль-ахира 813 г. х. (30 августа 1410 г.) нанёс тяжёлое поражение джалаиридскому султану Ахмаду близ Тебриза; после смерти султана Ахмада в 814 г. х. (1411 г.) он провозгласил султаном в Тебризе его сына Пир Будака, и в том же году его старший сын Шах Мехмед завоевал Багдад. Так Багдад, почти столетие бывший столицей Джалаиридов, вместе с линией Басра — Мосул — Киркук перешёл под власть Кара-Коюнлу.", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["Эрзинджан и Кемах перешли к Ак-Коюнлу — Кара Юлюк Осман-бей", "122460d4"], "d": ["После смерти Кара Юсуфа по желанию жителей Эрзинджана правителем города стал Яр Али, внук Мутахартена. При нём бей Ак-Коюнлу Кара Юлюк Осман взял Эрзинджан и присоединил его к землям Ак-Коюнлу. С этого времени Эрзинджан стал местом, переходившим из рук в руки то между Ак-Коюнлу и Кара-Коюнлу, то между принцами Ак-Коюнлу.", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["Основание Казанского ханства — Улу-Мухаммед-хан покидает Золотую Орду", "335a7408"], "d": ["Согласно статье TDV о Казанском ханстве, Улу-Мухаммед-хан, потерявший трон в столице Золотой Орды Сарае, сначала отошёл в Белёв со своей семьёй и примерно 3000 воинов, в 1437–1438 гг. боролся с русским князем Василием II, затем обосновался в городе Казани; при поддержке местного населения он заложил здесь основы нового ханства. TDV отмечает, что процесс образования завершился в 1437–1445 гг. и что с 1445 г. ханство получило полностью независимый статус — карта принимает за основу начало этого процесса, 1438 г., когда Улу-Мухаммед обосновался в Казани.", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["Основание Крымского ханства — Хаджи Герай обретает независимость от Золотой Орды", "5728223e"], "d": ["Согласно статье TDV о Крыме, Крымское ханство возникло как порождение раздробления Золотой Орды борьбой за престол во второй половине XIV в.; самая ранняя монета, отчеканенная истинным основателем ханства Хаджи Гераем, несёт дату 845 г. х. (1441–42 гг.), и эта дата считается официальной датой основания ханства. В том же году Хаджи Герай упрочил своё положение в Крыму, установив дружбу с Москвой, и на его сторону встали местные беевские семьи, прежде всего племя ширин.", "dbd052d0"]},
"OLAYLAR_EK16:1450-01-01:0":{"b": ["Джахан-шах взял Эрзинджан — власть Кара-Коюнлу", "0c928cc4"], "d": ["Правитель Кара-Коюнлу Джахан-шах в 854 г. х. (1450 г.) отправил армию на Эрзинджан и отнял город у Ак-Коюнлу. Эта потеря привела к разладу между беем Ак-Коюнлу Джахангиром Мирзой и его братом Хасан-беем (Узун-Хасаном).", "203c5c2e"]},
"OLAYLAR_EK16:1452-01-01:0":{"b": ["Захват Кара-Коюнлу Джахан-шахом тимуридского Ирана (Рей, Исфахан, Фарс, Кирман)", "c6fbb3f5"], "d": ["Согласно статье TDV о Кара-Коюнлу, правитель Кара-Коюнлу Джахан-шах, воспользовавшись борьбой за престол между тимуридскими принцами, в 856–857 гг. х. (1452–1453 гг.) взял под своё управление вилайеты Рей, Исфахан, Фарс и Кирман; это кульминация процесса расширения, начавшегося после смерти Шахруха Мирзы в 1447 г. и открытого присоединением Султании и Казвина. Земли Тимуридов в юго-центральном Иране таким образом перешли к Кара-Коюнлу; власть Джахан-шаха в 1466 г. достигнет размаха, охватывающего Азербайджан, Арран, Ирак-и Аджем, Ирак-и Араб, Фарс, Кирман и Восточную Анатолию.", "3f6a6c37"]},
"OLAYLAR_EK16:1452-10-23:0":{"b": ["Возвращение Бордо англичанам — последний гасконский поход Джона Талбота", "01b2b7be"], "d": ["Бордо, потерянный в 1451 г. в пользу французов, в ночь с 22 на 23 октября 1452 г. сдался английскому войску под командованием престарелого военачальника Джона Талбота, после того как жители восстали против французского гарнизона и открыли ворота; это была последняя и недолговечная победа Англии в Гаскони в Столетней войне. Через год, после битвы при Кастийоне, Бордо окончательно вернётся к Франции.", "f6945d27"]},
"OLAYLAR_EK16:1453-10-19:0":{"b": ["Окончательное возвращение Бордо Франции — фактический конец Столетней войны", "b0a86f6c"], "d": ["Со смертью Джона Талбота и уничтожением его армии в битве при Кастийоне 17 июля 1453 г. английское сопротивление в Гаскони рухнуло; осаждённое Бордо 19 октября 1453 г. сдалось французским силам. Эта сдача считается моментом фактического окончания Столетней войны, длившейся 116 лет (официальный мирный договор так и не был подписан), и она сузила владычество Англии на континентальной Европе до Кале.", "1c632d46"]},
"OLAYLAR_EK16:1457-01-01:0":{"b": ["Узун-Хасан вернул Эрзинджан — снова Ак-Коюнлу", "550d010a"], "d": ["Узун-Хасан, победив Кара-Коюнлу, вновь взял Эрзинджан под власть Ак-Коюнлу. Город оставался в границах Ак-Коюнлу и после битвы при Отлукбели в 1473 г.", "d778fa85"]},
"OLAYLAR_EK16:1466-10-19:0":{"b": ["Второй Торуньский мир — Данциг (Гданьск) и Западная Пруссия переданы Польше", "e2152dae"], "d": ["Второй Торуньский (Toruń) мир, положивший конец Тринадцатилетней войне, начавшейся восстанием Прусской конфедерации в 1454 г. против власти Тевтонского ордена, был подписан 19 октября 1466 г.; Орден уступил Польскому королевству Восточную Померанию с Данцигом (Гданьском), устье Вислы с Эльбингом (Эльблонгом) и область Кульм — эти земли получили название «Королевская Пруссия». Восточная же Пруссия оставалась у Ордена до 1525 г.", "831685a9"]},
"OLAYLAR_EK16:1474-01-01:0":{"b": ["Иван III купил оставшуюся половину Ростовского княжества", "5203244f"], "d": ["Половина, остававшаяся в руках ростовских князей, была передана Москве; вместе с другой половиной, перешедшей к Москве в 1332 г., Ростовская земля полностью была подчинена Москве.", "ab0eeae6"]},
"OLAYLAR_EK16:1485-09-12:0":{"b": ["Тверское великое княжество присоединено к Москве — Иван III взял город", "fa3f924e"], "d": ["Под осадой московской армии последний великий князь тверской Михаил Борисович бежал в Литву, Тверь сдалась Ивану III; сильнейший соперник Москвы таким образом исчез.", "b9942526"]},
"OLAYLAR_EK16:1489-02-26:0":{"b": ["Королева Катерина Корнаро уступила Кипр Венеции — конец крестоносного государства", "e24d3f3a"], "d": ["Венецианка Катерина Корнаро, после смерти мужа короля Жака II в 1473 г. управлявшая Кипром в качестве королевы-регентши, ввиду отсутствия наследника под давлением венецианского правительства 26 февраля 1489 г. отреклась от престола и передала свои королевские права на острове дожу и Венецианской республике; взамен она сохранила титул королевы и получила графство Азоло на Terraferma. Этой передачей закончились власть династии Лузиньянов, длившаяся с 1192 г., и последнее крестоносное государство; остров оставался под венецианским управлением вплоть до османского завоевания 1570–71 гг.", "7f769951"]},
"OLAYLAR_EK16:1492-01-02:0":{"b": ["Падение Гранады — конец последнего мусульманского государства на Пиренейском полуострове", "46e5201b"], "d": ["Последний правитель эмирата Насридов Гранады, ослабленного десятилетней поэтапной осадой и внутренними распрями, Абу Абдаллах (Боабдиль) 2 января 1492 г. передал ключи от города Католическим королям Фердинанду и Изабелле в соответствии с щедрыми условиями капитуляции (Гранадские капитуляции), подписанными в ноябре 1491 г.; после ухода Боабдиля из Альгамбры последнее мусульманское государство на Пиренейском полуострове прекратило существование, и Реконкиста была завершена. В том же году последуют изгнание евреев (март) и плавание Христофора Колумба (август).", "5dc28ef8"]},
"OLAYLAR_EK16:1500-07-14:0":{"b": ["Битва на Ведроши — Москва разбила литовскую армию; Брянск и Северская земля остались за Москвой", "d3f61400"], "d": ["В московско-литовской войне 1500–1503 гг. московская армия под командованием Даниила Щени близ Дорогобужа на реке Ведроше разбила войско гетмана Константина Острожского и взяла гетмана в плен. Города Брянск и Северск, взятые весной того же года, остались в руках Москвы; к концу войны около трети литовских земель перешло к Москве.", "e5879803"]},
"OLAYLAR_EK16:1503-04-02:0":{"b": ["Московско-литовское перемирие — Черниговско-Северская область перешла к Москве", "8e4c56f9"], "d": ["Московско-литовская война 1500–1503 гг. закончилась шестилетним перемирием при посредничестве венгерско-чешского короля Владислава II; Великое княжество Литовское вынуждено было уступить Великому княжеству Московскому обширный участок, составлявший около трети Великого княжества, — Черниговско-Северскую область (окрестности Чернигова, Новгорода-Северского, Стародуба, Брянска), а также некоторые земли в окрестностях Смоленска и Полоцка. Это было одним из крупнейших единовременных приобретений Москвы в процессе «собирания» русских земель.", "4cb77b9b"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["Взятие Шейбани-ханом Герата и Хорасана у Тимуридов", "a81d8575"], "d": ["Согласно статье TDV о Шейбани-хане, узбекский правитель Шейбани-хан, взяв в 1503–1505 гг. Андижан, Фергану, Гиссар, Кундуз и Балх, в 913 г. х. (1507 г.) завладел и тимуридской столицей Гератом; статья Encyclopaedia Iranica о Хорасане даёт точную дату этого завоевания — город пал 8 мухаррама 913 г. х. (20 мая 1507 г.), и неделей позже, 15 мухаррама (27 мая), была прочитана хутба на имя Шейбани-хана, чем завоевание было оформлено. Весь Хорасан, включая Мешхед, в том же году перешёл от Тимуридов к Шейбанидам; это означало, что Тимуридская династия после Мавераннахра потеряла и последнюю крупную крепость в Иране.", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["Падение Орана в руки Испании — африканский поход кардинала Сиснероса", "86ed8ac1"], "d": ["Оран, контролировавший морской путь в западной части Средиземного моря и бывший портом Тлемсена, вырос благодаря тому, что в 1492 г. туда бежали из Гранады андалусские мусульмане и евреи. Кастильское королевство, в начале XVI в. одно за другим занимавшее портовые города на берегу Магриба, 17 мая 1509 г. заняло Оран; большая часть населения была перебита, остальные взяты в плен, и в городе не осталось ни мусульманского, ни еврейского населения. Испанцы расширили стены и крепости; Оран оставался в руках Испании до 1708 г.", "be7b3b1b"]},
"OLAYLAR_EK16:1514-08-01:0":{"b": ["Смоленск сдался Москве — Василий III вступил в город", "46c61446"], "d": ["Во время третьей осады в московско-литовской войне 1512–1522 гг. литовский гарнизон сдался 31 июля; московская армия 1 августа торжественно вступила в город, и население присягнуло Василию III. Смоленск — крупнейшее приобретение Василия на западе; поражение, понесённое несколькими неделями позже под Оршей, не позволило вернуть город.", "803c9255"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["Присоединение Нидерландов к испанской короне — смерть Фердинанда, воцарение Карла V", "fbe0dbd2"], "d": ["После смерти арагонского короля Фердинанда II 23 января 1516 г. его внук Карл V, с 1506 г. уже управлявший Нидерландами (нынешними Бельгией, Нидерландами, Люксембургом и частью северной Франции) в качестве герцога Бургундского, стал наследником и кастильского, и арагонского престолов и 14 марта 1516 г. был провозглашён в Брюсселе королём Испании. Так эти земли посредством личной унии стали считаться подчинёнными не германской/австрийской ветви династии Габсбургов, а непосредственно испанской короне — в 1519 г. с избранием Карла V императором Священной Римской империи эти два качества (король Испании и германский император Римской империи) соединятся в одном лице, а подчинение области Испании продлится до 1556 г., когда Карл V отречётся от престола и оставит наследство сыну Филиппу II.", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["Разрушение Демаком Маджапахита и господство над берегом Явы", "7da602b5"], "d": ["Согласно статье TDV о Демаке, Султанат Демак, первое независимое мусульманское государство Явы, был основан Раденом Патахом в последней четверти XV в.; по яванским источникам, находившееся в упадке индуистско-буддийское царство Маджапахит исчезло под ударами Демака. В 1527 г. Демак завоевал Тубан, который китайские источники с XI в. упоминают как важный порт для правителей Маджапахита, — это год, когда и последние остатки Маджапахита подчинились Демаку, и поворотный пункт процесса исламизации большей части Явы.", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["Низведение Норвегии до провинции под датской короной", "8e2f274e"], "d": ["Датский король Кристиан III в своей коронационной хартии (håndfæstning) 1536 г. объявил, что Норвегия более не считается отдельным королевством, а будет управляться как провинция Дании, и что норвежский Государственный совет (riksråd) упразднён; это решение стало реальностью в 1537 г. с распространением на Норвегию Датского церковного устава, и сопротивление шотландско-норвежского епископа Олава Энгельбректссона было сломлено. Хотя на практике Норвегия ещё некоторое время сохраняла собственные законы и институты, её политический статус теперь был не независимым королевством, а провинцией под датской короной — это положение продлится до 1814 г.", "a8c9dee7"]},
"OLAYLAR_EK16:1558-05-01:0":{"b": ["Нарва взята русскими — первый большой город Ливонской войны", "c21130d7"], "d": ["Армии Ивана IV взяли Нарву; Россия вышла к берегу Балтики. Нарва оставалась в руках России до перехода к Швеции в 1581 г.", "8057148b"]},
"OLAYLAR_EK16:1558-07-01:0":{"b": ["Дерпт (Тарту) взят русскими", "f941a504"], "d": ["Русские армии в летнем походе 1558 г. взяли Дерпт (Тарту) и окрестные крепости; город оставался под русским управлением до Ям-Запольского перемирия 1582 г.", "35503ef9"]},
"OLAYLAR_EK16:1561-06-01:0":{"b": ["Ревель (Таллин) перешёл под покровительство Швеции — Северная Эстония перешла к Швеции", "3c183267"], "d": ["В период распада Ливонской конфедерации ревельский городской совет в 1561 г. принёс верность шведскому королю Эрику XIV; северная Эстония оставалась у Швеции до Великой Северной войны (1721 г.).", "cb752659"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["Виленский договор — Ливонская конфедерация распалась, Курляндия и Ливония подчинены Польше и Литве (кроме города Риги)", "d1ceaad5"], "d": ["Последний великий магистр Ливонской конфедерации, распавшейся под русским давлением в ходе Ливонской войны, Готхард Кетлер договором, подписанным 28 ноября 1561 г. в Вильнюсе (Pacta Subiectionis), перешёл под покровительство великого князя литовского и короля Польши Сигизмунда II Августа; большая часть Ливонии, кроме города Риги, была подчинена Польше и Литве, а Кетлер стал первым герцогом Курляндского герцогства. Это был последний акт перехода Ливонского ордена от Средневековья к Новому времени.", "bcd4efe9"]},
"OLAYLAR_EK16:1581-01-01:0":{"b": ["Швеция взяла Нарву у России", "5a7f7a6a"], "d": ["В последние годы Ливонской войны шведские войска взяли Нарву, находившуюся в русских руках с 1558 г.; город оставался у Швеции до 1704 г.", "5fee4227"]},
"OLAYLAR_EK16:1581-01-01:1":{"b": ["Вольный город Рига подчинён Речи Посполитой", "77dba329"], "d": ["Рига, остававшаяся на протяжении Ливонской войны вольным городом, в 1581 г. была подчинена Речи Посполитой; город оставался в ней до перехода к Швеции в 1621 г.", "ecdf652d"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["Акт об отречении (Plakkaat van Verlatinghe) — Нидерланды объявили о независимости от Испании", "a632aaee"], "d": ["В ходе Восьмидесятилетней войны Генеральные штаты (Staten-Generaal) нидерландских провинций, входивших в Утрехтскую унию, актом об отречении, принятым 26 июля 1581 г., объявили испанского короля Филиппа II «тираном» и отказали ему в верности; этот документ считается декларацией об основании фактически независимых Соединённых провинций (Республики Нидерландов). Окончательное признание Испании придётся ждать Вестфальского мира 1648 г., но фактический разрыв — в этот день.", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["Падение Смоленска к Речи Посполитой — конец двадцатимесячной осады", "4e9678e3"], "d": ["В эпоху Смуты войско польского короля Сигизмунда III 13 июня 1611 г. взорвав подкоп, пробило брешь в стенах Смоленска, осаждённого с сентября 1609 г., и овладело городом; двадцатимесячное сопротивление закончилось. Смоленск оставался в Речи Посполитой до 1654 г., и это падение подготовило почву для Деулинского перемирия (1618), которое будет подписано в тот же год.", "bc44374a"]},
"OLAYLAR_EK16:1611-07-16:0":{"b": ["Новгород взят шведской армией — в Смутное время северо-запад России перешёл под шведский контроль", "a8ab28bb"], "d": ["Шведская армия Якоба Делагарди взяла Новгород; город до 1617 г. был столицей «Новгородского государства» под шведским покровительством, в качестве кандидата в цари был выдвинут Карл Филипп.", "281592c2"]},
"OLAYLAR_EK16:1617-02-27:0":{"b": ["Столбовский мир — Россия потеряла балтийский берег (Ингрию) в пользу Швеции", "175dc175"], "d": ["Столбовский мир, положивший конец Ингрийской войне, был подписан 27 февраля 1617 г. в деревне Столбово к югу от Ладожского озера; Россия вернула Новгород и другие северные земли, тогда как Швеция сохранила Карелию и Ингрию (между Эстонией и Финляндией, включая крепости Ивангород, Ям, Копорье и Орешек), и непосредственный выход России к Балтике был отрезан. Этот разрыв продлится до основания Петром Великим в 1703 г. Санкт-Петербурга в той же местности.", "7e70e3e6"]},
"OLAYLAR_EK16:1617-02-27:1":{"b": ["Столбовский мир — Россия уступила Ингерманландию Швеции, Новгород возвращён", "e0bcbc7a"], "d": ["Россия уступила Швеции берега Невы и часть Карелии (Ям, Копорье, Ивангород, Орешек) и была оторвана от берега Балтики; Швеция вернула Новгород. Такое положение сохранялось до Великой Северной войны Петра I.", "bf517525"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["Деулинское перемирие — Смоленск, Чернигов и Новгород-Северский уступлены Польше", "6880d2c1"], "d": ["Деулинское перемирие, положившее конец польско-русской войне 1609–1618 гг., было подписано 11 декабря 1618 г. и обеспечило четырнадцатилетнее с половиной прекращение огня; Россия вынуждена была уступить Речи Посполитой Смоленск (кроме Вязьмы), а также 29 городов в областях Чернигова и Новгорода-Северского — это была самая тяжёлая территориальная потеря эпохи Смуты. Область оставалась в Польше до Андрусовского перемирия 1667 г.", "5c52de5a"]},
"OLAYLAR_EK16:1625-01-01:0":{"b": ["Швеция взяла у Польши Тарту (Дерпт) — второй этап Ливонского похода", "46b7c86a"], "d": ["Густав II Адольф в походе 1625 г. завоевал Южную Эстонию и Северную Ливонию; Тарту стал шведским городом, в котором в 1632 г. будет основана Академия Густава Адольфа.", "b58d9bd1"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["Переяславская рада — запорожские казаки присягнули русскому царю", "bcd8f8ef"], "d": ["Гетман запорожских казаков Богдан Хмельницкий, с 1648 г. восставший против Речи Посполитой, на Переяславской раде 18 января 1654 г. (8 января по юлианскому календарю), в которой участвовало прибывшее из Москвы посольство во главе с Василием Бутурлиным, присягнул на верность царю Алексею Михайловичу; это считается началом перехода Украинского казацкого гетманства под покровительство России, и оно сдвинуло фактический контроль над Черниговско-Северской областью от Польши к России — официальная же граница будет проведена Андрусовским перемирием 1667 г.", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["Возвращение Смоленска Россией", "bf0eca92"], "d": ["В ходе польско-русской войны, начавшейся в 1654 г., русская армия, осаждавшая Смоленск с июля, 3 октября 1654 г. вернула его после сдачи польского гарнизона; город, потерянный в 1611 г. в пользу Польши, через 43 года вернулся к России. Это был один из важнейших шагов в процессе обращения вспять потерь России эпохи Смуты, и он стал окончательным по Андрусовскому перемирию 1667 г.", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["Андрусовское перемирие — Киев и Левобережная Украина перешли к России", "799be067"], "d": ["Андрусовское перемирие, положившее конец польско-русской войне 1654–1667 гг., обеспечило прекращение огня на тринадцать с половиной лет; Россия получила Смоленск, Черниговско-Северскую область и Украину на левом берегу Днепра, а также — поначалу на два года, фактически навсегда — город Киев. Этот договор заложил правовую основу раздела украинских земель по Днепру между Польшей и Россией (и того, что Киев остался в России).", "94445e3a"]},
"OLAYLAR_EK16:1702-10-22:0":{"b": ["Россия взяла у Швеции Нётеборг (Орешек) — первая невская крепость Великой Северной войны", "28d180eb"], "d": ["Войска Петра I осадили и взяли Нётеборг (по-русски Орешек) при выходе из Ладоги и назвали его Шлиссельбург («Ключ-город»); это открыло путь к Неве и к основанию Санкт-Петербурга в 1703 г.", "3017c2be"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["Основание Санкт-Петербурга — окно России в Европу", "ba196be0"], "d": ["Пётр Великий 16/27 мая 1703 г. на Заячьем острове в дельте Невы, только что отвоёванной у Швеции в ходе Великой Северной войны, заложил Петропавловскую крепость (Петра и Павла); этот день принимается за дату основания города Санкт-Петербурга. Пётр задумал болотистую дельту как «окно» в Европу, и в 1712 г. город стал новой столицей России — область же была официально присоединена к России Ништадтским миром 1721 г.", "24c24aaf"]},
"OLAYLAR_EK16:1708-09-29:0":{"b": ["Взятие Менорки англо-голландскими силами", "3ca66a83"], "d": ["В ходе войны за испанское наследство англо-голландские силы, действовавшие как союзники австрийского эрцгерцога Карла (VI), под командованием генерала Джеймса Стэнхоупа 14 сентября 1708 г. высадились на острове и 28–29 сентября сломили испанскую оборону и овладели Меноркой (официальная сдача главной крепости, Fort St. Philip, затянулась до 24 ноября). Стратегическая гавань Менорки Маон в течение следующего столетия станет средоточием англо-французско-испанского соперничества.", "9188937e"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["Раштаттский мир — закончилась война за испанское наследство, Испанские Нидерланды и Милан перешли к Австрии", "3c0e086f"], "d": ["Раштаттский мир, положивший конец войне за испанское наследство между Францией и Австрией, был подписан 7 марта 1714 г. (Утрехтский мир 1713 г. урегулировал отношения между Англией и Францией); по договору австрийские Габсбурги получили Испанские Нидерланды (нынешнюю Бельгию), а в Италии — Неаполь, Милан и Сардинию. Это было крупнейшее территориальное расширение Австрии в её истории, и к весу династии Габсбургов в Центральной Европе оно добавило новый фронт в Западной и Южной Европе.", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["Ништадтский мир — закончилась Великая Северная война, балтийские берега перешли к России", "068ffd06"], "d": ["Ништадтский мир, положивший конец Великой Северной войне, длившейся 21 год, был подписан 30 августа 1721 г. в Финляндии; Швеция уступила России Эстонию, Ливонию (включая Ригу), Ингерманландию и часть юго-восточной Финляндии (Карелию), взамен получила обратно остальную Финляндию, и была выплачена компенсация. Договор считается концом статуса Швеции как великой державы и официальным закреплением возвышения России как европейской империи — после этой победы Пётр I принял титул «императора».", "ff69c190"]},
"OLAYLAR_EK16:1772-08-05:0":{"b": ["Первый раздел Польши — потеря земель в пользу России и Австрии", "2c56a0d8"], "d": ["Договором, подписанным 5 августа 1772 г. между Россией, Пруссией и Австрией, была разделена примерно треть земель Речи Посполитой: Россия получила часть нынешней Белоруссии и Латвии (включая Динабург, Полоцк и Витебск), Австрия присоединила Галицию (Львов и западное Подолье, включая Язловец), а Пруссия получила прибрежную область Королевскую Пруссию. Польский сейм утвердил договор лишь 30 сентября 1773 г. под давлением. Это был первый из трёх разделов, которые продлятся до 1795 г.", "6f2b4118"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["Второй раздел Польши — потеря земель в пользу России и Пруссии", "31750484"], "d": ["После того как реформы конституции 1791 г. встревожили Россию и Пруссию, оба государства вновь разделили Польшу по договору, подписанному в Санкт-Петербурге 23 января 1793 г.: Россия получила большую часть Литвы-Белоруссии и западную Украину (включая Каменец, Бар и Минск), а Пруссия аннексировала Великую Польшу, включая Гданьск и Познань, - всего 307 000 км². Польский сейм, находившийся под давлением, был вынужден ратифицировать договор в том же году; это был недолговечный раздел, отсрочивший полную аннексию Польши на два года. В этот день (23 января 1793 г.) при Втором разделе Польши Правобережная Украина, включая Бердичев, Фастов, Житомир, Канев, Константинов, Умань и Черкассы, перешла к России.", "656e71c2"]},
"OLAYLAR_EK16:1795-03-28:0":{"b": ["Герцогство Курляндия и Семигалия присоединено к России — последний герцог Пётр фон Бирон отрёкся", "8d0e410f"], "d": ["В ходе Третьего раздела Польши курляндское дворянство принесло верность Екатерине, герцог Пётр фон Бирон отрёкся от престола; Курляндия стала губернией России (в источниках встречается также дата 24 октября 1795 г.).", "4682774b"]},
"OLAYLAR_EK16:1795-10-24:0":{"b": ["Третий раздел Польши — полное исчезновение государства", "e3c02d6b"], "d": ["Россия, Пруссия и Австрия трёхсторонней конвенцией, подписанной 24 октября 1795 г. в Санкт-Петербурге, полностью разделили оставшиеся земли Речи Посполитой: Россия получила Литву (включая Вильнюс и Каунас) и остаток Белоруссии, Пруссия присоединила центральную Польшу с Варшавой, а Австрия — южную область с Краковом. Три государства также взаимно гарантировали военными средствами новые земли друг друга и приняли меры на случай восстановления Польши. Это полное исчезновение польско-литовского государства как независимой страны; оно не будет восстановлено до XX в.", "a66df675"]},
"OLAYLAR_EK16:1797-05-12:0":{"b": ["Конец Венецианской республики — Большой совет распустил себя", "5efed589"], "d": ["Когда армия итальянского похода Наполеона заняла венецианскую сушу и предъявила республике ультиматум, Большой совет (Maggior Consiglio) 12 мая 1797 г. голосами 512 против 20 согласился на самороспуск; последний дож Лудовико Манин оставил свой пост, и аристократическое правление Венецианской республики, непрерывно существовавшей более 1.100 лет, закончилось. Её земли сначала перешли под временное демократическое правление, а затем в октябре 1797 г. по Кампо-Формийскому миру были официально уступлены Австрии.", "8852717b"]},
"OLAYLAR_EK16:1797-06-14:0":{"b": ["Конец Генуэзской республики — Наполеон создал Лигурийскую республику", "3d3e59ee"], "d": ["На смену Генуэзской республике, переданной под давлением Наполеона в итальянском походе в начале июня 1797 г. временному правлению, 14 июня 1797 г. по конституции французского образца была провозглашена «Лигурийская республика»; вековое Генуэзское герцогство фактически превратилось в одно из государств-сателлитов Франции. Республика в 1805 г. будет непосредственно присоединена к Франции, а по Венскому конгрессу 1815 г. передана Сардинско-Пьемонтскому королевству.", "38af1e4b"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["Кампо-Формийский мир — раздел Венеции между Австрией и Францией", "9f29678c"], "d": ["Кампо-Формийский мир, подписанный 17 октября 1797 г. между Наполеоном Бонапартом и представителем Австрии графом Кобенцлем, официально упразднил тысячелетнюю Венецианскую республику и разделил её земли: земли к востоку от реки Адидже, Истрия и побережье Далмации (включая Сплит, Задар, Шибеник и Котор) отошли к Австрии, а Додеканес и Ионические острова (Корфу, Кефалония, Закинф, Лефкада, а также базы Венеции на побережье Албании и Мореи, включая Превезу и Парг) — к Франции. Австрия также уступила Франции свои земли в Нидерландах (нынешней Бельгии).", "c490738c"]},
"OLAYLAR_EK16:1800-09-05:0":{"b": ["Сдача Мальты Англии — конец двухлетней французской осады", "fedc2867"], "d": ["Мальта, захваченная Наполеоном в 1798 г. на пути в египетский поход, вскоре в результате восстания жителей острова попала в морскую блокаду английского флота; после двухлетней осады и голода французский командир генерал Вобуа 5 сентября 1800 г. сдался английскому генералу Пиготту. Мальта таким образом перешла от Французской республики под английское покровительство и по Парижскому договору 1814 г. будет официально присоединена к английской короне — она стала важнейшей английской военно-морской базой на Средиземном море.", "6f406ae3"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["Амьенский мир — Менорка возвращена Испании", "f341e4b8"], "d": ["Амьенский мир (25 марта 1802 г.), подписанный между Францией, Испанией, Голландией и Англией, временно положил конец войне Второй коалиции; Англия вернула почти все земли, захваченные ею в ходе войны (кроме Цейлона и Тринидада), — в их числе была и Менорка, взятая у Испании в 1798 г. Мир продлился лишь год, в мае 1803 г. война вспыхнула вновь, но Менорка после этого договора уже не переходила в руки англичан.", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["Фридрихсгамский мир — уступка Швецией Финляндии России", "c0d407bc"], "d": ["Фридрихсгамский (нынешняя Хамина) мир, положивший конец русско-шведской войне 1808–1809 гг., был подписан 17 сентября 1809 г.; Швеция уступила России всю Финляндию, включая Аландские острова. Финляндия получила статус великого княжества с широкой автономией в составе Российской империи и сохранила лютеранскую веру и шведское право. Это означало фактический конец статуса Швеции как великой державы на Балтике.", "4362e6c6"]},
"OLAYLAR_EK16:1810-03-04:0":{"b": ["Присоединение Имеретинского царства — царь Соломон II низложен", "5ad36bff"], "d": ["Последний царь Западной Грузии, Имеретинского царства, вынужденного в 1804 г. по договору Elaznauri принять русское вассальство, Соломон II продолжал сопротивляться возрастающему русскому давлению; тогда русские войска 20 февраля 1810 г. заняли столицу Кутаиси, низложили Соломона и заставили местную знать присягнуть императору Александру I; Имеретинское царство тем самым фактически прекратилось и было подчинено непосредственно русскому управлению. Соломон бежал в османские земли и умер в изгнании (1815).", "fdccc40f"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["Кильский мир — уступка Данией Норвегии Швеции", "59ab1601"], "d": ["Швеция, напавшая на Данию с юга после поражения Наполеона под Лейпцигом, по Кильскому миру, подписанному 14 января 1814 г., получила Норвегию (кроме Исландии, Фарерских островов и Гренландии) — датско-норвежская уния, длившаяся с 1380 г., тем самым официально закончилась. Взамен Швеция уступила Дании свои земли в Померании; Дания также передала Гельголанд Англии. Норвегия оказала договору вооружённое сопротивление и провозгласила собственную конституцию, и Швеции пришлось это признать — итогом стала личная уния (real union), продлившаяся до 1905 г. Швеция не смогла фактически принять Норвегию: договор не был признан в Норвегии, и управление осталось у Кристиана Фредерика; шведская армия вступила в Норвегию лишь 26 июля 1814 года.", "223aed9a"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["Заключительный акт Венского конгресса — карта Европы после Наполеона перечерчена", "fca1c676"], "d": ["Заключительный акт Венского конгресса, подписанный великими державами (Австрией, Россией, Пруссией, Англией, Францией), положившими конец Наполеоновским войнам, был принят 9 июня 1815 г. (за 9 дней до Ватерлоо) и коллективно перечертил карту континента: прежние испанские/австрийские Нидерланды и Соединённые провинции объединились под «Соединённым королевством Нидерландов», Генуэзская республика была присоединена к Сардинско-Пьемонтскому королевству, большая часть Варшавского герцогства под названием «Конгрессовая Польша» была подчинена России, а Шведская Померания (Штральзунд) перешла к Пруссии. Этот единый день считается официальным началом послевоенного европейского равновесия (Concert of Europe).", "39c08302"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["Генеральный морской договор — кавасим и прочие шейхства Залива связаны договором с Англией", "fc499e19"], "d": ["После того как Англия в 1819 г. бомбардировала Рас-эль-Хайму и разгромила флот «пиратов» кавасим, она навязала Генеральный морской договор, начатый 8 января 1820 г. и завершённый к марту подписанием по одному с шейхствами региона; договор запретил пиратство и рабство и обязал суда нести красно-белый флаг, схожий с английским. С этим договором «Пиратский берег» со временем превратился в «Договорное побережье» (Trucial Coast); углубившаяся вечным морским перемирием 1853 г. и эксклюзивными соглашениями 1892 г. английская гегемония положила начало отношениям, которые продлятся до 1971 г.", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["Конец осады Гаэты — крах Королевства Обеих Сицилий", "121ae580"], "d": ["После краха, начавшегося высадкой Гарибальди на Сицилии в мае 1860 г., бежавший из Неаполя бурбонский король Франциск II с 3 ноября 1860 г. был осаждён в своей последней крепости Гаэте; с уходом французского флота из района в январе 1861 г. итальянская морская блокада ужесточилась, и 13 февраля 1861 г. Гаэта сдалась. Франциск II отказался от трона и отправился в изгнание; последний очаг сопротивления Королевства Обеих Сицилий, Чивителла-дель-Тронто, падёт лишь 20 марта 1861 г.", "ad1202f1"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["Провозглашение Королевства Италия — объединение Сардинии, Тосканы и Южной Италии", "12e52f70"], "d": ["На первом заседании итальянского парламента в Турине 17 марта 1861 г. было официально провозглашено Королевство Италия, и король Сардинии — Пьемонта Виктор Эммануил II стал первым королём объединённой Италии. Новое королевство объединяло с Сардинским королевством земли Тосканы, Эмилии-Романьи, Неаполя и Сицилии (Обеих Сицилий), присоединённые в прошлом году народными голосованиями; Рим (Папская область) и Венеция (Австрия) пока оставались за его пределами — они присоединятся соответственно в 1870 и 1866 гг.", "d044a9c0"]},
"OLAYLAR_EK16:1866-10-18:0":{"b": ["Падение Джизака к России — последняя крепость Бухарского эмирата на линии Сырдарьи", "21205a6e"], "d": ["В ходе продвижения России в Средней Азии, после неудачной попытки генерала Черняева в феврале 1866 г., русские силы под командованием назначенного ему на смену генерала Дмитрия Романовского в октябре 1866 г. после семидневной осады и яростного штурма взяли Джизак, последнюю большую крепость Бухарского эмирата в долине Сырдарьи; это падение фактически положило конец бухарскому сопротивлению в регионе и открыло русской армии путь к Самарканду.", "b95ba993"]},
"OLAYLAR_EK16:1882-03-10:0":{"b": ["Переход Асэба в государственную собственность Италии — основа первой колонии Италии", "15ab8732"], "d": ["Порт Асэб на берегу Красного моря был в 1869 г. куплен частной итальянской судоходной компанией (Рубаттино) у местных афарских вождей; с согласия Англии итальянское правительство 10 марта 1882 г. приняло порт в прямую государственную собственность и принятым в июле законом официально объявило Асэб первой колонией Италии. Это стало отправной точкой расширения Италии на берегу Красного моря, которое позднее превратится в колонию Эритрея (1890).", "ba606490"]},
"OLAYLAR_EK16:1884-02-08:0":{"b": ["Уничтожение гарнизона Синката — Синкат перешёл к силам Махди", "e175a94e"], "d": ["Гарнизон Синката, месяцами осаждённый силами Османа Дигны и лишившийся припасов, вместе со своим командиром Тауфик-беем попытался прорвать осаду и дойти до Суакина; 8 февраля 1884 г. он был уничтожен вне крепости, и Синкат перешёл в руки сил Махди. Весть достигла Суакина 12 февраля.", "abf8611c"]},
"OLAYLAR_EK16:1884-02-09:0":{"b": ["Осадное положение в Суакине — город перешёл под английское командование", "801f6a81"], "d": ["После разгрома 4 февраля при Эль-Тебе спасательных сил Бейкера, шедших на выручку Токара, адмирал Хьюитт 6 февраля высадил в Суакине морскую пехоту. 9 февраля 1884 г. в городе было объявлено осадное положение, и английским офицерам были даны полные военные и гражданские полномочия над городом; на следующий день ответственность за город была официально передана от Бейкера Хьюитту.", "92798eb8"]},
"OLAYLAR_EK16:1884-02-20:0":{"b": ["Сдача Токара силам Махди", "0e21fd24"], "d": ["Осаждённый гарнизон Токара 19 февраля 1884 г. вступил в переговоры с силами Махди и на следующий день, 20 февраля, сдал город. Весть достигла английских сил в Тринкитате 24 февраля; спасательная операция Грэма запоздала.", "0ebad590"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["Установление Британией протектората на северном берегу Сомали — начало Сомалиленда", "f301ea94"], "d": ["Согласно статье TDV о Сомали, Зейла, Бербера и Таджура в 1884 г. были колонизованы англичанами под названием Сомалиленд; по стандартному академическому источнику, этот процесс начался с договора, подписанного в Бербере с племенем Хабар Авел и приходящегося на 21 рамадана 1301 г. х. (14 июля 1884 г.), и расширился подписанием в 1884–1886 гг. подобных договоров с племенами Gadabursi, Habar Tolcaala, Habar Gerhacis, исса и Warsangeli; Англия в обмен обещала военную защиту. Эта цепь договоров подготовила почву для провозглашения в 1887 г. официального Протектората Британское Сомалиленд.", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["Битва при Мулайде — конец Второго государства Саудидов, Неджд перешёл к Рашидидам", "1cd3b213"], "d": ["Когда отношения испортились из-за спора о закяте и ареста одного рашидидского посла, армия эмира Джебель-Шаммара Мухаммада ибн Рашида 21 января 1891 г. в Мулайде в области Касим нанесла тяжёлое поражение силам Саудидов под руководством Абд ар-Рахмана ибн Фейсала и их союзникам; это стало фактическим концом Второго государства Саудидов: семья Аль Сауд отправилась в изгнание в Кувейт, а весь Неджд перешёл под власть Рашидидов. Эта власть продлится до 1902 г., когда молодой Абдул-Азиз ибн Сауд отвоюет Эр-Рияд (рейд на Эр-Рияд, 16 января 1902 г.).", "e496bc0f"]},
"OLAYLAR_EK16:1891-02-19:0":{"b": ["Возвращение Токара англо-египетскими силами — отход Османа Дигны", "80a2c26a"], "d": ["Токар на берегу Красного моря, с 1884 г. находившийся в руках местного командира движения Махди Османа Дигны, в феврале 1891 г. был возвращён в результате операции англо-египетских сил; Осману Дигне пришлось отойти в горы. Это стало тяжёлым ударом по присутствию Государства Махди на берегу Красного моря, и область перешла под совместное англо-египетское управление.", "07bd31cf"]},
"OLAYLAR_EK16:1891-03-03:0":{"b": ["Проход колонны Гренфелла через Синкат — Синкат вышел из-под власти Махди и вернулся под англо-египетское управление", "b7539a44"], "d": ["После возвращения Токара в феврале 1891 г. англо-египетская колонна под командованием Гренфелла 3 марта 1891 г. выступила из Афафита через Синкат и 7 марта прибыла в Суакин; колонна нашла область, в которую с 1884 г. невозможно было войти, полностью очищенной от противника. 8 марта собравшимся в Суакине шейхам от имени хедива была объявлена всеобщая амнистия, и Синкат вновь был подчинён англо-египетскому управлению.", "5e77e2d3"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["Переход Итальянского Сомали на прямое государственное управление — ликвидация Компании Бенадир", "8c7d085b"], "d": ["Согласно статье TDV о Сомали, Италия утвердила своё господство на южном сомалийском берегу (Бенадир) договорами 1889–1891 гг. с Занзибарским султанатом и Англией, а управление поначалу передала привилегированной торговой компании (Benadir Company); по стандартному академическому источнику, концессия этой компании истекла 24 января 1905 г., и итальянское государство, выкупив прямой суверенитет над берегом Бенадир (включая Могадишо, Мерку и Барава), установило официальное колониальное управление. Фактическое расширение колонии вглубь страны (Бардера, Байдоа) завершится указом об учреждении 1908 г. и в последующие годы.", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["Роспуск унии Норвегии и Швеции — односторонняя декларация независимости Стортингом", "aaba2935"], "d": ["После того как король Оскар II наложил вето на требование норвежского правительства об учреждении отдельного консульства и объявил, что не сможет сформировать новое правительство, норвежский Стортинг (парламент) 7 июня 1905 г. единогласно постановил, что король фактически более не исполняет обязанностей короля Норвегии и что уния, продолжавшаяся с Кильского мира 1814 г., расторгнута. На народном голосовании 13 августа 1905 г. почти все избиратели (371.000 против 184) одобрили роспуск; Швеция после Карлстадских переговоров 26 октября 1905 г. официально признала независимость.", "94eda38c"]},
"OLAYLAR_EK16:1915-05-08:0":{"b": ["Либава (Лиепая) взята немецкими силами — началась оккупация Курляндии", "fdb10548"], "d": ["В немецком летнем наступлении 1915 г. немцы вошли в Курляндию; Либава была русской военно-морской базой на берегу Балтики. Большая часть Курляндии перешла под управление Ober Ost (до конца 1918 г.).", "98e7ef58"]},
"OLAYLAR_EK16:1915-08-01:0":{"b": ["Митава (Елгава) взята немецкими силами", "eb491281"], "d": ["Бывшая столица герцогства Курляндии Митава перешла под немецкий контроль; рижский фронт замер на линии Даугавы и простоял так до 1917 г.", "05882415"]},
"OLAYLAR_EK16:1915-08-18:0":{"b": ["Крепость Ковно (Каунас) взята немцами — Литва оказалась под оккупацией", "9849405b"], "d": ["Немецкая 10-я армия взяла самую большую русскую крепость на Немане; Литовский край перешёл под управление Ober Ost, и в 1918 г. Литовская тариба провозгласила независимость в условиях этой оккупации.", "1f9a43bc"]},
"OLAYLAR_EK16:1915-09-18:0":{"b": ["Вильна (Вильнюс) взята немецкими силами", "2781858b"], "d": ["Во время Великого отступления Вильна перешла к немецким силам и была присоединена к Литовскому краю Ober Ost; город до 1919 г. переходил из рук в руки между немецкими, советскими и польскими силами.", "d9dddcbb"]},
"OLAYLAR_EK16:1916-11-03:0":{"b": ["Англо-катарский договор — Катар перешёл под английский протекторат", "f61c4e49"], "d": ["Во время Первой мировой войны по договору, подписанному 3 ноября 1916 г. между английским политическим представителем в Персидском заливе майором Перси Коксом и катарским шейхом Абдуллой ибн Касимом Аль Тани, Катар согласился поставить свои внешние сношения в зависимость от согласия Англии, получив взамен гарантию английской защиты от нападений с моря; этот договор стал правовой основой английских протекторатных отношений Катара, продлившихся до 1971 г., и был официально ратифицирован в 1918 г.", "abf30185"]},
"OLAYLAR_EK16:1917-09-03:0":{"b": ["Рига взята немецкой 8-й армией", "df95df19"], "d": ["Немецкие силы форсировали Даугаву и взяли Ригу; город оставался под немецким контролем до ноября 1918 г., независимость Латвии была провозглашена в условиях этой оккупации (18 ноября 1918 г.).", "e0339705"]},
"OLAYLAR_EK16:1918-11-18:0":{"b": ["Народный совет Латвии провозгласил независимость", "fc72a7f7"], "d": ["Народный совет Латвии, собравшийся в Национальном театре в Риге, провозгласил Латвийскую Республику, независимую от Российской империи; было образовано временное правительство во главе с Карлисом Улманисом. Через несколько недель (декабрь 1918 г.) Советская Россия напала, и началась война за независимость.", "2858d946"]},
"OLAYLAR_EK16:1919-01-05:0":{"b": ["Красная армия вошла в Вильнюс — литовское правительство покинуло город", "889a97b3"], "d": ["Литовское правительство оставило Вильнюс при приближении Красной армии; советские войска вошли в город, и в феврале 1919 г. отсюда была провозглашена Литовско-Белорусская Советская Республика (Литбел). Город будет взят польскими силами в апреле 1919 г.", "c3a0c216"]},
"OLAYLAR_EK16:1919-04-21:0":{"b": ["Польские силы взяли у советских войск Вильнюс (Вильно)", "32d36c4a"], "d": ["Войска Юзефа Пилсудского в апреле 1919 г. взяли Вильно у Красной армии; Литва продолжала претендовать на город, и вильнюсский вопрос отравлял литовско-польские отношения в межвоенный период.", "85e7c434"]},
"OLAYLAR_EK16:1920-10-12:0":{"b": ["Желиговский провозгласил Срединную Литву — Вильнюс стал столицей поддержанного Польшей марионеточного государства", "11400510"], "d": ["Генерал Люциан Желиговский своим «мятежом» взял Вильнюс и провозгласил Республику Срединная Литва; государство просуществовало до 24 марта 1922 г.", "d8050fe5"]},
"OLAYLAR_EK16:1922-02-28:0":{"b": ["Великобритания отменила протекторат над Египтом и провозгласила его независимость", "f8faab66"], "d": ["Декларацией от 28 февраля 1922 года Великобритания в одностороннем порядке отменила протекторат, существовавший с 1914 года, и провозгласила Египет независимым государством, оставив за собой, в частности, оборону, имперские коммуникации и Судан. Через две недели (15 марта 1922 года) султан Ахмед Фуад принял титул короля. На карте слой британской оккупации над египетскими городами заканчивается в этот день.", "8cde4005"]},
"OLAYLAR_EK16:1922-03-24:0":{"b": ["Срединная Литва присоединена к Польше — Вильнюс стал польским", "e929fa20"], "d": ["Виленский сейм 20 февраля 1922 г. проголосовал за присоединение; польский сейм утвердил его 24 марта 1922 г. Конференция послов признала границу в 1923 г., Литва её не признала.", "4a067568"]},
"OLAYLAR_EK16:1939-03-22:0":{"b": ["Литва приняла германский ультиматум — Мемельская область передана Германии", "149fb0b2"], "d": ["По ультиматуму Риббентропа Литва уступила Германии Клайпедский (Мемельский) край; Гитлер вошёл в Мемель 23 марта. Область была взята Красной армией 28 января 1945 г.", "75afd979"]},
"OLAYLAR_EK16:1939-09-19:0":{"b": ["Красная армия заняла Вильнюс", "5b25d037"], "d": ["Красная армия, вступившая 17 сентября в восточную Польшу, в ночь с 18 на 19 сентября вошла в Вильнюс, находившийся в руках Польши. По советско-литовскому пакту о взаимопомощи от 10 октября город будет передан Литве, а литовская армия войдёт в него 28 октября.", "285aa71c"]},
"OLAYLAR_EK16:1939-10-28:0":{"b": ["Литва получила Вильнюс — цена советско-литовского пакта о взаимопомощи", "37ba5976"], "d": ["Вильнюс, взятый Красной армией 19 сентября 1939 г., по пакту о взаимопомощи от 10 октября 1939 г. был передан Литве; литовская армия вошла в город 28 октября. Взамен в Литве разместились советские гарнизоны, в 1940 г. последовало присоединение.", "60d2f2bf"]},
"OLAYLAR_EK16:1941-06-23:0":{"b": ["Германия заняла Гродно", "b7ca9378"], "d": ["Восточный фронт: «Барбаросса» 1941 г. и «Багратион» 1944 г.", "c6101096"]},
"OLAYLAR_EK16:1941-06-23:1":{"b": ["Германия заняла Брест-Литовск", "25898c65"], "d": ["Восточный фронт: «Барбаросса» 1941 г. и «Багратион» 1944 г.", "c6101096"]},
"OLAYLAR_EK16:1941-07-09:0":{"b": ["Псков взят немецкой армией — началась оккупация русских земель", "d9822e30"], "d": ["На третьей неделе операции «Барбаросса» вермахт вошёл в Псков; город оставался под немецким военным управлением до 23 июля 1944 г. Источник: хронология города Пскова, memorialmuseums.org «Memorials in Pskov» — краткое изложение результатов поиска [резюме].", "c875c7b2"]},
"OLAYLAR_EK16:1941-07-11:0":{"b": ["Витебск взят немецкой армией", "e1e4d7d0"], "d": ["Группа армий «Центр» взяла Витебск в первые недели «Барбароссы»; город оставался под немецким военным управлением до июня 1944 г., большая часть его населения погибла.", "aeb95ab0"]},
"OLAYLAR_EK16:1941-07-16:0":{"b": ["Смоленск взят немецкой армией", "5a7f4e2a"], "d": ["Группа армий «Центр» взяла Смоленск; этот город на пути к Москве оставался под оккупацией 26 месяцев, до 25 сентября 1943 г., и подвергся большим разрушениям.", "1cff2f04"]},
"OLAYLAR_EK16:1941-07-26:0":{"b": ["Могилёв взят немецкой армией", "4362b7a1"], "d": ["Могилёв после 23 дней обороны перешёл в руки вермахта; город оставался под оккупацией до 28 июня 1944 г.", "082ca73b"]},
"OLAYLAR_EK16:1941-07-28:0":{"b": ["Основан рейхскомиссариат Остланд — страны Балтии и Белоруссия перешли под немецкое гражданское управление", "052d4c08"], "d": ["Решением Гитлера от 17 июля 1941 г. занятые территории Востока были переданы гражданскому управлению; Остланд под руководством Хинриха Лозе охватил Эстонию, Латвию, Литву и Белоруссию (центр — Рига). Гражданское управление Эстонии — с 5 декабря 1941 г.; восток Белоруссии остался под военным управлением.", "83f60be8"]},
"OLAYLAR_EK16:1941-08-17:0":{"b": ["Нарва взята немецко-эстонскими силами", "60fc2b6a"], "d": ["В Летней войне эстонские добровольцы и вермахт взяли Нарву; город был включён в Остланд и до 26 июля 1944 г. оставался под немецким управлением.", "0f32445c"]},
"OLAYLAR_EK16:1941-08-19:0":{"b": ["Новгород взят немецкой армией", "4f599b62"], "d": ["Группа армий «Север» взяла Новгород; один из древнейших городов России оставался под оккупацией до января 1944 г. и был в значительной мере разрушен.", "ac0d4ff0"]},
"OLAYLAR_EK16:1941-08-19:1":{"b": ["Гомель взят немецкой армией", "9d78eb92"], "d": ["Через три дня после наступления вермахта на Гомель Красная армия полностью отошла из города; город оставался под оккупацией до 26 ноября 1943 г.", "56a11e36"]},
"OLAYLAR_EK16:1941-08-28:0":{"b": ["Таллин взят немецкой 18-й армией", "a855ad0d"], "d": ["С кровавой эвакуацией Балтийского флота СССР в Кронштадт Таллин пал; Эстония в составе Остланда стала Generalbezirk Estland (гражданское управление с 5 декабря 1941 г.).", "859cfaf1"]},
"OLAYLAR_EK16:1941-10-03:0":{"b": ["Орёл взят немецкой армией", "3127f454"], "d": ["В Брянско-Вяземской операции немецкая 2-я танковая армия взяла Орёл; город оставался под оккупацией до 5 августа 1943 г.", "f5465227"]},
"OLAYLAR_EK16:1941-10-06:0":{"b": ["Брянск взят немецкой армией", "20fa93f8"], "d": ["По окончании Брянского сражения немецкие силы вошли в город; город оставался под оккупацией до 17 сентября 1943 г.", "f4a24f91"]},
"OLAYLAR_EK16:1941-11-03:0":{"b": ["Курск взят немецкой армией", "a723a00a"], "d": ["По приказу советского командования Курск был оставлен, и немецкая 2-я армия вошла в город; город оставался под оккупацией до 8 февраля 1943 г.", "0d07184e"]},
"OLAYLAR_EK16:1943-02-08:0":{"b": ["Курск освобождён Красной армией", "1ac03fba"], "d": ["В конце советского зимнего наступления (Курско-Харьковское направление после Воронежско-Касторненской операции) Курск был возвращён; в июле того же года имя города было дано Курской битве.", "68d51be4"]},
"OLAYLAR_EK16:1943-08-05:0":{"b": ["Орёл возвращён Красной армией — первый советский салют после Курска", "80bfc68d"], "d": ["Взятие Орловского выступа и первый артиллерийский салют в Москве вместе с Белгородом.", "5714054b"]},
"OLAYLAR_EK16:1943-09-17:0":{"b": ["Брянск возвращён Красной армией", "d0f2a35f"], "d": ["Брянской операцией город был возвращён 17 сентября 1943 г.", "e6b7799d"]},
"OLAYLAR_EK16:1943-09-25:0":{"b": ["Смоленск освобождён Красной армией", "6516d85a"], "d": ["На пике Смоленской операции 7 августа — 2 октября 1943 г. город был возвращён; в 1985 г. Смоленск получил звание «город-герой».", "e355d898"]},
"OLAYLAR_EK16:1943-11-26:0":{"b": ["Гомель освобождён Красной армией", "280268c2"], "d": ["Белорусский фронт в Гомельско-Речицкой операции вернул город; это одно из первых крупных освобождений городов Белоруссии.", "3402c1b4"]},
"OLAYLAR_EK16:1944-01-20:0":{"b": ["Новгород освобождён Красной армией", "52962012"], "d": ["В ходе Ленинградско-Новгородской операции Великий Новгород был возвращён 20 января 1944 г.", "75ea1a61"]},
"OLAYLAR_EK16:1944-06-26:0":{"b": ["Витебск освобождён Красной армией — операция «Багратион»", "b06be69c"], "d": ["1-й Прибалтийский и 3-й Белорусский фронты окружили и взяли Витебск; это было первое крупное освобождение города в операции «Багратион».", "9b4d6042"]},
"OLAYLAR_EK16:1944-06-28:0":{"b": ["Могилёв освобождён Красной армией — операция «Багратион»", "52fa985d"], "d": ["2-й Белорусский фронт взял Могилёв и форсировал линию Днепра.", "22c05c20"]},
"OLAYLAR_EK16:1944-07-03:0":{"b": ["Красная армия вернула Минск — операция «Багратион»", "87dc1fb5"], "d": ["В операции «Багратион», начавшейся 22 июня, Белорусские фронты прорвали группу армий «Центр» и окружили Минск; город был возвращён 3 июля, и на востоке в окружении осталось около 50 тысяч немецких солдат. Немецкое гражданское управление Белоруссии (Generalbezirk Weißruthenien) рухнуло.", "1c35549f"]},
"OLAYLAR_EK16:1944-07-13:0":{"b": ["Красная армия взяла Вильнюс", "0172450e"], "d": ["В Вильнюсской операции 5–13 июля 3-й Белорусский фронт окружил немецкий гарнизон и взял город (операция «Острая Брама» польской Армии Крайовой шла одновременно). Вильнюс стал столицей Литовской ССР.", "aaf124b7"]},
"OLAYLAR_EK16:1944-07-16:0":{"b": ["Красная армия освободила Гродно от немецкой оккупации", "1d134151"], "d": ["Восточный фронт: «Барбаросса» 1941 г. и «Багратион» 1944 г.", "c6101096"]},
"OLAYLAR_EK16:1944-07-23:0":{"b": ["Псков возвращён Красной армией", "f18103aa"], "d": ["После более чем трёхлетней немецкой оккупации Псков был возвращён Красной армией.", "b6fb3c84"]},
"OLAYLAR_EK16:1944-07-26:0":{"b": ["Красная армия взяла Нарву", "64854ae3"], "d": ["Нарва, с февраля 1944 г. лежавшая в руинах на линии фронта, была взята советскими силами в ходе Нарвской операции июля 1944 г.; северо-восток Эстонии вышел из-под немецкого гражданского управления (Generalbezirk Estland).", "74009a05"]},
"OLAYLAR_EK16:1944-07-27:0":{"b": ["Резекне взят Красной армией — восток Латвии освобождён", "e9efd12d"], "d": ["2-й Прибалтийский фронт взял Резекне; латвийская область Латгалия вышла из-под немецкого управления.", "eac95aa6"]},
"OLAYLAR_EK16:1944-07-27:1":{"b": ["Даугавпилс освобождён Красной армией", "b4ee6622"], "d": ["360-я стрелковая дивизия 2-го Прибалтийского фронта взяла Даугавпилс (Динабург); второй по величине город Латгалии вышел из-под немецкого управления.", "b8a7bd0d"]},
"OLAYLAR_EK16:1944-07-27:2":{"b": ["Шяуляй взят Красной армией — Шяуляйская операция", "ccb20729"], "d": ["1-й Прибалтийский фронт взял железнодорожный узел на севере Литвы Шяуляй; операция продолжалась с 5 июля по 29 августа 1944 г., и был достигнут Рижский залив.", "444f3101"]},
"OLAYLAR_EK16:1944-07-28:0":{"b": ["Красная армия освободила Брест-Литовск от немецкой оккупации", "6d5a837a"], "d": ["Восточный фронт: «Барбаросса» 1941 г. и «Багратион» 1944 г.", "c6101096"]},
"OLAYLAR_EK16:1944-08-01:0":{"b": ["Каунас взят Красной армией — временная столица Литвы вышла из-под немецкого управления", "5c2b2c16"], "d": ["3-й Белорусский фронт взял Каунас; ежедневный приказ Сталина от 1 августа возвестил о взятии. Город в 1919–1939 гг. был временной столицей Литвы.", "795fab27"]},
"OLAYLAR_EK16:1944-08-25:0":{"b": ["Тарту взят Красной армией — Тартуская операция", "cc8069ab"], "d": ["3-й Прибалтийский фронт прорвал оборону немецкой 18-й армии и взял Тарту; город несколько недель оставался на линии фронта, а Тартуская операция закончилась 6 сентября 1944 г.", "3e9ef2ba"]},
"OLAYLAR_EK16:1944-09-22:0":{"b": ["Красная армия вошла в Таллин — немецкие силы покинули город", "41ae1ec5"], "d": ["Во время Таллинской операции немцы покинули город; правительство Эстонского национального комитета, 18 сентября занявшее правительственные здания, не смогло удержать управление при вступлении Красной армии. Эстония вновь перешла под советское управление.", "a229e09c"]},
"OLAYLAR_EK16:1945-01-28:0":{"b": ["Красная армия взяла Мемель (Клайпеду)", "d01ad3dc"], "d": ["В советской операции, направленной на Восточную Пруссию и берег Балтики, порт Мемель (Клайпеда) был отнят у Германии и присоединён к Литовской ССР. Область, переданная в 1939 г. Германии, тем самым вышла из-под немецкого управления.", "65cf6a00"]},
"OLAYLAR_EK16:1945-05-08:0":{"b": ["Курляндский котёл капитулировал — Courland Army Group подписала капитуляцию перед Говоровым", "3c88889b"], "d": ["Немецкая Курляндская группа армий, с октября 1944 г. окружённая в районе Лиепая — Вентспилс, капитулировала; запад Латвии перешёл под советский контроль.", "a7bfcc52"]},
"OLAYLAR_EK16:1955-12-01:0":{"b": ["Войска султана Омана вошли в главные центры внутреннего Омана; ибадитский имамат фактически прекратил существование", "9a9962a5"], "d": ["В декабре 1955 года султан Омана предпринял шаги для восстановления своей власти, и его войска вошли в главные населённые центры внутреннего Омана (Бахла, Изки, Низва); власть ибадитского имамата над внутренним Оманом фактически прекратилась. Источник указывает только месяц; на карте показано 1 декабря 1955 года.", "31f8761e"]},
"OLAYLAR_EK16:1961-06-19:0":{"b": ["Кувейт вышел из-под британского покровительства и обрёл полную независимость", "e9a86d04"], "d": ["Обменом нотами между Кувейтом и Соединённым Королевством 19 июня 1961 года было прекращено британское покровительство, действовавшее с соглашения 1899 года, и Кувейт стал полностью независимым. На карте британский слой над Кувейтом заканчивается в этот день.", "eb64fb65"]},
"OLAYLAR_EK16:1971-09-03:0":{"b": ["Катар провозгласил независимость с окончанием договоров с Великобританией", "8f288cc6"], "d": ["После истечения срока договоров о покровительстве, заключённых с Великобританией, Катар 3 сентября 1971 года провозгласил независимость. На карте британский слой над Дохой заканчивается в этот день.", "997a4b35"]},
"OLAYLAR_EK17:1369-01-01:0":{"b": ["Крепости Истранджи: завоевание Pınarhisar, Кирк-Килисе (Кыркларели) и Визе", "c6b1a9c1"], "d": ["Мурад I, проведший зиму 1369 г. во дворце в Эдирне, весной вновь выступил против Византии и взял крепости Pınarhisar, Кирк-Килисе и Визе у подножия гор Истранджа. Эти завоевания вызвали панику в Константинополе, и император Иоанн V решил отправиться к папе за помощью.", "61aac0e3"]},
"OLAYLAR_EK17:1513-01-01:0":{"b": ["Пири-реис начертил древнейшую из дошедших до нас карт мира", "6ef941f5"], "d": ["Пири-реис в Галлиполи начертил карту мира, датированную 919 г. х. (1513 г.); по TDV İslâm Ansiklopedisi, среди источников карты были «древние карты, дошедшие до него из восточного и западного мира, и карта Христофора Колумба», то есть считается, что она хранит следы оригинальной навигационной карты Колумба, которая в то время считалась утраченной. Карту он представил Селиму I Грозному в Каире в 923 г. х. (1517 г.). До нас дошла лишь её часть, показывающая западные/атлантические берега (Испанию, Португалию, Западную Африку, восточный берег Южной Америки); эта часть была вновь обнаружена в дворце Топкапы в 1929 г. и входит в список ЮНЕСКО «Память мира».", "78561b0b"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["Объединение окрестностей Карса: переход Şüregel, Арпачая и Digor под османское управление", "10f16b5c"], "d": ["Во время Irakeyn Seferi крепости Пасин, Şüregel и Oltu перешли в руки османов; весьма вероятно, что и крепость Карс была присоединена тогда же. Область Арпачая и Digor к северу и востоку от Карса перешла под османский контроль в ходе той же операции.", "f8a4288a"]},
"OLAYLAR_EK17:1552-01-01:0":{"b": ["Расширение Алжирского оджака к Сахаре — обложение данью Тугурта и Уарглы, окончательное завоевание Тлемсена", "705ec920"], "d": ["Согласно статье TDV о Тлемсене, в 960 г. х. (1553 г.) большая армия, отправленная из Алжира под командованием Салих-реиса, окончательно взяла город и положила конец трёхвековой династии Зайянидов. В тот же период (1552 г.) Салих-реис организовал поход на независимые султанаты Тугурт и Варгла; османские силы взяли Тугурт, продвинулись к Варгле, оба султаната были обложены данью; в Бискре на пути был оставлен постоянный османский гарнизон. Так граница Алжирского оджака впервые перешла Телль-Атлас и дошла до сахарского берега. Большое сражение под Мостаганемом произошло не в этом году, а в 1558 г.: Хасан-паша разбил там испанского графа Алькаудете и положил конец испанским наступлениям в Северной Африке.", "da55aa7d"]},
"OLAYLAR_EK17:1557-01-01:0":{"b": ["Основание эялета Хабеш — берег Красного моря перешёл под османское управление", "7dd470ec"], "d": ["Эялет, созданный, чтобы не допустить проникновения Португалии в Красное море через Абиссинию, по статье TDV об эялете Хабеш был официально учреждён 15 шаабана 962 г. х. (5 июля 1555 г.), центром санджака стал Суакин. Оздемир-паша начал операцию осенью 1555 г.; он овладел островами Дахлак, контролировавшими порт Массава, а 2 апреля 1557 г. взял город Массава, затем Аркико. Продолжение завоевания шло переходом провинции Тигре под власть османов в 1558 г. и Дебарвы в 1559 г.", "7bb5b28b"]},
"OLAYLAR_EK17:1606-10-11:0":{"b": ["Седефкяр Мехмед-ага назначен главным архитектором — зодчий мечети Султанахмет", "27b66fce"], "d": ["Мехмед-ага, взятый ко двору по девширме в 1562–63 гг. из албанского городка Эльбасан, воспитавшийся при Мимаре Синане, 11 октября 1606 г. был назначен главным архитектором Османской империи. TDV İslâm Ansiklopedisi приводит слова современного источника, описывающего его как «кроткого нравом, скромного, верного слову, набожного и умного». Мехмед-ага, которому через три года по приказу Ахмеда I предстояло приступить к строительству мечети Султанахмет, оставил обширное наследие — от ремонтных работ у Каабы до множества фонтанов и мечетей в Стамбуле и Эдирне. Распространённое народное предание гласит, что шесть минаретов вызвали спор о «равенстве» с Каабой в Мекке; энциклопедические источники этого не подтверждают и характеризуют решение лишь как «не опробованное до того времени».", "a4c538fd"]},
"OLAYLAR_EK17:1617-11-22:0":{"b": ["Новый падишах Мустафа I: на троне узник «кафеса» с бледным лицом и рассеянным взглядом", "c487b0d1"], "d": ["Мустафа I, взошедший на престол после смерти Ахмеда I, как первый шехзаде, оставленный в живых братом, годами жил запертым во дворце под строгим надзором; TDV İslâm Ansiklopedisi описывает его как «бледнолицего, с редкой бородой, с крупными чёрными глазами и тусклым взглядом» и отмечает, что долгое заключение усугубило его психологическое состояние. Во время этого первого правления, продлившегося девяносто шесть дней, он не мог вести государственные дела; зато, по преданию, часто выезжал на охоту, осматривал верфь и даже бросал в воду золото, наблюдая за рыбами. Корпус янычар и улемы, сочтя его непригодным к правлению, 26 февраля 1618 г. низложили его и посадили на трон четырнадцатилетнего племянника Османа II.", "f2d36b20"]},
"OLAYLAR_EK17:1630-08-19:0":{"b": ["Путевой сон Эвлии Челеби — оговорка «Seyahat» вместо «Şefaat»", "2d863e22"], "d": ["По TDV İslâm Ansiklopedisi, Эвлия Челеби связывает начало своей сорокалетней жизни в странствиях со сном, который он видел в ночь ашуры месяца мухаррам 1040 г. х. (19 августа 1630 г.): во сне в стамбульской мечети Ahî Çelebi он видит Пророка в окружении большого собрания и от волнения вместо «şefaat yâ Resûlellah» говорит «seyahat yâ Resûlellah». По преданию, Пророк, улыбнувшись этой оговорке, обещает ему и заступничество, и странствия, и паломничество. Он никогда не женился и посвятил жизнь этому обещанию «странствий».", "ede1feb4"]},
"OLAYLAR_EK17:1632-01-01:0":{"b": ["Противоречия Мурада IV: падишах, пристрастный к вину, — запрет на вино, борцовская рука, слух композитора", "3d2ea5e0"], "d": ["В первые годы Мурада IV, взошедшего на престол в одиннадцать лет, определяющим было влияние его матери Кёсем-султан; TDV İslâm Ansiklopedisi сообщает, что Кёсем, опасаясь властных наклонностей сына, «направляла его к развлечениям, отвлекала подарками и празднествами». Когда примерно в двадцать лет он фактически взял управление в свои руки, это был высокий, широкоплечий, внушительный правитель — по преданию, он поднимал сильного человека за пояс и несколько раз проносил его по Has Oda. Поразительное противоречие, которое фиксирует TDV, таково: падишах, о котором говорят, что он ненавидел табак и опиум, чрезмерно пристрастен был к вину, однако перед походом запретил кофе, табак, а позднее и само вино; в то же время он обладал познаниями в музыке, достаточными, чтобы сочинять музыку по канонам макама.", "f2aba572"]},
"OLAYLAR_EK17:1632-01-01:1":{"b": ["Полёт Лагари Хасана Челеби на ракете — предание, единственным источником которого служит Эвлия Челеби", "1f02e3f2"], "d": ["По Seyahatnâme Эвлии Челеби, Лагари Хасан Челеби в присутствии Мурада IV на Sarayburnu соорудил из пятидесяти ока пороха семиствольное ракетное устройство и, сказав «Мой падишах, я поручаю тебя Всевышнему, иду беседовать с пророком Исой», сел на ракету. По преданию, поднявшись примерно на 250 метров, Хасан Челеби с помощью приспособлений, похожих на крылья сокола, спланировал в море, доплыл и вернулся к падишаху, а в награду получил сипахийство с жалованьем в семьдесят акче в день.", "ef620ef6"]},
"OLAYLAR_EK17:1638-12-24:0":{"b": ["Кеманкеш Кара Мустафа-паша стал великим визирем — началась эпоха финансовых реформ", "583846a4"], "d": ["Кеманкеш Кара Мустафа-паша, ставший великим визирем 17 шаабана 1048 г. х. (24 декабря 1638 г.) после гибели Таййар Мехмед-паши в Багдадском походе, при султане Ибрагиме проводил жёсткую финансовую дисциплину: сократил численность янычар и сипахов втрое, исправил пробу монеты, ужесточил систему нарха. По приводимой TDV цифре, эта экономия достигла 6000 кисе в год — но такой строгий контроль нажил ему врагов в придворной среде.", "2de299c2"]},
"OLAYLAR_EK17:1639-01-20:0":{"b": ["Мустафа I умер после пятнадцати лет забвения", "b4c872cd"], "d": ["Мустафа I, во второй раз низложенный 10 сентября 1623 г., все пятнадцать лет до самой смерти жил в комнате, где его держали взаперти; об этих годах в источниках нет никаких сведений. Он скончался 15 рамадана 1048 г. х. (20 января 1639 г.) — часть источников считает это естественной смертью, часть утверждает, что приложил руку Мурад IV.", "f153eced"]},
"OLAYLAR_EK17:1644-01-01:0":{"b": ["«Безумный Ибрагим» или волнообразная болезнь?", "2abc230f"], "d": ["TDV İslâm Ansiklopedisi прямо отвергает ярлык «Безумный Ибрагим», распространившийся в XX в.; он отмечает, что в собственных письмах падишах жалуется на боли, отсутствие аппетита, слабость в ногах, ощущение тумана в голове, стеснение в груди и приступы обморока. В то же время последовательные и разумные ответы в процессе низложения противоречат утверждению о постоянной неуравновешенности; делается вывод, что состояние султана «не было постоянным, а протекало с изменяющейся тяжестью». В этот период ответственность Кёсем-султан постепенно возрастала, а то, что приглашённый во дворец Джинджи-ходжа оказывал падишаху духовное утешение «действенными молитвами», усилило его возможность вмешиваться в политику.", "f3705d31"]},
"OLAYLAR_EK17:1647-01-01:0":{"b": ["Соболиный инцидент — меховой налог великого визиря Ахмед-паши подготовил конец Ибрагима", "a2a47d62"], "d": ["Пока увлечение султана Ибрагима собольими мехами и амброй при дворе росло, великий визирь Ахмед-паша около 1647–1648 гг. ввёл практику принудительного сбора с государственных чинов платы за соболий мех; TDV İslâm Ansiklopedisi отмечает, что чиновники видели в этом откровенную «дань». Когда офицеры-янычары коллективно отказались платить, это сопротивление стало прямым толчком к процессу низложения падишаха — собравшиеся утром 7 августа 1648 г. чиновники сначала убили Ахмед-пашу, а на следующий день низложили Ибрагима.", "596c6d08"]},
"OLAYLAR_EK17:1648-05-01:0":{"b": ["«Государством правят женщины» — восстание Варвара Али-паши из Сиваса", "5b027357"], "d": ["Бейлербей Сиваса Варвар Али-паша отказался платить 30.000 курушей, которые Стамбул требовал под названием «байрамийе», заявив, что «годового дохода Сиваса на эту сумму не хватит»; по TDV İslâm Ansiklopedisi, основанием его восстания было утверждение, что из-за нездоровья падишаха государственные дела перешли в руки женщин и что это вызвало нестабильность частой сменой наместников. Хотя в мае 1648 г. он сначала добился военного успеха, он был разбит Ипширом Мустафа-пашой, 20 мая 1648 г. казнён, а его голова отправлена в Стамбул.", "e45166db"]}
});
